/* 平成23年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h23.committeeSessions.push(...[{"id":"h23-20110606-5","meetingId":"h23-cm06","date":"2011年6月6日","dateIso":"2011-06-06","committee":"総務委員会","time":"午後１時０２分～午後４時５５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１、幹部職員紹介","agenda":"の１、幹部職員紹介","exchanges":[{"speaker":"阿部委員","kind":"意見","question":"民主・改革ネットの阿部祐美子です。どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":6,"id":"exchange-001"}]},{"id":"topic-02","title":"の２、事務事業概要","agenda":"の２、事務事業概要","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"それからインターエフエムなんですけれども、私もまだあまり認識として持てなかったんですけれども、平成１９年８月に開設ということなんですけれども、これをおつくりになった理由というのは、八潮でエフエムやしおというのがあって、八潮に住んでおられる何人かの方々がＦＭ放送が八潮の地域に限定して、電波ですから、ほかにも届くことはあるわけですけれども、そういうことをして八潮区内の。","respondent":"荒井広報広聴課長","answer":"それからまた現状の配布条件、つまり月３回の配布ということになりますと、コストが約１.８倍になるということもありまして、コストの問題と継続性あるいは、条件がよかったので１日で配布ができたんですが。","voiceIndex":56,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"それからモデル配布については、１回実施したのみということでいいんですかね。この郵送代が一定程度は経費がかかるという点で、いろいろ勘案してのこういう選択になったのかなとは思うんですけれども、その辺はどういうふうに１回の実施でこういうことに至ったのかというあたりがよくわからなかったので、そこがわかれば教えていただきたいと思います。","respondent":"荒井広報広聴課長","answer":"全く今後やらないかというと、そういうことでもなくて、現在の段階ではそういった確実に配布できるかというところを担保できないところが大きな原因になっておりまして、当面の間見合わせたいと考えているところです。","voiceIndex":58,"id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"最後に１つだけ。いろいろな意味での支援ですよ。財政的な支援だけじゃなくて、いろいろな意味での支援というのを１つでも大いにとっていただけるようにしていただきたいなと思っているところで、これは私の意見ですけれども、そのことを申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-004"}]},{"id":"topic-03","title":"の債権の放棄","agenda":"の債権の放棄","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今、何件かの説明があったんですけれども、債権管理審議会が年６回開かれる予定で、既に今年度は１回終了したという話なんですけれども、年６回ペースでやるとなると、きちんと手続しなくてはいけないのが相当あるんだなと思うんですけれども、その辺のボリュームがどうなのかと、それから、これらを放棄しましたと最後に会計管理者が説明されたんですけれども。","respondent":"福田会計管理者","answer":"二、三年は要するのではないかと思います。それから、今回、２２件諮問いたしました。そのうち１４件でありますので、残り８件につきましては継続審議という取り扱いになっております。それから、これは報告案件ですので、議会のご意見を求めるという趣旨のものではございません。","voiceIndex":65,"id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"そうすると、その審議会で放棄をするということでも、この１４件は品川区の手を離れていくわけですよね。そのあたりのことというのは品川区は、私はちょっと議事録を読んだんですけれども、あまりよくその辺のことがわからなかったので、どういう経過を経てこの審議会に乗っていくのかなという、その審議会前までのルート、経過を教えていただきたいなと考えています。","respondent":"福田会計管理者","answer":"確かに行方不明です。こういう説明を申し上げて、委員のご了解を得て、その意見を答申として私どもはいただきまして、その答申に基づいて放棄の決定をしたというものです。","voiceIndex":67,"id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"２２件かけて１４件で残り８件は継続だということなんですけれども、一つ一つ聞くつもりはないですけれども、大体今ご説明があったようなところに何らかの形で欠けるところがあると審議会として判断されて継続になったのかなと、説明を伺ってそういうふうに思ったんですけれども、残った８件というのは、継続の理由というのは大まかにどんな内容、どんなところが継続になった理由なんでしょうか。","respondent":"福田会計管理者","answer":"事務局が時間の配分を、もう少しスピーディーにできるだろうと、初めての審議会だったものですからそう読んだんですけれども、先生方が非常に慎重にご審議いただきまして、時間的に消化できなかったものが残ってしまったというものです。","voiceIndex":69,"id":"exchange-007"},{"speaker":"阿部委員","kind":"質問","question":"幾つか教えてください。１つ基本的なことなんですけれども、例えば道路占用使用料が自力執行権があって、公園占用使用料は非強制徴収公債権で、根拠が違ってということなんでしょうか。それを教えてください。それから、今後の審議の結果というのは、それぞれ報告が、あるいはオープンに見ることができるような状態になるんでしょうか。","respondent":"福田会計管理者","answer":"これは事前だけではありませんけれども、事前に必要な経営分析を行って、確かにその事業がほぼ間違いなく継続できるだろうという目で公認会計士に見ていただいております。打つべき手は打った上でやっているというご理解をいただきたいと思います。","voiceIndex":71,"id":"exchange-008"}]},{"id":"topic-04","title":"の区民参加による行政評価の実施","agenda":"の区民参加による行政評価の実施","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"一番下のところの評価対象事業の１０事業程度を選定するということなんですけれども、課題だとか関心度合いと書いてあるんですけれども、選ぶ基準というのがどういうふうになるのかなというのがわからないので教えていただきたいのと、それから、評価する時期が７月下旬から８月上旬ということで、随分日程的にはタイトじゃないかなという印象を持つんですね。","respondent":"久保田行財政改革担当課長","answer":"関係者の意見を聞く機会はですけれども、私ども特にこの事業につきまして、関係する団体や区民の方から意見を聞くという予定はございませんで、この行政評価委員会の中でご意見を伺いまして、こうした意見をもとに、それぞれ区のほうで予算編成にあたりましては。","voiceIndex":77,"id":"exchange-009"},{"speaker":"南委員","kind":"意見","question":"それとこの公募委員による行政評価していただいた結果がこうですよということで、ちょっと表現は必ずしも適切かどうかはあれですけれども、一定程度区民に評価というもののげたを預けてしまうみたいな、そんな感じで区民にとって必要な事業も縮小していく、あるいは廃止になってしまうこともあり得ると私は思うので、いろいろなテーブルの上だけの議論じゃなくて。","respondent":"久保田行財政改革担当課長","answer":"今回はそれにあわせまして、区民参加による行政評価を実施いたしまして、区民の視点に立った施策・事務事業の見直しを進めていきたいと考えているところです。","voiceIndex":79,"id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"１つ疑問なのは、公募区民、公募しますから、関心のある方が皆さん手を挙げて出てこられる。でも区内団体関係者の方は、関心があるなしにかかわらず、こちらで選ぶんでしょうか。言う場もあるはずです。だったら純粋に区民の方を私はすべて委員にするというのが筋だと思うんですが、なぜ区議会議員もここに入るのか、その根拠について教えてください。","respondent":"久保田行財政改革担当課長","answer":"その個別的な団体というよりも、区政全般から団体関係者の代表としての立場から、広く事業を見ていただきたいと考えておりまして、団体の関係者の方も区民委員として２名お願いしたいと考えているところです。","voiceIndex":81,"id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"それでなおかつこの中に入る必要があるのかどうかということと、もう１回あれなんですが、団体関係者とおっしゃいましたけれども、その方たちがぜひ参加させてくれということならば、それは今言ったお話はわかるんですが、こういう方は入らないとだめなんですよというんだと、ちょっと区民参加による行政評価という表題そのものが、私はちょっと言っていることが違うかと思うんですが。","respondent":"久保田行財政改革担当課長","answer":"区議会議員のほうですけれども、委員ご指摘のように委員会等がありますので、議員として意見を述べる場というものがあるかと思いますけれども、私どもこの行政評価委員会を進めるにあたりまして、より効率的に、また実りのあるものとしたいというところもありますので。","voiceIndex":83,"id":"exchange-012"}]},{"id":"topic-05","title":"の日曜開庁の取扱業務の拡大","agenda":"の日曜開庁の取扱業務の拡大","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"取扱業務が拡大することはいいことだと思いながら、２点教えてください。この拡大をすることによって、件数をどのくらいと見通されているのかということと、それによる人件費がどの程度と、件数がどの程度と考えられているのか教えてください。","respondent":"久保田行財政改革担当課長","answer":"それを８時間で日曜開庁でやりますから、１００件を超えるぐらいの件数が見込めるかなと考えているところです。","voiceIndex":89,"id":"exchange-013"},{"speaker":"原委員","kind":"質問","question":"日曜日にやっているんですけれども、非常にいいと思うんですけれども、この際、介護保険料の納付ということなんですけれども、実際には相談業務ですよね。その辺で来てしまうことはないんですか。やるかやらないかとかですね。","respondent":"久保田行財政改革担当課長","answer":"実際の介護保険料に関しては、件数はそう多くはないのかなと見込んでいるところでございまして、ただ窓口のほうに来てお支払いしたいといった方がいた際に、先ほども言いましたように、ほかの窓口を案内するのも本家本元の区役所でどうかというところがありますので。","voiceIndex":91,"id":"exchange-014"},{"speaker":"南委員","kind":"確認","question":"職員体制についてはことさら増やさなくてもできるという説明がさっきあったのかどうか、もしあったらあれなんですけれども、確認をしたいと思うんですけれども。それと戸籍住民課の事務スペースと書いてあるんですけれども、３階からこう入って右のほうに行ってさらに右に行くと戸籍住民課のスペースがありますよね。そこのところで今までやっていたのとこれからのこれを加えてやるという認識でいいんですか。","respondent":"久保田行財政改革担当課長","answer":"その間ぐらいにあるんですけれども、そこのところを活用して、税務のほうの事務も入れさせていただいて、その中ですべて行っていきたいと考えております。","voiceIndex":93,"id":"exchange-015"},{"speaker":"南委員","kind":"質問","question":"住民サービスの利便性が増えるという点では評価できるんじゃないかと思うんですけれども、一方で節電というのがあって、日曜開庁は今までもずっとやっていたのであれですけれども、その辺の考え方というのは矛盾するところはないんですか。普通の出先については閉館をしていくという計画が結構ありますよね。","respondent":"久保田行財政改革担当課長","answer":"日曜開庁と節電、区民の利便性と節電というものを考慮いたしまして、引き続き日曜開庁のほうは行っていきたいと考えております。","voiceIndex":95,"id":"exchange-016"},{"speaker":"南委員","kind":"確認","question":"要するに区民サービスを減らさないために、拡充、利便性を上げていくという点で、節電とは切り離して開庁し、業務も拡大していくという意味でいいんですかね。確認です。大事なことだと思うので。","respondent":"久保田行財政改革担当課長","answer":"日曜開庁を行う中でも節電というものは十分行ってまいりますし、そうした中では、節電という意味では、区としても２５％削減ということで積極的に取り組んでいるところですので、日曜開庁というところでは節電も取り組んでおりますし、またその中で。","voiceIndex":97,"id":"exchange-017"},{"speaker":"須貝委員","kind":"質問・要望","question":"日曜開庁で取扱業務の拡大についてはありがとうあります。区民の職業形式が多様化していく中で、区民の要望は我々が接していても高いものがあります。少しずつですが広げていっていただいて、区民の利便性、これで助かる人が相当出てくると思いますので、今後も努力してやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-018"},{"speaker":"鈴木委員","kind":"確認","question":"かぶりますけれども、もともとやっている中の話なので、今まで証明書を発行したときには手数料をもらっているから現金が動いていますよね。この現金というのは、日曜日が終わった後の処理はどうしていたのかなということを、今、急に思ったのが１点。対外的に持っていった場合に、曜日が出ていないから、品川区の発行した曜日が日曜日だよなんてことで、今までそういう確認をされたということはないのか。","respondent":"久保田行財政改革担当課長","answer":"他の自治体におきましても日曜開庁等を行っておりますけれども、全部の区に聞いたわけではございませんが、今回、検討する中でいろいろお話を聞く機会がありましたけれども、そういったことで日付がどうのという話は出なかったと記憶しています。","voiceIndex":100,"id":"exchange-019"}]},{"id":"topic-06","title":"の品川区における電力節減対策の概要","agenda":"の品川区における電力節減対策の概要","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"今回の２５％という非常に大きな目標で節電をしていかなければならないということで、大変なご努力が必要というふうには前提として認識をしておりますけれども、節電ということで一律にとにかく２５％、削れるところから削るという考え方ではなくて、ピーク時にどれだけ減らすかということがポイントであって、あまり使っていないときに一生懸命節電しても、逆に自粛、自粛のムードばかりが広がってしまって。","respondent":"諸岡危機管理室長","answer":"一時、夜間については比較的大丈夫ではないかというお話が出ておりましたけれども、東電もパンフレットあるいは説明、それから国の説明等について若干誤解がされていたということがございまして、我々夜の８時ということですが。","voiceIndex":106,"id":"exchange-020"},{"speaker":"塚本委員","kind":"質問・要望","question":"私も知らなかった事情が今わかったのですけれども、とにかく例えば街路灯につきましても３割、１０本あるうち３本ずつとめていくとかいうことではなくて、その現場に住んでいる方にとっては、ここは防犯上つけてほしいとか、そういう要望が区民の方々、全部聞いていたら大変だと思いますけれども、ありますので、極力弾力的にというか、臨機応変にというか、あまり気分が下にいかないような形で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-021"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、それをぜひ教えていただきたいと思います。その辺を教えていただきたいのと、改めてコンセプトを教えていただきたいなと思います。","respondent":"諸岡危機管理室長、桑村総務部長","answer":"１つは公園の街路灯等の、特に道路につきましては３割削減ですが、これは基本的には３割なんですけれども、一律ということではなく、道路公園課のほうで現場の状況を判断しながら、同じ明るさでも。それも土日は抜いた形で考えようということで、たまたま８月１０日が当たっているということで、一定の休館日というのと、１１日から１９日の間は確かにお盆の季節なので、正直言って、所管課のほうの検討では、あまり利用がないので。","voiceIndex":109,"id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、品川区が最低でも１５％で、２５％を目標にと、そのことは私は理解していただけていると思うんです。ですから、確かに節電は大事だし、お盆の期間の利用が少ないということで設定されたと。それとあともう１つ、先ほどの日曜開庁との関係で伺ったんですけれども、業務拡大、住民サービスと節電との関係ですけれども、住民サービスはしていきたいと。いかがでしょうか。","respondent":"桑村総務部長","answer":"区民集会所等につきましても、区民がご利用のところですから、利用しているときに節電を長くかけづらいものですから、どうしてもお休みの期間を入れするということにしないとなかなかできないものですので、一定のご不便をかけますけれども、区民集会所の場合は８月。","voiceIndex":112,"id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"消しているからどこも真っ暗なんですけれども。さっきも申し上げたとおり、１階だけは使っていただけるけれども、２階、３階はご遠慮いただきたいとか、そういうことも含めて、ぜひ検討をしていただきたいと私は思うんですけれども、その余地も全くないほど、区の認識というのはそういうふうになっているんでしょうか。","respondent":"諸岡危機管理室長","answer":"ただやはり基本的な節減対策ですので、ぎりぎりのところまで節減をするという方針です。それから区民集会所ですが、一部について開館するということになりますと、基本的に空調を動かすということで非常に効率が悪くなってしまいます。","voiceIndex":114,"id":"exchange-024"},{"speaker":"須貝委員","kind":"質問・要望","question":"毎週火曜日なら火曜日、水曜日なら水曜日、定期的に使われている方が、１カ月にその１週とちょっと、月で言えば１回または１、２回ぐらいの休館日を設けられて、皆さんが使わないとき休館するということで、私はこういうほうが効率的にもいいんじゃないかと考えます。ただ１点だけちょっとお願いがあるんですが、今、報道なんかでひったくり等の犯罪が増えている。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-025"},{"speaker":"阿部委員","kind":"質問","question":"２点ほど伺いたいと思います。各施設の性格にもよると思うんですけれども、そのあたりへの配慮というのはある程度検討されたのかどうかということが１点です。それから集会所についていろいろ出ていますが、利便性というよりまさに節電という意味から考え方を伺いたいんですけれども、１カ所に集まるほうが実は消費電力が少ないという面もあると思うんですね。その辺の考え方というのはいかがですか。","respondent":"諸岡危機管理室長","answer":"２点目の節電の関係で、１つの施設に皆さんに集まっていただいたりという、そういう考え方もないわけではありませんし、またそれをやりたいという区もあると報道等に出ておりますけれども、ただ実際、さっき委員からもお話がありましたように、そのとおりに。","voiceIndex":117,"id":"exchange-026"},{"speaker":"阿部委員","kind":"質問","question":"１つ目の弱視等々の方々、もちろんお申し出があれば対応してくださると思うので、それは逆に行政側から呼びかけるということもあってもいいのではないかと。不便に感じている場所があったら教えてくださいぐらいのお声がけはあってもいいのかなと思います。２つ目のほうについては、確かに意見が分かれるところだと思います。どこかで実験ができるとおもしろいですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-027"},{"speaker":"金野副委員長","kind":"意見","question":"ここで休館というのを設けていないのはどういうことなのかなというのが１つ。そこで防犯ということも考えて、区としては危機管理というか、どのようにこれをしていこうとしているのか、また対応は今どうしているのかという、この２点をお願いします。","respondent":"諸岡危機管理室長","answer":"品川歴史館の対応ですけれども、品川歴史館は現状でも週１回定例的な休館日があります。さらに休館日を設けるとなるとかなり休館が多くなってしまうので、それは考えていないです。館内の展示物の保管等によりまして、照明をそれほど明るくしておりません。","voiceIndex":120,"id":"exchange-028"},{"speaker":"金野副委員長","kind":"質問・要望","question":"比較のデータが私の手元にないのでわからないんですが、そうなると、もっとここは節減できるのではないかと思うのですが、どうでしょうか。この期間だけは我慢してくださいねというところも区民の皆さんは理解できなくはないんでしょうけれども、そうしたところのことも考えて、防犯ということをいま一度警察等と連携をとって、パトロールの強化というところもしていただきたいと、これは要望です。","respondent":"諸岡危機管理室長","answer":"子どもたちの自由研究の場としても活用されているところです。したがいまして、開館をしながら、その間、事務室等の照明を極力落としたり、落とせるところは節減を図りながら開館していきたいと考えているところです。","voiceIndex":122,"id":"exchange-029"},{"speaker":"須貝委員","kind":"質問","question":"細かに報告いただきましてありがとうあります。１点お聞きしたいのは、総合区民会館の小ホール、ここだけ契約の相手方が東京都新宿区ということで、専門のところなのかと思うんですが、一応なぜなのかということをお聞きしたいと思います。","respondent":"阿部経理課長、宍戸施設整備課長","answer":"そういうことで、区外にも広げましてやったところ、１２ページに記載のとおり、区外の業者だけが応募してきたという状況です。建物の駆体、設備関係あるいは外壁ですとか防水や何かを更新するという前提で、駆体関係は６５年もつと言われていまして、今回耐震改修をすることによりまして、２０年から２５年はこれから使っていただけると考えられるわけです。","voiceIndex":130,"id":"exchange-030"},{"speaker":"原委員","kind":"確認","question":"今、ご説明があったんですけれども、コンクリートが４０年で、あと２５年ぐらいは大丈夫というお話なんですけれども、通常、民間ですと、逆にコンクリートは４０年ということなので、古いところに補強をした形で、もう１回確認で、２５年大丈夫だということなのか、お伺いします。","respondent":"宍戸施設整備課長","answer":"ただ部位・部体ごとの耐用年数ということで言えば、杭ですとか、コンクリートの駆体ですとか、鉄骨造も含めて６５年ということは、国のほうでいろいろ調査したものでもそういう取り扱いですので、設備関係あるいは外壁、繰り返しになりますけれども。","voiceIndex":133,"id":"exchange-031"},{"speaker":"鈴木委員","kind":"確認","question":"確認なんですけれども、総合区民会館小ホールですけれども、これは舞台装置はその間使えるのかな。そこがわからなかったので、小ホール自体が休館になるのか、それとも開館したまま夜間の工事なのか、そこだけちょっと教えてください。","respondent":"阿部経理課長","answer":"今回の工事につきましては、集中的にある一定の期間を閉めまして、これは２度ほどありますけれども、その中で工事を行って、基本的にはあけるということです。具体的には、７月から８月の期間を閉めるです。７月２５日から８月２６日まで閉めます。","voiceIndex":136,"id":"exchange-032"},{"speaker":"鈴木委員","kind":"質問","question":"きゅりあんで調べてもらったので、休館になっているという状況はもう伝わっているんですよね。１月の分も休館ということで出ているということでいいわけですか。","respondent":"宍戸施設整備課長","answer":"その辺はきゅりあんと綿密な打ち合わせをした上で工事の予定を立てたものです。","voiceIndex":138,"id":"exchange-033"},{"speaker":"鈴木委員","kind":"意見","question":"要するにきゅりあんの利用者の方にその辺を周知していればいいのかどうか。その辺、していなければいけないということをお願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":140,"id":"exchange-034"},{"speaker":"阿部委員","kind":"質問","question":"純粋に数字だけを見た話をするんですけれども、区外業者が入札に参加されている小ホールの舞台機構改修については、９３.８％、区内業者については、これだけじゃなくて、ほかの契約も非常に多いんですけれども、９９％程度になるという、純粋にこの数字だけを見ると、区内業者優先という方針が、長期的に品川区にとって本当に唯一の正しい選択なのかどうかと思わされてしまうし、区にとってだけではなくて。","respondent":"阿部経理課長","answer":"たまたま今、申し上げた、例えば９９とかというふうになっただけであって、制限付き一般競争入札につきましては、大体９２％ぐらいが平均の落札率ですので、委員がおっしゃった総合区民会館、大体その程度だということで。","voiceIndex":141,"id":"exchange-035"}]},{"id":"topic-07","title":"の庁舎駐車場等の貸付","agenda":"の庁舎駐車場等の貸付","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"仕組みをもう少し教えてください。駐車料金は直接このアマノマネジメントサービスの収入となるということなんでしょうか。区は７２万円の貸付料をアマノから受け取るわけですよね。アマノはその駐車料金、２時間を超えた分がアマノの取り分になるのでしょうか。この理解はおかしいのかしら。そうすると、無料処理分を発行すればするほど、アマノの取り分が少なくなる。","respondent":"阿部経理課長","answer":"今までも１時間４００円というものはいただいておりました。というのは、区役所にいらっしゃらないで利用なさる方がいますので、その方は最初から有料です。今までもそのような形で、年の収入として１,１００万円程度、第一駐車場と第二駐車場でありました。","voiceIndex":147,"id":"exchange-036"},{"speaker":"阿部委員","kind":"質問","question":"そうすると、この月額７２万円という積算根拠と、処理をする機械なんかも、それはアマノ側ということになるんでしょうか。","respondent":"阿部経理課長","answer":"７２万円ですけれども、これはアマノからの提示です。プロポーザルの中で、運営方法なんかと同時に、区への貸付料を幾らにしますというのを同時に提示を受けていますので、７２万円というのはアマノのほうからの提示の金額です。今、委員おっしゃったとおり、精算機ですね。","voiceIndex":149,"id":"exchange-037"},{"speaker":"阿部委員","kind":"質問","question":"これは貸付であって、特に指定管理制度を使ったりという手法ではないんですね。契約期間とか、もしかすると、この期より前にご報告が総務委員会であったのかしら。どういう形でプロポーザルをどのくらいから受けたのかとか、ちょっと概要を教えていただいていいですか。","respondent":"阿部経理課長","answer":"これは行政財産貸付という方式でやります。これは自治法の変更もございました。従来は行政財産の貸付というのは、ある特定の、例えばＵＲとか、そういう特定のところにはできて、民間にはやれるという条項がなかったんですね。","voiceIndex":151,"id":"exchange-038"},{"speaker":"阿部委員","kind":"質問","question":"これまでの方式から今回の貸付という形にすることによって、区にとってどのようなメリットがあるのか、仕組みの面、それから収入の面でどういったメリットがあるのか教えてください。","respondent":"阿部経理課長","answer":"もう１つは、それぞれの保守管理がありますから、そういう経費ももろもろかかってまいります。ですから、今回、貸し付けることによりまして、収入自体は若干減りますけれども、そういう維持管理費がかなり減る、１,２００万円ぐらい減るということになります。","voiceIndex":153,"id":"exchange-039"},{"speaker":"鈴木委員","kind":"質問","question":"最後の案内係の方は、先方じゃなくて、区のほうで今までどおりやっていただくということでいいわけですか。","respondent":"阿部経理課長","answer":"そのとおりです。案内係は今までもいましたけれども、区のほうで直接委託するという形です。","voiceIndex":155,"id":"exchange-040"},{"speaker":"鈴木委員","kind":"質問","question":"割引認証機という件が出ているんですけれども、これは窓口に用事があった場合、そのカードをもらっていますけれども、それをなしで、直接認証機に行っちゃえばいいということになるわけですか。","respondent":"阿部経理課長","answer":"今ですと普通のカードで入れる形ですけれども、今回は発券します。入る時に券を発行します。今で言う駐車場と同じやり方です。磁気カードになっていますので、先ほど４台ぐらい各フロアにおくと言いましたけれども、そこで職員に渡してやってもらうという形になります。","voiceIndex":157,"id":"exchange-041"},{"speaker":"鈴木委員","kind":"質問","question":"機械にだれかがついているというか、何のために来たかは証明しなければいけないのか。というのは、逆に言うと、何も用事がなくても、認証機だったら、例えば住民票を発行してもらったらそれをもらったよという証明が今まではありますよね。もしそのままなしに認証機のところに行っちゃったとき、ただ２時間使える状況になり得るんじゃないかという気がするんですけれどもいかがですか。","respondent":"阿部経理課長","answer":"現在も、例えば何カ所かにいらっしゃる場合は、どこどこに行ってきたからというんじゃなくて、最近のところでもらう形になっています。それは２時間券でも１時間券でも。ですから、基本的にはやり方は変わらないです。","voiceIndex":159,"id":"exchange-042"},{"speaker":"鈴木委員","kind":"質問","question":"質問が悪かったかもしれません。何も用事がないのに、事務的に何もしていないのに、この認証機のところに行って、何かやってきたよということは言えればただになってしまうのではないのという、悪く考えたわけです。そういう形が出るケースが今後あるんじゃないかなという気がするんですが。","respondent":"阿部経理課長","answer":"そういう長期の方というのはほとんど区役所に用事はない方だろうと考えています。そういう方も今回利用制限をかけてしまおうですので、委員おっしゃる方が皆無になるとは思っていませんけれども、今まで以上はかなり効果的だろうと考えています。","voiceIndex":161,"id":"exchange-043"},{"speaker":"鈴木委員","kind":"質問","question":"窓口に行って、窓口でカードをもらうわけじゃないから、自分で現金を払うじゃないですか。ところが今度のケースでいくと、少なくとも２時間までは、窓口に行かないで、カードで通っていっちゃう可能性がある。もらいにくいから、今度はその作業がないということは、２時間無料にできちゃうようなケースが発生するんじゃないかなと、そっちはどうなんでしょうか。","respondent":"阿部経理課長","answer":"委員おっしゃるように、そういう方もいらっしゃると思います。そういう方はどういうやり方をとっても、基本的には管理できないだろうと考えていますので、今申し上げた長時間をこれからは、皆さんのご利用を是正していくという形で、今回のような形を導入するです。","voiceIndex":163,"id":"exchange-044"},{"speaker":"阿部委員","kind":"意見","question":"処理機のイメージ、その機械のイメージなんですけれども、廊下のところにぽっと置いてあって、だれでも差し込めるということではなくて、例えば職員の側にあって、職員の方に渡して、それを機械を通して行う。そういうイメージでよろしいんですね。","respondent":"阿部経理課長","answer":"それは逆に言えば、今月の早い時期に職員の説明会をしますので、そのときまでは決めておかなければいけない話ですので、確かに自由に通せたほうが使い勝手としてはいいとは思いますけれども、２時間を超えたときにどうかというのは。","voiceIndex":165,"id":"exchange-045"},{"speaker":"原委員","kind":"質問・要望","question":"１点目が、アマノマネジメントサービスの概略を教えていただきたいというのが１つ、それから２つ目、案内係がいるということなんですけれども、そうすると、機械的にはアマノがやっている。何を言いたいかというと、管理者責任の問題がないとは言えない。その点についてお伺いします。","respondent":"阿部経理課長","answer":"駐車場の機械については、すべてアマノが設置して管理責任は全部いる形。例えば精算機にはバーもつきますので、それの責任も全部アマノという形になります。そういう責任の分担です。","voiceIndex":167,"id":"exchange-046"},{"speaker":"原委員","kind":"質問","question":"１点目、会社のほうはわかりました。機械関係、そうだろうなと思いましたので、了解いたしました。２つ目なんですけれども、案内係というのは、そうすると、今までどおりの解釈でいのかな。責任が発生してしまったりするものですから。そこだけもう１点ご説明いただければ。","respondent":"阿部経理課長","answer":"あくまでも案内係というのは、先ほど申し上げたとおり、出入り口の車と歩行者の方の安全確保ということだけですので、中に入ってから案内をするという形はございません。車の方があいているところにとめて、用務が終わったら出ていくという形になります。","voiceIndex":169,"id":"exchange-047"},{"speaker":"原委員","kind":"質問","question":"そうすると、具体的に区が案内係の人を配置するということなんですけれども、そうすると、人数的に、延べ人数でもこれでもいいんですけれども、減ってくるという解釈でよろしいんですか。","respondent":"阿部経理課長","answer":"先ほど申し上げましたけれども、人数が減りますので、その分、経費も少なくなってくる。先ほどのような効果が出てくるということです。","voiceIndex":171,"id":"exchange-048"},{"speaker":"南委員","kind":"確認","question":"だから今で言うと、第二駐車場だと、あそこのスロープをずっと上がって、１６３号線に出る、あそこのところに１人配置している。２カ所に配置するということですよね。今の質疑を聞いていてちょっとわからなかったので確認したいんですけれども、それにプラス品川区があそこがあいていますよと案内する人を置くということになるんですか。そんなふうに理解したんですが。","respondent":"阿部経理課長","answer":"ですから中には、ここがあいていますからここですという、今はやっていますけれども、そういう人をこれからは置きません。ですから発券機から中に入って、あいているスペースを見つけてもらって、用務が終わったら出ていく。これは運転者の方の責任という形になります。","voiceIndex":173,"id":"exchange-049"},{"speaker":"南委員","kind":"質問・要望","question":"この第一駐車場が２５台、第二のほうが９７台で、中小企業センターを含んでそういうことになるわけですけれども、この台数というのは、工事が始まる前の台数と同じなんですか。増えたのか減ったのか、変化がもしあれば、それを１つ教えていただきたいのと、あとプロポーザルをされたというんですが、４社。そのプロポーザルのときの条件というのが何だったのか、改めて伺っておきたいと思います。","respondent":"阿部経理課長","answer":"使い方としては、民間の駐車場と基本的に変わりませんので、委員おっしゃったような車高の高い車がどうかということは、それほど私のほうでは心配をしていないところです。もう１点、プロポーザルの実施のことですけれども、これにつきましては、今申し上げたのは台数ですね。","voiceIndex":175,"id":"exchange-050"},{"speaker":"南委員","kind":"提案","question":"台数についてはそんなに大きな変化はないということなんですが、ちょっと確認なんですけれども、前は第一駐車場の下に地下の駐車場があって、庁有車は大体そこが車庫になっていたと思うので、第二駐車場のこの９７台の庁有車を含むというのは、これは大半が区民の来庁された方の利用に提供されると考えていいんですか。","respondent":"阿部経理課長","answer":"プロポーザルの結果ですけれども、実績と、あと先ほど申し上げた運営状況ですね。そこは２社ぐらいが同じ点数でございましたけれども、貸付料がかなり違っておりましたので、最終的には運営方法と安全確保あるいは貸付料、総合的に判断をしてアマノに決めたです。","voiceIndex":177,"id":"exchange-051"},{"speaker":"南委員","kind":"確認","question":"最後にちょっと確認なんですけれども、地下駐車場に庁有車が入るということで、第二駐車場の９７台については、この数字全部かどうかは別としても、大多数が庁有車を含まないというふうに利用していただけると考えていいんですかと質問したつもりなんですけれども。","respondent":"阿部経理課長","answer":"先ほど庁有車を含むという説明をしたと思うんですが、ただしその庁有車の駐車スペースを特定してございません。そこまで出ていけば、今度は一般の方も入れるという形になりますので、９７台というのはそういうものも含めた９７台です。","voiceIndex":179,"id":"exchange-052"},{"speaker":"南委員","kind":"意見","question":"わかったんですけれども、第二駐車場に置いていた、置かなくてはいけなかった庁有車については、第一駐車場の地下には入らないで、第二駐車場に置いていた部分があったということですね。いいです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":181,"id":"exchange-053"},{"speaker":"須貝委員","kind":"質問・要望","question":"そのときに、どこがあいているんだろうというときに、迷われる方も私は出るんじゃないか。そこら辺は工夫していただいて、今まで工事中で多くの区民の皆さんにご迷惑をおかけしたんですから、少なくとも当面の間、区民サービスとして、利便性も考えて、しばらく案内者を中に置いておくということも、私は考えていいんじゃないかと思うんですね。確かに費用が削減されるということはわかります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":182,"id":"exchange-054"},{"speaker":"鈴木委員","kind":"意見","question":"前は第一駐車場から第二駐車場に抜けられる、一方通行になっていて、中を抜けられましたね。今度はそれはどうなってしまうのかなというのが１点と、それから今、庁舎の前のコインパーキングを借りている分、これは７月１日からなくなるのかなと思うんですけれども、そうすると、そのことがどういうふうに、区民の方で今来て、結構あそこに入れているんですね。","respondent":"阿部経理課長","answer":"もう１点目の提携駐車場のことです。それもＰＲを当然していかなくければいけないだろうと思っていますので、先ほど申し上げましたけれども、ＰＲの仕方の中で、それを十分配慮しながらやっていきたいと考えています。","voiceIndex":183,"id":"exchange-055"}]},{"id":"topic-08","title":"の４、その他","agenda":"の４、その他","exchanges":[{"speaker":"塚本委員","kind":"意見","question":"都区制度のあり方については、前年度の中で一定の形というか、今後議論する上で何か出てくるのを待たなければいけないとか、そんな状況になっているという話も出ているんですけれども、そういう意味においても、継続ということで、今年度においても所管事務としてやっていくほうがいいのではないかと思います。とりあえずそれだけ。その他につきましては、また別途文書で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":190,"id":"exchange-056"},{"speaker":"南委員","kind":"質問","question":"ですから、総務委員会をやらないで競馬の視察だけというふうになるのであればともかく、総務委員会をやるのであれば、私自身も責任を果たすという点では困ったなと考えていますので、その辺、先に日程が先方との関係で出てきているという点では、改めて変更を含めてお願いできないのかなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":193,"id":"exchange-057"},{"speaker":"南委員","kind":"提案","question":"私はあまり総務委員ってやったことないんですけれども、何回かやった中で、ナイター競馬に参加するのについて、委員長のほうから実施したらどうかというふうに伺うということは初めてだったと思うので、大変丁寧ややり方をされるんだなと思っていたんですけれども、そうであるならば、日程が先にポンと出てきちゃって、それにぜひ合わせていただきたいという運営というのは。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":195,"id":"exchange-058"},{"speaker":"鈴木委員","kind":"質問","question":"日程の問題は、逆に言うと、委員また理事者も含めていったら、何十人の中での設定ですから、その日程を今、ここで質疑しても進まないんじゃないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":196,"id":"exchange-059"},{"speaker":"南委員","kind":"提案","question":"だけど、そういうふうに総務委員会として設定して、そこに本場区なんだから行きましょうということであれば、万難を排して参加するようにしなくてはいけないんですけれども、何か提案の仕方が逆じゃないかなと思うので、そうであるならば、ちょっと申しわけないんですけれども、日程が全然私はとれないところなので困ったなと思って。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":197,"id":"exchange-060"},{"speaker":"阿部委員","kind":"質問・要望","question":"委員会として開かれるのであれば、議員の立場では最優先と思いますので、ぜひできるだけ早く設定していただきたいという要望です。それからもう１つ、競馬場なんですけれども、今回の震災でかなりいろいろハード面での影響があったと聞いております。視察でそういうところももし見られればと考えていますので。","respondent":"伊藤委員長","answer":"それも踏まえた上で検討していただきまして、次回以降の委員会の中でそういう場を設けていきたいと考えていますので、よろしくお願いいたします。","voiceIndex":198,"id":"exchange-061"},{"speaker":"須貝委員","kind":"質問・要望","question":"行政視察ありきじゃなくて、これが何もない平時ならば、今、これからどこへ行く、何をしようという、勉強したいということも考えるということは必要だと思いますけれども、だれが見ても今、非常時なときに、果たして行政視察ということで、ほかの自治体を訪れて、確かに勉強も大事だと思うんですけれども、私は今はそれこそ委員会として自粛すべきときではないのかなと思うんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":200,"id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1882#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":72365,"voices":201}},{"id":"h23-20110607-14","meetingId":"h23-cm06","date":"2011年6月7日","dateIso":"2011-06-07","committee":"行財政改革特別委員会","time":"午後１時０３分～午後２時２０分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"初めに、指定管理・民間委託の状況について伺いたいんですけれども、先ほど現状についてのご説明ということですけれども、業務委託と指定管理者がそれぞれありますけれども、契約の内容について現状をお伺いしたいと思うんです。","respondent":"久保田行財政改革担当課長","answer":"それぞれの施設によって、どういう取り組みをしているかというところは、私ども、把握してございませんけれども、一般的な考え方でいいますと、やはり指定管理を受けている事業者にとりましては、公の施設を管理しているというところがありますので。","voiceIndex":28,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"私、震災には触れないように気をつけたいと思うんですけれども、火災、災害、大震災、きちんとした対応をされているというご説明ですけれども、それは契約事項に入っているのか、要するに、契約を結ぶときなのか、それとも、もし結んだ後にやるのであれば、どういう仕組みになっているのか、当然何らかの対応が当然されているんだろうなとは思うんですけれども、今のご説明ですと、区と協議して。","respondent":"久保田行財政改革担当課長","answer":"その公表の時期等につきましては、私どもとしましては、決まった段階でできるだけ速やかに説明してもらいたいということをお話ししてございまして、ＴＯＣとしても、速やかに工事に着手していきたいという意向を確認していますので、時期が来ましたら。","voiceIndex":30,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"どういうことなのかと単純に思うんです。その辺について伺いたいと思います。最後に、自動車駐車場スペースのこと、実態調査のご説明がありましたけれども、よくわからなかったのは、間違っていたら教えていただきたいんですけれども、この庁舎に区民の方が用事で車で来たときに、当然車をとめますけれども、庁舎を利用したということになると、無料になるじゃないですか。","respondent":"久保田行財政改革担当課長","answer":"ＴＯＣといたしましても、株主等への説明等の責任もありますので、公表の時期というのは非常に慎重にタイミングを図っているというところもございまして、ＴＯＣとしても速やかに工事を進めていきたいという意向は変わってございませんので、時期が来ましたら。","voiceIndex":32,"id":"exchange-003"},{"speaker":"中塚委員","kind":"意見","question":"自動車駐車場のことですけれども、利用者の利便と、なぜそこでお金を取るのかということの関係になるわけですけれども、ここがよくわからないんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":34,"id":"exchange-004"},{"speaker":"中塚委員","kind":"意見","question":"要するに、冒頭の説明の法律が変わって、取ることができるようになったという説明がありましたけれども、なぜそれでこれを導入したのか、そこがよくわからないので、区の判断でやるわけですよね、できるようになるということは。取られるほうにしてみれば、困るわけで、今の話だと、ちゃんと利用者、ありましたけれども、考え方をご説明いただけますか。","respondent":"桑村総務部長","answer":"これは、場所によって考え方がいろいろあったんだと思うんです。この庁舎も正直言って、初めは無料だったわけです。","voiceIndex":36,"id":"exchange-005"},{"speaker":"渡辺委員","kind":"質問・要望","question":"質疑ではないんですが、進行のことで確認だけ、今、３点の資料をもとにご説明をいただいた中で、そのまま質疑だと、もちろん概要という中で、大くくりの質疑と考えてもいいんですが、今のように細部にわたると、テーマがそれぞれかなり違うものが一括してはちょっと難しいかなと。委員長に聞いてしまうわけではないんですが、進行について皆さんに意見を求められてもいいのかと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-006"},{"speaker":"渡辺委員","kind":"確認","question":"逆に順番がどっちかという……。もちろん今、概要について、細かくない部分では伺うことが可能であれば、先にそれを伺うというのもあるなと、その確認だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-007"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"業務委託と指定管理とがあるんですが、先ほど少し説明で、規模の違い等で業務委託にするか、指定管理にするかという違いの部分の説明だったんですが、業務委託と指定管理、例えば、違いの中で、金額の歳出の違いがあるのか、また、責任の重みといった部分が、業務委託と指定管理で違いがあるのか、その辺の、業務委託と指定管理。","respondent":"久保田行財政改革担当課長","answer":"そうした中で、例えば、使用の承認とか、利用料金の徴収もするですので、そういった意味では、業務委託とは大きく違うところでございまして、それだけ責任も重いですし、それぞれの施設の管理に対しての責任や管理業務に対してのきちんとした対応が求められるといったところです。","voiceIndex":42,"id":"exchange-008"},{"speaker":"石田（慎）委員","kind":"意見","question":"区として今後の施設のあり方の中で、これから業務委託と指定管理をこのままの状況でやっていくのか、それともある一定の指定管理の方向で進んでいきたいという思いがあるのか、それとも業務委託でやっていきたいという、その未来像というか、区のお考えを再度お聞かせいただければと思います。","respondent":"久保田行財政改革担当課長","answer":"指定管理につきましても、そういった効果が見込まれるものについては、指定管理制度を導入して、施設の管理を行っていきたいという考えです。","voiceIndex":44,"id":"exchange-009"},{"speaker":"渡辺委員","kind":"質問・要望","question":"それと経費の点も、当然コスト面を考えられると思うんですが、今世の中全般で、効率性を求め過ぎたという検証がさまざまな場面で出てくるかと思っています。そういったところを、これはもう方向性だけ伺えればいいと思うんですが、今どのような考え方をお持ちか伺いたいと思います。","respondent":"久保田行財政改革担当課長","answer":"専門性もありますので、そういった中で適切な指定管理者を選んでいくといったところを考えてあります。その中で、評価等も加えながら、指定管理制度を有効に活用しながら、サービスの質を維持しながら、施設管理のサービスを提供していきたいと考えております。","voiceIndex":46,"id":"exchange-010"},{"speaker":"渡辺委員","kind":"質問","question":"今の点とちょっと関連してくるんですが、最後に、当然事業形態の中で、有形のもの、無形のものもある中で、すごく難しいんですが、どれぐらい意識されているのかなというのが気になったので、伺いました。やはりまず第一義的には、品川区のサービスであるという中で、ここは業者だという変な壁はない仕組みが必要かと思っていますが、その点のお考えを伺えればと思います。","respondent":"久保田行財政改革担当課長","answer":"委員からご指摘がありますように、私どもは、たまに、例えば、事業者の方の対応が悪かったとかということが区民の声なんかで挙げられる場面がありますけれども、その際には責任者の方を呼ぶなり何なりして、きちんと伝え、指導していっているところでございまして。","voiceIndex":48,"id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"現状をお聞きしたいと思います。現状だけで結構です。１つは、指定管理されているところで、公募を含めてされているところ、公募がなかったというところがどこなのかというのをお知らせください。それと、業務委託ですから、その中の仕事、どの業務を民間に頼みましょうという形なんでしょうけれども、その中において、各所管と最終的に入札等々が入ってくると思うんです。","respondent":"久保田行財政改革担当課長","answer":"総合区民会館やスポーツ協会、体育館等につきましても、その事業者の地域とのかかわりとか、いろいろな特殊性がありますので、そういった中で一定の評価をした上で、次回も指定管理者としてふさわしいという判断をすれば、そういったところにつきましても、公募によらずに。","voiceIndex":50,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"１番目の指定管理の件ですけれども、公募をするという決まりというのがなかったでしょうか。確かに今までの歴史的な背景、それから評価もあると思うんです。","respondent":"久保田行財政改革担当課長","answer":"指定管理の公募の件ですけれども、制度上、公募でなければならないという決まりはございませんので、私どもの指針の中におきましても、施設の設置目的や事業内容などに特別な理由がある場合には、特定の事業者を選定することができるということで。","voiceIndex":52,"id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"これは意見です。これから考えていきたいなと思う点ですけれども、確かに連続性については、当然必要な重要項目ではあると思うんです。結局その人たちは何もやっていないわけですから、実績がないわけですよね。今、区の方向性、選定の方法はわかりますけれども、それで果たして行財政改革という点ではどうなのかなというところをちょっと考えていきたいなと、意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-014"}]},{"id":"topic-02","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"報告すると言っていますので、それはそれで議題に乗せていただきたいと思うのと、今日それぞれの地図もありますけれども、周辺の環境といいますか、住民要望といいますか、どういう土地柄、場所にあるのか、そういう周辺の状況をよく見ていかないと、ここにどういう施設が住民要望として強いのか、あと広域的に考えたときに必要なのか、双方があると思うんです。自然環境ということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-015"},{"speaker":"原委員","kind":"質問・要望","question":"関連組織ということで、先ほど委員長も副委員長もお話ししていたように、本当に幅がすごく広がっていってしまって、際限なくいってしまうということが考えられるんですが、単純にボランティアとか任意団体、それから、ＮＰＯ、ＮＧＯ、公益の財団法人、社団法人、これから２年後の一般社団法人、一般財団法人で、品川区にかかわる、品川区が免許を出しているところもあると思うし、東京都もあるだろうし。","respondent":"武内委員長","answer":"今それぞれ、原委員からもありましたけれども、今回指定管理者とか民間委託という形での一覧をつくっていただきましたけれども、どの辺まで関連団体と考えていくかという話だったんですけれども、それについてもし何か具体的な、まあ。","voiceIndex":60,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"皆さんが話しているように、指定管理者制度はたくさんの項目が入ってしまっていますから、わかりづらいと思うんです。なので、ここでやっていくのは、根幹になる筋みたいなところをしていくべきなんだろうなと思うんです。時期的にいうと、多分もう２回ぐらい指定されているんです。５年やって、新たなところということになっていますね。ですから、検証も必要なんじゃないかなと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-017"},{"speaker":"西本委員","kind":"意見","question":"絞ってしないと、ただ、案件になってしまうと、そのものに対してどうなんだという話になってしまうので、そういう話ではない。だから、そこになってしまうと、考え方とか、それは別所管でしょう、委員会でしょうという話になってしまうから、行財政改革特別委員会という意味でいうと、一連の流れとか、選定基準がどうなっているのかとか、検証も含めてというところになってくるのかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":66,"id":"exchange-018"},{"speaker":"原委員","kind":"意見","question":"先ほどお話が出たように、どこまででとめていただけるか、極端なんです。先ほど出たように町会、商店、こんなものまでも補助金などいろいろな関係で出てきて効率化ということになってしまう可能性もあるので、その前の段階で幾つか、だから、先ほど出たんだと思うんですけれども、どこかケースを出してという形の展開のほうが、より具体的なのかな、これは意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":68,"id":"exchange-019"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"まさにここで話をしていただきたいのは、中塚委員が言っていたように、チェック機関はあるわけで、正副でもずっと話していたときに、あまりに幅が広いので、指定管理と民間委託の部分を出しました。だけれども、それぞれの区が携わった団体もあるでしょう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-020"},{"speaker":"中塚委員","kind":"意見","question":"ただ、指定管理者であれば、既に進んでいるもの、あと業者委託、いわゆる民間委託であれば、図書館の窓口や給食やいろいろな、過去１０年、２０年の長い歴史と、それぞれどこまで進んでいるということはあるわけですよね。そういった仕組みそのものの議論と、今までどう進んできたかというのも出てくると、またわかりやすく議論が描けるのかなと思いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":70,"id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5902#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":26088,"voices":75}},{"id":"h23-20110608-17","meetingId":"h23-cm06","date":"2011年6月8日","dateIso":"2011-06-08","committee":"震災対策特別委員会","time":"午後１時０３分～午後４時０３分","status":"正式会議録","sourceType":"formal","overview":"震災対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を53件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"スケジュールですけれども、平成２４年度に修正するということを聞きましたけれども、すると実際は平成２５年にこの計画が出てくるのでしょうか。となると、もう少し短くしたほうがいいような気がするんですけれども、そのことについての確認をお願いします。だからこの見直しの中で、当然それが入ってくるものかなと思っているんですけれども、それはどう考えているんでしょうかということです。","respondent":"高山防災計画担当課長","answer":"見直しのスケジュールにつきましては、先ほどお話ししました東京都の修正スケジュールの見込みが来年、平成２４年の夏というふうに伺っておりますので、可能な限りそちらのほうの修正決定を経まして、その後の修正作業はできるだけ短期間に済ませたいと考えております。","voiceIndex":37,"id":"exchange-001"},{"speaker":"伊藤委員","kind":"意見","question":"芦屋市の担当の方の話を思い出すと、大体９割近くの方が、一番初め地域コミュニティの中で助け出された話を聞きましたから、そうするとこの品川区も、どこでもそうなんでしょうけれども、やはり当たり前のことなんですね。そのことはお話をしますし、たしか濱野区長は、新聞に報道されておりましたけれども、品川区でも津波対策の必要性を感じたということをおっしゃっていましたね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":39,"id":"exchange-002"},{"speaker":"本多委員","kind":"質問","question":"この見直しの主な検討内容３点の中に帰宅困難者問題がありますけれども、品川区の人口は約３５万人で、昼間人口が５０万人というところがやはり課題になると思うんですが、この平成１９年度の防災計画では昼間人口のことがあまり重点的には書かれていないんですが、平成２１年度の品川区震災復興マニュアルでは、人口と昼間人口との危機管理というんでしょうか、課題がかなり触れられて。","respondent":"高山防災計画担当課長","answer":"まず今回、帰宅困難の問題につきましては、事業所内に社員をとどめるということが大きな対策の一つの柱ではありましたが、今般の震災を振り返ってみますと、必ずしもそういった社員の行動につながっていないという部分も見受けられましたので。","voiceIndex":40,"id":"exchange-003"},{"speaker":"本多委員","kind":"質問・要望","question":"これから防災計画の見直しが進んで固まって、出来上がってきたものをそれぞれ企業の事業所にしっかりと連絡をしたり、連携をするということをお願いをしたいと思います。その確認だけさせていただきたいのと、あと、品川区に危機管理室というものがありますけれども、そこと今後の連携がどのようになるのか、概要で結構ですので、それだけ教えてください。","respondent":"高山防災計画担当課長","answer":"危機管理室につきましては、それ以外の、たとえば新型インフルエンザでありますとかテロのようなたぐいも入ってくるかと思うんですが、その他属さない危機全般につきまして、危機管理室の対応になるのではないかと考えております。","voiceIndex":42,"id":"exchange-004"},{"speaker":"塚本委員","kind":"質問","question":"これに対する検討は、今回のこの主な検討内容ということで含めていただけると考えてよろしいでしょうか。","respondent":"中山防災課長","answer":"それをプロのアナウンサーに吹き込みをお願いいたしまして、もう少し聞き取りやすくなるのではないかと期待しつつ、その事業を進めていこうと考えているところです。","voiceIndex":46,"id":"exchange-005"},{"speaker":"塚本委員","kind":"質問・要望","question":"防災行政無線のある種の機能としての限界といったものも露見している中で、こういう時代なのでいろいろな新たな技術、あるいはいろいろな知恵というものを絞って、新しい施策も含めて、たとえば防災ラジオでありますとか、そういったものなんかも含めて、幅広くこの災害の情報をいち早く正確に区民の皆様にお知らせできるものを検討するということも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それが１点です。そういう点では、この防災計画を立てるに当たって、実際に住民が巨大地震が起こったときにどうなるのかということを想定して、自分としてはどう、地域としてはどうあるべきなのかというところが考えられるような形で、私は住民参加で防災計画も見直していただきたいと思っているんですけれども、そこのところが２点目です。","respondent":"高山防災計画担当課長","answer":"そしてお尋ねの２点目なんですが、コミュニティということで、地域防災計画の中に住民参加をということなんですが、これにつきましては、防災会議の中で区民の代表者の方も入っていただいておりますし、また計画の素案を出した段階で。","voiceIndex":49,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところで、私は改めてこの被害状況というのを、震度５強というのは経験したことのない被害ですから、この震災対策特別委員会の中でもみんなで出し合う、そして対策として何が必要なのかということでつなげていくということも必要なのかと思うんですけれども、私は改めて、ぜひ品川区としても何らかの形で調査をして被害状況をまとめて、ぜひこの対策にも生かしていっていただきたいと思うんです。","respondent":"片田防災まちづくり事業部長","answer":"そういうところを、今、できることから一応しっかりとやっていきたいと考えております。","voiceIndex":51,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は区内の被害状況については、区に届けられたものというのだけではなくて、区のほうからやはり調査をして、被害状況をまとめるということをぜひしていただきたいと思いますので、要望しておきます。","respondent":"岩田都市環境事業部長","answer":"こういう形でやりますので、この震災対策特別委員会には我々の庁内プロジェクトチームで検討した過程のものをどんどんお出しして、区議会からのご意見もいただきながら、区民の意見も聞きながら見直してまいります。","voiceIndex":53,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区民が震度５強というのは初めての経験ですから、本当に怖い思いをしたというのがたくさんありますし、被害状況というのも多くのところで区に届いていないというものもたくさんありますので、そういうところから、そういうハードの部分、それからソフトの部分、あわせて私は取り組むべき課題というのが見えてくるのではないかなと思いますので、いろいろな調査の方法はあると思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-010"},{"speaker":"山内委員","kind":"意見","question":"今回の震度５といった地震に対しての被害はさほどなかったというとらえ方をしていますけれども、これがやはり直下型となったときに、この東京都が示している危険度が高いといったことになると、やはりこの考え方、たとえば、今、防災広場を整備していくとかいう事業をいろいろ行っておりますけれども、それに加えて何かもう一つ上を行くような。","respondent":"岩田都市環境事業部長","answer":"ただ、さらにその力、地域の防災力をどう高めていくかということは、この見直し作業の中で十分検討していかなくてはいけないと考えております。","voiceIndex":56,"id":"exchange-011"},{"speaker":"山内委員","kind":"質問","question":"そういったところを今一度検討していきながら、区民の方々に、やはりどこの行政も安心・安全といったことをうたっているわけですから、そういった意味で安心できるような役所の務めといったものも、これからは非常に大きなポイントになってくるのではないかといったところもありますので、そういったところも、もし検討の内容で一つ加えていただけるのであれば、その減災、震災前の部分での、今。","respondent":"岩田都市環境事業部長","answer":"したがいまして、やはりもう少し行政も地域に打って出て、一方で強制力をかけながら、助成措置もやりながら、アメとムチの両輪で、将来的に２０年、３０年すればきちんと安全なまちは絶対にできるんだという安心感をつくっていくというのが。","voiceIndex":58,"id":"exchange-012"},{"speaker":"金野委員","kind":"質問","question":"品目ということもありましたけれども、いわゆる備蓄イコール避難所ですね。被災地でもこの問題はありましたので、電源確保が本当に学校避難所で確保されていくのか、今の現状はどうなのか、それでこれはだれが使えるのかといったようなところも、しっかり学校避難所のあり方というのも早急に検討するべきというところが加わるのではないかと思うんですが、そのお考えはいかがでしょうか。","respondent":"中山防災課長","answer":"これはいつもやっていることです。それで電源ですが、先般もご説明いたしましたけれども、今、停電になりますと、これは手動でもできるんですけれども、３０分後に自動的に発電する発電機があります。これが大体４kwの光で７２時間はもつだろうです。","voiceIndex":60,"id":"exchange-013"},{"speaker":"金野委員","kind":"質問・要望","question":"備えが大事というところでは、やはりこの学校避難所のあり方というのを、この避難所連絡会議はそうなんですが、品川区としてこういうふうにしていきますよというある一定のものを持ちながら避難所連絡会議の中でしていくということも大事でしょうし、またこれを避難所訓練という形でしていくということも大分増えてきましたけれども、区民の皆さんが自分の目で、備蓄倉庫にはこういうものがあるんだな。","respondent":"片田防災まちづくり事業部長","answer":"ただ、今、委員のお話がございましたように、やはり避難所ごとにそれだけの適正な避難人口を想定した中で、備蓄等のバランスについても果たして大丈夫なのかどうかといった疑問もありますので、そういう状況の中では、いろいろ今後検討するに当たって。","voiceIndex":62,"id":"exchange-014"},{"speaker":"金野委員","kind":"質問・要望","question":"場合によってはと最後におっしゃって、言葉じりをとるつもりはないんですが、やはりこれは大事な備えであるという観点からぜひ検討をしていただいて、ご報告もいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-015"},{"speaker":"渡部委員","kind":"質問・要望","question":"地域防災計画の中で何点かお伺いしたい。今度新たに見直したときに、このような災害があった後ですから、またこういうところに新たに置く必要があるんだというお考えがあれば聞かせていただきたいのがまず１点。それとこの３月１１日に震災があって、やはり私たちもこういうときどうするんだろう、ああするんだろうといったときに、実はこれを確認してこういうふうにやるんだというようなところがありました。","respondent":"岩田都市環境事業部長","answer":"その後、それが決まれば区民向け、あるいは職員向け企業向けにこういったよりわかりやすいものをつくって、繰り返しＰＲあるいは訓練をしていく必要はあろうかと考えていますので、十分そこら辺は検討してまいりたいと思います。","voiceIndex":65,"id":"exchange-016"},{"speaker":"渡部委員","kind":"質問・要望","question":"よろしくお願いします。ただ、ある程度の説明を聞いていただいて、今は意識が高いところですから、預かっていただくというのはありなのかなと思いました。学校で残っていらっしゃった先生方が個別に対応されていたというような話も伺ったんですが、これも実は特段マニュアル化されているわけでもないですし、本来、多分これは学校の先生ではなくて区の職員で対応すべきものなのかなとも感じたりしたんですが。","respondent":"岩田都市環境事業部長","answer":"実際は同じ震度階であっても、振幅数、揺れの横揺れ・縦揺れの組み合わせがみな違いますので、今回品川区で震度５の強という強い地震を受けて、ほとんど被害がゼロに近かったといって安心はできないんです。","voiceIndex":67,"id":"exchange-017"},{"speaker":"木村委員","kind":"質問・要望","question":"これは増やすことが可能なのかどうか。そういう話も聞いておりますので、ぜひとも地域地域でそういう訓練はもちろん、これから１年に１回、３月１１日になるのかどうかわかりませんけれども、そういう取り組みも私は必要だと思いますし、本当に品川区が先頭になってそういうことをやるべきだと私は思っておりますけれども、区のほうの考え方を教えていただきたいと思います。","respondent":"岩田都市環境事業部長、中山防災課長","answer":"もう発災後３０分に到達したときがありますから、おそらく津波でビルはつぶれていませんので、ですからとにかくすぐ近くの二、三分で逃げ込める５階建て以上のビルに逃げ込んで。それから避難所訓練ですけれども、これは先ほど申し上げましたように、学校避難所連絡会議の中で学校単位の避難所訓練をやってありますし、また、１年に１回ですけれども、１会場１,０００名ぐらいで１３地域センターに分かれまして。","voiceIndex":69,"id":"exchange-018"},{"speaker":"向委員","kind":"質問・要望","question":"そのお考えを伺いたいのと、あと、できれば今回帰宅困難者もかなり多かったですが、震災が発災したときに地域に残っている人で、自分たちの力でやはり火を消さないといけないとか、何かしら対応ができる装備を整えていっていただきたいと思います。ご意見、お考えをお願いします。","respondent":"中山防災課長","answer":"それで少し練習をしていただいて動かせるようにしていただきたいです。","voiceIndex":72,"id":"exchange-019"},{"speaker":"向委員","kind":"質問","question":"使い方は皆さん一生懸命なんですが、力の問題で、男性でもエンジンを稼動できないという方を私も見たんです。なので、そういったご意見もよく伺うので、その点もあわせて、操法もいろいろＤＶＤとか、そういった区役所の皆さんからの補助があると。冊子に加えて使いやすい装備ということで、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-020"},{"speaker":"吉田委員","kind":"質問","question":"それは聞こえるんです。その中でこの間３月１１日は、私はマンションに住んでいたんです。そのときにやはり無線が聞こえるということは、一番どうしたらいいんだろうというときに、コミュニティのものでもあるんですけれども、やはり聞こえるところに情報を得にいくという、どうしたら聞こえる配置をしたらいいんだろうかという視察等も考えていらっしゃるのか、お伺いをしたいんですけれども。","respondent":"中山防災課長","answer":"そうしますと、高くいたしますと音が落ちてしまうんです。遠くへ飛ばないで落ちてしまうような不都合もございまして、先ほど来、出ていますけれども、何らかの検討をしますので、ご理解のほど、よろしくお願いします。","voiceIndex":75,"id":"exchange-021"},{"speaker":"伊藤委員","kind":"意見","question":"だからああいう震災が起こった際に、すぐに地域の方がそこに駆け込んでいって助けた。結果として死者が０名だったということを聞いたことがあります。非常に印象に残っているんです。具体的には発災した際に、町会・自治会、それから地域団体がそれをしなければならないようなところまで落とし込んでいかないと、今の地域コミュニティの中では有効に対処できないと思うんですが、お考えをお聞かせください。","respondent":"中山防災課長","answer":"共助ですけれども、地域の方の名前を書いていただくというような取り組みを、今、進めているところですので、地区によって温度差がありますけれども、私どもがもうこの話をしましたので、大分動きがよくなったんですけれども。","voiceIndex":78,"id":"exchange-022"},{"speaker":"伊藤委員","kind":"質問","question":"下町のところでは確かにそういう動きはしやすいんでしょうけれども、例えばオートロックのマンションがあって、そこにどうしても入らなければいけないことがあった場合には、それはその時点でできないわけでしょう。これはもう個人や町会ではどうしようもない話ですから、まさにこの防災計画の中に具体的に落とし込んでいく作業をしていかなければいけない。お答えをお願いいたします。","respondent":"片田防災まちづくり事業部長","answer":"やはり町会の高齢化というところもありますので、そういうことも含めて、じゃあ、情報の発信の仕方とか、これまではケーブルテレビあるいは防災伝言版とか、あるいは先ほどの防災無線等々でいろいろな角度から情報を発信してございましたけれども。","voiceIndex":80,"id":"exchange-023"},{"speaker":"本多委員","kind":"確認","question":"委員長、先ほど聞かせていただきましたことを、くどくもう一度ちょっと確認をしたいと思うんですけれども、同趣旨の質問で申しわけありません。年度が変わって、今、人事が違いますけれども、危機管理室が問われる部分については同じことだと思いますので、その検討体制について、危機管理室長が入る、入らないの確認だけ、どうしてもちょっともう一度させてください。","respondent":"岩田都市環境事業部長","answer":"それで、今回のこの地域防災計画の見直しの区長指示の中で、この危機管理室のあり方そのものについても検討するようにという検討事項がついておりますので、現在見直しの中で、その検討に入っております。","voiceIndex":82,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう一つは先ほどの災害弱者なんですが、２,９９７名ということなんですが、この内訳がどんな内訳になっているのかということで、例えば要介護何度の方が何人ぐらいいるかとか、そういう全体の内訳でいいんですけれども、障害者の方が何人いるとか、そういう内訳の資料もあったらぜひお出しいただきたいと思うんですが、お願いします。","respondent":"岩田都市環境事業部長、中山防災課長","answer":"現在、用意しておりませんけれども、１つはまず地盤ですね。これは皆様方もよくご存じの東京都の地域危険度です。これは火災危険度、倒壊危険度というのがあります。これも、今、部長が申し上げましたように、水質検査をやるとちょっと飲めないかなと。ですから生活用水に使うには持ってこいかということで、４１校に井戸は掘ってあります。","voiceIndex":84,"id":"exchange-025"},{"speaker":"井上副委員長","kind":"質問・要望","question":"それで、地域活動課が防災課と協力をして、今、地域センターのほうでそういった調査もかけているというようなお話も伺っているんですけれども、八潮地区は八潮地区で防災協議会が独自にすべて全戸でアンケートを実施していると。いかがでしょうか。","respondent":"片田防災まちづくり事業部長","answer":"今の調査の関係ですけれども、特に罹災証明等については、実際に地震保険等に入っていらっしゃる方が自分の被害がどうだったのかなということでご相談をされて、品川区の建築課と地域活動課のほうで状況を確認をして必要な対応、証明等の発行なりは行っているような状況です。","voiceIndex":88,"id":"exchange-026"},{"speaker":"井上副委員長","kind":"提案","question":"そういった取り組みは違う所管になるのでしょうから、ぜひそちらのほうに震災対策特別委員会として提案をしていけばいいと思うんです。先ほどコミュニティのことを言われました。とても大切であるという認識も品川区が持っている。それが最終的には区民を守る一番の計画になると思うので、その辺の柔軟な対応をとっていただきたいという切な要望に対して、お考えを伺いたいと思います。","respondent":"片田防災まちづくり事業部長","answer":"ただ、品川区のほうとしては、現在、住宅課のほうでもいろいろな耐震の相談とか、あるいはマンションの管理上の問題をご相談を受けるようなこともありますので、専門家の派遣とかもあわせて行っていますので、いろいろなあらゆる機会を通してコミュニティの大事さ、あと。","voiceIndex":90,"id":"exchange-027"},{"speaker":"井上副委員長","kind":"質問・要望","question":"いろいろと高層の住宅に対して心配をしているところだけれども、建物は安全ですとか、そういったところではエレベータと備蓄なんだろうと思いますけれども、八潮地区のほうでも１４階建て以上の建物では、１週間ぐらい靴をはいて部屋の中を歩かなければいけないぐらいのいろいろな家具の転倒といった被害があるということを聞けば、決して被害がなくてよかったねという話ではないと思いますので。","respondent":"片田防災まちづくり事業部長","answer":"場合によっては、もし帰宅困難者があわせてでた場合には、学校が主な避難所となっていることを考えると、例えば大学とか、そういう区内の別ないろいろな学校機関とも連携をとる等をして、その方々をどのような受け入れ方をするのか。","voiceIndex":92,"id":"exchange-028"}]},{"id":"topic-02","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう一つ、こういう避難されてきている方に使える制度というのがさまざまあると思うんですけれども、それに加えて、先日避難者の上下水道料金の減免が東京都のほうでされるというのが新聞報道であったのを、事務局のほうで資料として出していただきましたけれども、こういうことの情報は区民住宅に入られている方のところにはどういうふうに伝えられているのか、申し込みの仕方とかもあわせて。","respondent":"柏原住宅担当課長、中山防災課長","answer":"当面の間６カ月ですけれども、そういった形で避難された方にはご案内をしていますが、あの福島の原発の状況であるとか等々ありますので、その後延伸するかどうかについては、今、検討しています。当然９月からは林間学校等で使えませんので、それで、今、どうしているかといいますと、富岡町のほうの職員に頻繁に来ていただいて、今の入所者の今後の身の振り方についての相談業務をお願いしているというような状況です。","voiceIndex":99,"id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それとあとは情報というところで、それであればこの上下水道の減免ということについては、品川区のほうに申し込めば減免が受けられるというのは、上下水道に関しては手続はどうなっているのか、ぜひこういうのも早くにできるような対応をぜひお願いしたいと思うんですが、いかがでしょうか。","respondent":"柏原住宅担当課長","answer":"水道の件につきましては、入っていただいたときにまず個別に契約等々していただいていますので、そのやり方等についてはこちらのほうでご案内するにいたしましても、個別でのお問い合わせをしていただいて手続をするという形になろうかと思いますので。","voiceIndex":102,"id":"exchange-030"},{"speaker":"伊藤委員","kind":"提案","question":"これはこれでいいんだけれども、何を言いたいかというと、これを見える化したらどうですかということです。なかなか雑駁な言い方だけれども、例えば本庁舎のどこかに、今、何％節減していますというようなことがわかるシステムを置いて、それを区民の皆様がだれでも見えるシステムをつくればいいのではないでしょうかということの提案です。お答えをお願いいたします。","respondent":"岩田都市環境事業部長","answer":"それはダイレクトにそのときの電力使用量を表示しないと、あまりインパクトがないと思いますので、ハード的にそういう仕組みがつくれるかどうかですね。そこら辺、専門家のほうのご意見を聞きながら考えていきたいと思います。","voiceIndex":104,"id":"exchange-031"},{"speaker":"伊藤委員","kind":"提案","question":"もちろん、その費用対効果も測定しての話だから、今、荒っぽい提案ですからすぐにどうこうということではないんだけれども、私たちが思うのは、区民の皆さんに、それこそいろいろな話があったように、今、公園が消灯していますよね。それから道路の消灯もしている。結果としていろいろな意見が出てくるというのも事実です。検討してくださいということですが。","respondent":"岩田都市環境事業部長","answer":"一般論で、例えば電気がいっぱいありますから、これが何本あるので何Ｗ掛ける何千本というので、それから２５％減らすということではなくて、実際、昨年の使用量、実際に使った使用量からさらに２５％下げるという形ですので、これがどこまでできるかちょっと検討させますので。","voiceIndex":106,"id":"exchange-032"},{"speaker":"伊藤委員","kind":"質問","question":"わかりました。そうであるならば、ハード的なものをそろえなくてもいいじゃないですか。例えば１カ月間の電力使用量を測定して、今月はこうでしたということを、例えばそれこそ掲示板を出すぐらいは簡単にできる話でしょう。だから要は２５％という数字ではなくて、具体的にこれだけ、何千kwなのかわからないけれども、削減しましたよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-033"},{"speaker":"金野委員","kind":"提案","question":"というのは、区民まつり等々、これから行うところ、あるいは少し小規模にするというような計画もあるかと思うんですけれども、例えば学校の校庭でされるような区民まつりは、いわゆる先ほどの電源というところで、自家発電のこれを試しに使ってみるというところで、実際に使えるものかどうなのかというのを。","respondent":"中山防災課長、岩田都市環境事業部長","answer":"受け入れの決定ですが、これは大変申しわけなかったんですけれども、私どもの態勢がちょっと不十分だったものですから若干おくれたかと思いますけれども、都合１,５３２名の方の受け入れを行いました。翌日に皆さんご帰宅されたです。委員のおっしゃったように、各学校とかあるいは地域の町会も発電機を持っておりますので、そういった発電機を活用しながらぼんぼりを照らしてお祭りをやる分というのは、私はとてもいいことだろうと考えていますので。","voiceIndex":109,"id":"exchange-034"},{"speaker":"金野委員","kind":"提案","question":"ただ、この電源という１点で私はちょっと提案をさせていただきましたので、そういった場を活用して、いわゆる学校避難所の電源がちゃんと使えるかどうかという一つの、ただ学校避難所訓練だけで使えるというのではなくて、ちゃんと使えるよということも、そこで使った軽油を新しく取り換えるということもできるのかなと思ったので、ちょっと提案をしてみました。どうでしょうか。","respondent":"中山防災課長、片田防災まちづくり事業部長","answer":"そのほか毎年点検をしています。それから先ほど申し上げましたように、学校避難所連絡会議等で、だれでもつけられるような、だれでも切れるような訓練を実施しています。今、ご提案いただきましたところは、いろいろ地域センターとか関係部署ともちょっと協議をして、できるところはそういうことを考えていきたいと考えていますので、よろしくお願いしたいと思います。","voiceIndex":112,"id":"exchange-035"},{"speaker":"山内委員","kind":"質問","question":"それからこれはいわゆる無利子融資あっ旋と同様の考え方でよろしいのかといったことと、それから区内中小企業への緊急融資あっ旋といったことでありますけれども、これは計画停電等によりと書いてありますけれども、これは本社は品川でしょうけれども、いわゆる支社や工場がその計画停電地区にある、もしくは東日本大震災の地域にあるといったところでの。","respondent":"高山防災計画担当課長","answer":"申しわけございません。こちらのほうの所管が、本日出席の理事者の中にございませんでして、詳細はちょっとお答えができないんですが、申しわけございません。調べてお答えしたいと思います。","voiceIndex":115,"id":"exchange-036"},{"speaker":"山内委員","kind":"質問","question":"わかりました。そのプレゼントは商品券ですか。いろいろ考えていらっしゃると思うんですけれども、７月、８月、９月、確かに昨年はとにかく暑かったです。冷房を非常に多く使ったということで、電力不足ということも言われたりしました。そうしますと、そういったことだと、冷房を使わないと結構電力は落ちるんですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-037"},{"speaker":"渡部委員","kind":"質問","question":"２点伺います。義援金なんですけれども、やっと今度の１１日でしたか、間もなくこういう形で皆さんからいただいた義援金を割り振りしてお届けしましたというような発表があると伺いましたが、今後、義援金は大々的に受け付ける、受け付けないは別として、いつぐらいまで今の高齢福祉課のほうの対応でやっていこうとお考えなのか、わかれば教えてほしい。これはまだ続くような形をとられています。","respondent":"岩田都市環境事業部長、中山防災課長","answer":"ただ、こういう大災害ですので、これから長い復興の時間がかかりますので、この義援金を早急に締め切るということはおそらく品川区としてはしなくて、温かい区民の方の支援というのは継続的にずっと続けていくことになろうかと思います。参考までなんですけれども、義援金の関係なんですが、６月２２日に宮古市のほうへ１,０５０万円、それとこれは都市環境事業部長の発案なんですけれども、自転車を６０台、第５便として搬送する予定です。","voiceIndex":120,"id":"exchange-038"},{"speaker":"井上副委員長","kind":"質問","question":"区民住宅の提供のところなんですけれども、募集戸数２２戸に対して１４７件の方が応募されたんですが、その１２５件の方たちは、その後相談とかどうされたのかとか気になるんですけれども、そのフォローはどのようにされてきたのかお伺いしたいと思います。","respondent":"柏原住宅担当課長","answer":"といいますのは、都営住宅の募集であるとか、ほかの住宅の募集、または福島県の方ですと戻ったりとかいう方がいらっしゃいまして、ほかの住宅を見つけたりとかご自身で動いたりした分もありまして、キャンセルが多かったということで、その後。","voiceIndex":123,"id":"exchange-039"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"そういうことをしていかないと、おそらく選挙で皆さんそれぞれお訴えになったと思うんですが、この震災対策特別委員会の目的の達成がされないと思いますので、先ほどの繰り返しになりますけれども、あと１０回程度しかないわけですから、その中で具体的に議論をして実を結んでいくような運営の仕方、設計を正副委員長で示していただきたいということをお願いしておきます。私も当時の委員でありました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":128,"id":"exchange-040"},{"speaker":"渡部委員","kind":"質問","question":"例えばやはり中小企業をどうするんだという話になる。震災が起こったとき、これは震災対策ですから、話し合うときにはやはり場合によっては地域活動課の部長が必要かもしれないですし、ということは事前にやはり話し合いの内容を決めた上でやっていくのがいいのかなと感じましたので、これはもう私は正副委員長に一任いたしますので、理事者と相談の上、お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それを踏まえてなんですけれども、そういう中で私はぜひ深めてほしいというのは、先ほどからも出されている地域コミュニティを強くしていく、防災に対する地域力を高めるというところで、私は防災計画に住民がどうかかわっていくかというのがすごく求められていると思いますので、そこら辺の防災に対応する地域力、地域コミュニティを強くしていくためにどういうことが必要なのかというあたりは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-042"},{"speaker":"渡部委員","kind":"意見","question":"今、それを話し合うことは無理だと思います。僕らは何も言われていなくて、その他でそういう発言をしろとも言われていないですし、今の今、それをここでというわけにはいかないと思います。やはりみんな会派に持ち戻ってやらなければならないので、それは今やらないでほしい。逆に文書でしっかりと、例えば共産党はこういうことだというのを出していただかないとならないのです。それはとめてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":131,"id":"exchange-043"},{"speaker":"伊藤委員","kind":"提案","question":"その議論の過程の中でそういうのがあってももちろんいいんだけれども、だけど区議会で議決をしたことをこの当委員会が無視をして運営することになれば、これはまた別の問題になってくるわけであって、もしそういう運営をしたいということであれば、それはしっかり区議会の仕組みの中で提案をしていただいて、それぞれの党側の議会運営委員会になると思うんだけれども、そこで議論をされて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":132,"id":"exchange-044"},{"speaker":"井上副委員長","kind":"提案","question":"渡部委員からも、震災対策特別委員会に手を挙げて来たということは、個人的な意見でも構わないと思います。ですから理事者のほうでも、特別委員会なので、福祉に関することであれば健康福祉事業部の方を説明員として招集をする、あるいは、今、中小企業のことをおっしゃいました。所管がいません。ぜひそういった形で、今日、少しでもまとめられるようにしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":133,"id":"exchange-045"},{"speaker":"本多委員","kind":"質問・要望","question":"調査項目もはっきり書かれていたと思いますので、その５月２５日の区議会本会議で議決をされた、この震災対策特別委員会を設置したときの趣旨にのっとって委員会運営をやっていただきたいと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":134,"id":"exchange-046"},{"speaker":"山内委員","kind":"意見","question":"時間も短い期間の中というのは委員長、副委員長ももちろんおわかりの中で、議決をして、それでこれだけのことをやりますよとこうやってペーパーにしてあらわしている。議決をした意味が全くないということ、その辺はしっかりと考えてやってもらわないと、これからの特別委員会にかかわることだから、その辺はしっかりと整合性を持ってやってもらいたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":135,"id":"exchange-047"},{"speaker":"渡部委員","kind":"質問","question":"会の運営について先ほど申しました。僕が正副委員長にお願いをしますと言ったのは、もう、それだけなんです。なぜならば、ここに中小企業のことが書いてあって、今日、出席する理事者が仮にわかっていて、質問が来る可能性があるじゃないですか。でも、そういう質問が来る可能性があるとしたら、何で委員長たちはこれがわかっていてお呼びいただけなかったんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":136,"id":"exchange-048"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だから決して議論をするなとか、それから新しいものを議論するなと言っているわけではない。それはもちろんあってもいい。けれども、新たに新しい課題を求めていくということではなくて、今、与えられた特別委員会としての使命を果たすことは、この議決された内容を真摯に議論していくことになると思っているので、そのことはぜひ間違いないように進めていっていただきたいことを改めてお願いをしておきます。","respondent":"飯沼委員長","answer":"それは年間計画を立てながらやっていきたいと思っていますので、今日のところは概要と入口のところの報告だったので、今日答えていただけなかった分はご勘弁をいただいて、次回から絞ったところでやっていきたいと考えています。今日もたくさんご意見をいただきました。","voiceIndex":137,"id":"exchange-049"},{"speaker":"山内委員","kind":"提案","question":"会派からそういった提案をしてくれということなんですか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":139,"id":"exchange-050"},{"speaker":"山内委員","kind":"質問","question":"いや、そうではなくて、それはいいでしょう。だってちゃんとここに特別委員会を設置し、そして調査事項と備考というところがちゃんとあるわけだから、これをもとにちゃんとやっていかなくてはいけないということを言っているわけでしょう。違うんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":141,"id":"exchange-051"},{"speaker":"山内委員","kind":"提案","question":"だからそれはこの備考欄にちゃんとあるじゃないですか。僕はそう思いますけれども。今、共産党から１つ提案がありました。これはちゃんと区議会で決まったことなんですから、この震災対策特別委員会を設置し、これについて調査していくといったことなんですから、それはちゃんと守ってやっていかないと、これからの特別委員会にかかわってくる。それはしっかりと考えていただきたい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":143,"id":"exchange-052"},{"speaker":"金野委員","kind":"質問","question":"皆さんがもっと深めたいというところをしていくというのが流れかなと思うが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-053"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6388#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=17&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":56848,"voices":147}},{"id":"h23-20110627-6","meetingId":"h23-cm06","date":"2011年6月27日","dateIso":"2011-06-27","committee":"区民委員会","time":"午前１０時００分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"平成１３年に条例ができて１０年たつんですけれども、１０年たった結果、区長にどうしても変えなくてはいけないのが出てこういう条例に変えたのかということ、それと生活安全協議会というものが副区長から区長に変わることによって、この組織自体が強化されるとか、効果が出るとか、何か明確なものというのはあるんでしょうか。","respondent":"川崎生活安全担当課長","answer":"２点目の区長に変わったということで強化されるのか、あるいは効果があらわれるのかというところなんですが、これについては、明日の議題になりますが、セーフティアップ運動というのをこれから策定して、その問題について取り組んでいきますので。","voiceIndex":5,"id":"exchange-001"},{"speaker":"本多委員","kind":"質問・要望","question":"趣旨などにつきましては理解できるんですが、１点だけ確認させていただきたいんですけれども、生活安全協議会というと区内の４警察署だと思うんですが、今の答弁にありましたように、充実を図るという意味では、東京湾岸署ですとか、そういうところを加えたりするようなことは考えなかったのか。この安全協議会以外でもいろいろな会議体というのがあるのかどうか、もしわかれば教えていただきたいんですが。","respondent":"川崎生活安全担当課長","answer":"ただし湾岸警察署の管内には公園が存在するのみで、区民の居住がありませんので、署長ではなく、生活安全担当課長に出席していただいております。ほかの警察絡みの会議があるかという質問ですが、この協議会のみでありまして、ほかにはございません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"今、協議会の充実を図る、区長が入ることによって充実を図るということですが、今までも必要なことは意見を協議会から区長に言っていたわけですけれども、充実を図るというのは、具体的に言うとどういうことなんですか。要するに仕組みをどういうふうに変えるか。協議会の充実というのは具体的にどういうことなのかというのがよくわからないんですが。","respondent":"川崎生活安全担当課長","answer":"充実の内容については、これと明日の議題になるのか、セーフティアップ運動というのを今後立てていくんですが、この中で、今まで協議会で図っていたものを、今度、区長と警察署長を入れて、区内の犯罪を減らしていこうということの取り組みをこれから始めていく。","voiceIndex":9,"id":"exchange-003"},{"speaker":"宮崎委員","kind":"確認","question":"セーフティアップ運動で、犯罪を防止する運動を進めるということですか。今まではそういうのはやっていなかったのか。ちょっとそこのところが、充実を図るということは、セーフティアップ運動を進めることですか。セーフティアップ運動を進めるということが、犯罪を防止するための取り組みなんですという説明なんでしょうか。そこのところをもう１回確認したいんですが。","respondent":"川崎生活安全担当課長","answer":"それに基づきまして、今までやっていたものよりもさらに具体的に犯罪を抑止していこうではなく、犯罪を減らしていこうという取り組みを、品川区セーフティアップ運動で進めていこうというものであります。","voiceIndex":11,"id":"exchange-004"},{"speaker":"宮崎委員","kind":"意見","question":"そうすると、例えば今、いろいろな町会の方々もパトロールをやってもらったりとか、あるいはその取り組みの一環だと思うんですけれども、学校のＰＴＡの人たちが自転車のところにつけてとか、いろいろやっているんですけれども、そういう取り組みとか、また新たな犯罪抑止ということというのは、具体的にどういうことを考えているのか。","respondent":"川崎生活安全担当課長","answer":"これは明日説明しようと思っていたんですけれども、品川区セーフティアップ運動基本計画というものを発表しまして、この中で４つの対象、振り込め詐欺、ひったくり、万引き、自転車、この４つについて、区と警察と区民の皆さんが協働して、これを減らしていこうと。","voiceIndex":13,"id":"exchange-005"},{"speaker":"宮崎委員","kind":"質問","question":"それが１つと、あともう１つ、警察のほうも生活安全課長から警察署長に変わるということと、そのほか委員として警視庁の本部のほうの職員が入ってくるということと、たしかこの協議会の事務局には警察のほうからも入っていたと思うんですけれども、１０年前、この条例を審査するときに、事務局にも入ってもらうという説明だったと思うんですけれども、そうすると、今、体制としては何人委員がいて。","respondent":"川崎生活安全担当課長、中川原地域振興事業部長","answer":"事務局については、私を筆頭に、生活安全担当の区の職員２名、そして品川区内の４警察の生活安全担当課長が事務局として役割を持っております。区長に変えることによって、より具体的な取り組みを行うです。そうはいっても振り込め詐欺とか身近な犯罪が増えている中で、警視庁と連携してそれに取り組もうということで平成１３年に条例ができて、警視庁からも警視を課長としてお迎えしてきた。","voiceIndex":15,"id":"exchange-006"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっとイメージが出てきたんですけれども、あと１つお聞きしたいのが、事務局の中に生活安全課長を含めるというのは、ほとんど警察のほうで事務局だなと思ったんですけれども、以前の条例を最初につくるときにも、いろいろ協議会の中であれをやろう、これをやろうというのを協議して、それで各団体に持ち帰ってやりますという説明だったと思うんですけれども。","respondent":"川崎生活安全担当課長","answer":"要請はしますが、それはやってくれ、あとはそっちに任せたよと丸投げするものではなく、警察と区民の代表の方、町会の方々などと協働してやっていくものでありますので、お願いしっぱなしではなく、例えば防犯カメラの設置とか。","voiceIndex":18,"id":"exchange-007"},{"speaker":"宮崎委員","kind":"質問","question":"どこに防犯カメラをつけたらいいか、そういう疑問、アドバイスをしてほしいということに対してアドバイスをする程度なのか、それとも具体的に警察のほうから、これをやってほしいとか、もちろん警察のほうで上意下達でできるものではありませんから、そういう意味では協働でいくようになるんだと思うんですけれども、具体的な警察のほうからの要請というのはどういう形で、中身で行われるんでしょうか。","respondent":"川崎生活安全担当課長","answer":"これを皆さんで知恵を出し合って協働してやっていきましょうという取り組みでありますので、アドバイス的なもの、注意喚起的なものは警察はしますが、これとこれをいついつまでにやってくださいとか、こういう要請のものは一切ございません。","voiceIndex":20,"id":"exchange-008"},{"speaker":"石田副委員長","kind":"質問・要望","question":"今までは協議会でいろいろ議論したのを、区長に対して品川区のこういう取り組みをしてほしいとか、そういう要望じゃないですけれども、そういう意見を述べてきた中で、今度は区長がトップに立ってやることによって、先ほどからも少しお話が出ていたんですが、内容ががらっと変わる中で、どのようなメリットがそこに出てくるのかというのがまず１点と、あと目的のところに。","respondent":"川崎生活安全担当課長、中川原地域振興事業部長","answer":"ほかの委員の方々は、役職のある会長とか、防犯協会の会長だとか、ＰＴＡの代表者とかが出席されているんですが、それについては会長にはお伝えしますが、私のほうが現場に出ていって、委員の対応などがありますので。じゃあ平場の話のほうがいいんじゃないかというお尋ねですが、ここに出てくる委員は、いろいろな方が会を持っていてその会長ですので、日々の中でこの問題について皆さん悩んだり困ったりしたことを議論されて、それを持ち寄って今回。","voiceIndex":22,"id":"exchange-009"},{"speaker":"石田副委員長","kind":"質問","question":"よくわかったんですが、そうしたら、今の１０年を否定してしまうのかなと。それに問題点があったから、今回改正をされるんだという僕の認識の中では、その辺、どういう問題解決をしていこうかなというのがあるのかなと、そこだけ教えてください。","respondent":"中川原地域振興事業部長","answer":"発展的にここまで区民の８・３運動とか、全国に先駆けましていろいろ自主的な運動も出てきまして、そういったものも集大成して、さらに今後充実させていこうというのが今回の基本計画の策定の意味ですし、区長がトップになる意味もあると考えていますので。","voiceIndex":25,"id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと意見を。これは賛成できないと思います。安全を確保する取り組みというのは大事で、これは進めていかなければいけないと思いますけれども、今回、１つはこれを進めてきたもう一方では、例えば交番がどんどんなくなってくる。ですから、今回のこういうやり方というのは、今の犯罪対策の関係では、警察の機能を弱めて住民に押しつけるという流れになっているので、賛成できないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-011"}]},{"id":"topic-02","title":"第３２号議案、平成２３年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第３２号議案、平成２３年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"団体観光促進なんですけれども、この目的はわかるんですけれども、まずこれの理念を教えていただきたいのと、それとなぜ１,０００円と決めたのか教えてください。委員長、今、説明があったのをずっと聞いちゃっていいんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"それと中小企業センターの運営なんだけれども、節電用品の購入というのはいいんですが、中小企業センターを夜通って、こうこうと電気がついて囲碁・将棋をしているじゃないですか。それとものづくり節電キャンペーン経費をやるという形でこういうふうに経費が出ているんですけれども、このキャンペーンというのは、大きい目で見ると、一部の企業じゃないですか。","respondent":"武内地域活動課長、米田商業・観光課長、福島ものづくり・経営支援課長","answer":"うちわの件ですけれども、どのようなところに配布、従来、１万５,０００本につきましては。中小企業センターにつきましては、夜間９時半まで利用が可能となってございまして、特に貸し館部分につきましては。単に節電だけではなく、働き方の工夫、例えば独自にサマータイムを導入するですとか、さまざまなことが考えられますので。","voiceIndex":42,"id":"exchange-013"},{"speaker":"藤原委員","kind":"質問・要望","question":"プレスを見たら、東京都が３,０００円と出しております。この２つの関係をどうとらえて、どう整理をしていくかということと、それと１,０００円のあれはわかったんですけれども、１,０００円で効果が出るのという思いがあるんですけれども、その辺についてもうちょっと明確に答弁していただきたい。国民全員一人一人が節電を心がけるのに、心がけるわけじゃないですか。","respondent":"武内地域活動課長、米田商業・観光課長、福島ものづくり・経営支援課長","answer":"そういった意味では、ただうちわでパタパタやるというよりも、もっとねらいは節電をＰＲするという区の方針として。いずれにしましても、先方の状況を見極めながら、今後も継続的に宮古市担当者と連絡をとってまいりたいと考えているところです。先ほど申しましたように、確かにものづくり現場での節電というのはかなり難しいというのがありまして、アドバイザー派遣をするということがあります。","voiceIndex":46,"id":"exchange-014"},{"speaker":"宮崎委員","kind":"質問","question":"実際対象がこれになっているのかどうかというのと、あと実際に診断によって設定の改修工事ですね。改修工事の支援がないと難しいのかなと思うんですけれども、そのことはどうかということを伺いたいのと、もう１つ、ハローワークのほうなんですけれども、ちょっと勉強不足で、ハローワークの被災者雇用開発助成金の制度でちょっと、よく知らないんですけれども、そこのところを教えてほしいんです。","respondent":"武内地域活動課長、福島ものづくり・経営支援課長","answer":"耐震診断の町会の会館も該当は３６件あります。予算計上する際、５件マイナスにしています。その理由としましては、３６件すべてというふうには考えられないということで、３１件ということにしています。こちらの短時間労働者ですけれども、この短時間労働者は１週間の労働時間が、同じ事業所に勤めている者よりも短いということで、なおかつ３０時間未満の者ということが短時間。","voiceIndex":50,"id":"exchange-015"},{"speaker":"宮崎委員","kind":"質問","question":"町会会館のほうなんですけれども、５件減らしたのは、すべては考えられないというのは、そこの意味がよくわからなかったんですけれども、予算上で、要するに区のほうの都合で全部の予算を組むことは考えられないということでしょうか。今の状況からいくと、例えば３６件あるんだけれども、その５件は新耐震の後につくったので大丈夫だとか、そういうふうなことですか。ちょっとそこを１点。","respondent":"武内地域活動課長、米田商業・観光課長","answer":"はうちわのものがどの程度の効果を見込んでいるのかということですけれども、クーラーを２８度に設定しますと、従来よりも１０％の節電効果が上がると言われております。受け手、区のほうでイベントを行う際にどのような考え方があるかというご質問ですが、区内商店街で各種イベント事業、あるいは区の商店街連合会で大商業祭り等を今後開催予定です。","voiceIndex":53,"id":"exchange-016"},{"speaker":"沢田委員","kind":"質問","question":"単価というか、細かいんですけれども、３万円の扇風機とか１万円とか、種類によって値段が大分違うような気がしたので、その辺はどうなっているのかなというのをお伺いしたいです。４００万円という予算がついていますけれども、そういった形で報酬というのが増やされているのかなというのをお伺いしたいです。","respondent":"武内地域活動課長、福島ものづくり・経営支援課長","answer":"それと単価がそれぞれ違うというのは、それぞれの集会室の機能的なものが違いまして、量販店に行きますと。もともとこの相談員は３名体制、常時３名が相談にのるという体制でずっと行ってきたんですけれども、平成２０年のリーマンショックの後。今、説明は庁内の事務室のことをお話ししましたけれども、今回計上しているのは、事務室ではなくて、区民が利用する集会所等のお話ですので。","voiceIndex":56,"id":"exchange-017"},{"speaker":"山元委員","kind":"質問・要望","question":"専門的な方だと思いますけれども、実際どういう方たちがなられるのか、イメージがわかないので教えていただきたいというのと、アドバイザーとして何人ぐらいの方にお願いをしているかというのも教えていただきたいし、どのくらい時間をかけて説明をしているのでしょうか、教えていただきたいと思います。借り物なのにどういうふうに改修したらいいのかということが１点。","respondent":"福島ものづくり・経営支援課長、武内地域活動課長","answer":"回数としては２回から３回ぐらいかかるのではないかと考えております。ご案内のとおり、区民集会所につきましては、一般的には区民の方の集会機能という形になりますので、そういう方が利用する場合については、節電ということを理解していただいて、２８度という中で。","voiceIndex":60,"id":"exchange-018"},{"speaker":"本多委員","kind":"質問・要望","question":"それと宮古のほうの、これは担当の課が違うと思うんですけれども、宮古のさんま祭りで２５０万円支援というところで、被災地支援ということで区がいろいろと工夫をしていただいているなというのがよくわかるんですけれども、ぜひ宮古市のほうの負担がないように、２５０万円という予算では限りがありますけれども、宮古市の負担がないような工夫をさらにお願い、これは要望なんですけれども。","respondent":"武内地域活動課長","answer":"そういう中で共通商品券等をプレゼントしていくということですので、それは一種の事例としてパンフレットには載せますけれども、それはやっていく中で、またポイント的な、この団体にはこういう希望があればということで。","voiceIndex":63,"id":"exchange-019"},{"speaker":"本多委員","kind":"質問・要望","question":"被災地支援ということでは、配慮するところは配慮されて、工夫をして、よろしくお願いしたいと思います。次に移るんですが、町会会館、先ほど対象が３６件ということなんですけれども、昭和５６年の新耐震の前が３６件が対象ということなんですけれども、概要として区内に二百幾つ町会があって、新耐震の後にあるのが何件とか、その基礎データをちょっと教えていただきたいんですが。","respondent":"武内地域活動課長","answer":"２０４町会・自治会がありまして、町会会館を持っているのが８０カ所です。３６会館が昭和５６年以前の建物です。","voiceIndex":65,"id":"exchange-020"},{"speaker":"本多委員","kind":"質問","question":"先ほどから出ている扇風機の件なんですけれども、予算が成立した後、１００強の発注をしていくということで、発注作業は経理側になると思うので総務委員会のことですから、その発注の仕方などは聞きませんけれども、担当所管として、これだけの電気製品を購入するという意味では、先ほども量販店からは買わないという答弁もあったかと思うんですけれども、区内の経済効果も刺激できるような。","respondent":"武内地域活動課長","answer":"その辺のところは、委員言われるとおり、電気屋さんといっても結構いい値段になりますので、区内の電気屋さん、特に地域センターですと、簡単な工事、電球だとか、そういうものも購入するような電気屋さんに見積もりをとりまして。","voiceIndex":67,"id":"exchange-021"},{"speaker":"石田副委員長","kind":"確認","question":"扇風機等を買って節電をしていこうという試みなんですが、これは今年だけのことでやっているのか、それとも長期的に見て、これからは冷房は２８度で扇風機でやっていこうという、区の方針を改めてお聞かせください。経営相談、先ほど１名増加と聞こえたんですが、１名で４００万円の報償費が計上されているのか、その確認をさせてください。","respondent":"武内地域活動課長、福島ものづくり・経営支援課長、安藤文化スポーツ振興課長","answer":"来年以降ももちろん２８度設定というアドバルーンは、当然認識は変わりませんけれども、区民集会所といえどもサービス的な部分もありますので、来年以降。これは１人が全部をやるということではなくて、さまざまな方にお願いしながら全部を埋めていくという形をとっております。荏原文化センターの改修のことですけれども、ご案内のとおり、荏原文化センターは昭和４５年に設置して、平成２年に大規模改修をするなど。","voiceIndex":69,"id":"exchange-022"},{"speaker":"石田副委員長","kind":"質問","question":"区役所のアドバイザーの件なんですが、今、大手の民間企業はわりと導入して、自分たちがどのような、結局大きいところだと、冷房を例えば２８度にして、パソコン等も今は多いですから、室内の気温が上がっている中で、費用対効果というか、仕事を暑い中でやって効率が悪くなるとか、そういうのもあるので、そういった意味ではこういった節電をやるときには。","respondent":"福島ものづくり・経営支援課長","answer":"区役所は区役所で専門家を雇って節電効果をやっていると聞いていますけれども、こちらのほうはあくまでも区内中小企業支援という形で組ませていただいている予算ですので、ご理解いただきたいと思います。","voiceIndex":73,"id":"exchange-023"},{"speaker":"宮崎委員","kind":"質問","question":"今回、一般質問でゴーヤなんかを学校でもやったらどうだとか、学校だけじゃなくて、区の施設でも、建物そのものを暑くしない、冷やしていくということをあわせてしっかりやっていく必要があるんじゃないかと思うんですね。そういうコンクリートのまちがどんどん広がっている中で、ヒートアイランドがあるわけですから、そういうものをしっかりやってほしいです。これはちょっと注文しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-024"}]},{"id":"topic-03","title":"区民まつりにおける国際交流事業の紹介","agenda":"区民まつりにおける国際交流事業の紹介","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"目的が外国人のコミュニティだと思うんですけれども、特にその中の１つの事業だと思うんですけれども、今回、地震があったじゃないですか。その中において、地域の中のコミュニティというのがものすごく大事だと思うんですけれども、それに関して、大きい意味で課長はどういうふうに推進してやっていこうと考えているのか、改めて教えていただきたいと思います。","respondent":"今井協働・国際担当課長","answer":"ですので、今、私ども考えておりますのが、外国人だけのコミュニティをターゲットしたものを１つ考えておりますが、それ以外にも、地域の中での日本人と外国人との交流、連携というものを大きく主眼として考えているところです。","voiceIndex":90,"id":"exchange-025"},{"speaker":"山元委員","kind":"質問","question":"八潮には外国の方がたくさんいらっしゃって、私も英語ができないので、ジェスチャーで何とか頑張っているんですけれども、特に八潮は、外国の方が多いんですが、小学校の、さっきも課長のほうから交流というお話がありました。地元の方たちが学校に交流施設ができるみたいな、何かそういう考えがあるのかどうか教えてください。","respondent":"今井協働・国際担当課長","answer":"いずれにしましても、外国人の方からそういう声がかかったときには、私どもがその窓口となって学校の交流を進めますし、また区内にあるそういった大使館などにも、私どもからそういう場がありますよということはご紹介しています。","voiceIndex":92,"id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2608#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":34363,"voices":97}},{"id":"h23-20110627-7","meetingId":"h23-cm06","date":"2011年6月27日","dateIso":"2011-06-27","committee":"厚生委員会","time":"午前１０時００分～午後１時４５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第３２号議案、平成２３年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第３２号議案、平成２３年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"現在、どういった対策がとられているのか。それから、障害者用のところで、ストマ用品などということですけれども、住民からは、障害者は地べたに寝ころがってしまうと、そのまま立てなくなる、起き上がれなくなるので、簡易ベッドが欲しいというような声もありますので、その辺のお考えはどうでしょうか。","respondent":"原高齢者福祉課長、永尾障害者福祉課長","answer":"今、１８０名の数字を述べさせていただきましたけれども、今後、停電があったときに、その機械が使えるのかどうかということも含めて、今、現場のほうでご家族の方を含めて確認しながら対応をとっているところです。車いすの方につきましては、現在、使っている車いすは、ある程度リクライニングもできますので、その辺での対応と、簡易ベッドはちょっと難しいのですけれども、エアマット等で、現在、考えているところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"次の質問に移らせていただきます。２１ページの２４時間対応定期巡回の、国のモデル事業のほうですけれども、今までは、夜間の対応訪問サービスのみだったと思うんですけれども、今まで、どのぐらいの利用があって、どういう中身で利用されていたのか、そして、区はどういう評価をされているのか、お聞かせいただきたいと思います。","respondent":"原高齢者福祉課長","answer":"２４時間対応定期巡回の関係ですけれども、夜間帯の夜１０時から朝７時までのサービスということで、ケアマネージャーが、ご家族、ご本人のお話を聞きながら、その方に合ったケアプランをつくりまして、排泄介助であるとか、トイレ介助であるとか。","voiceIndex":8,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今回、対象者は変わってくるのかどうか、認定をされている方すべてなのか、要支援の方なのか、要介護の方なのか。それから、対象者の人数は何人ぐらいをモデルにされているのか。モデル事業者はどこになるのか、変わられるのか、どうか。この事業は、期間はいつからいつまでになるのでしょうか。こういった事業を、ほかにもやっている自治体はあるのでしょうか、お聞かせいただきたいと思います。","respondent":"原高齢者福祉課長","answer":"人数ですけれども、先ほどの期間とも関係しますけれども、８月から実施をするということと、国のモデルということで中間報告をするというような期限もありますので、それに合わせて、最初は５人でスタートしたい。それから、途中から１５名ということで考えております。","voiceIndex":10,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"次の高齢者熱中症等予防対策事業ですけれども、今回、シルバーセンターがシェルターになっているということですけれども、節電の関係で、１日１館が休館になっていくとお聞きしましたけれども、シェルターとして使われるのであれば、休館しないほうがいいのではないかと、率直に思うんです。クーラーの設置率なんかがわかれば、教えていただきたいと思います。","respondent":"間部高齢者いきがい課長、原高齢者福祉課長","answer":"今のところ、日に１館休館するということで、１６館のうち１５館は開館しているということで、お近くの開館しているセンターへご案内するということで、基本的には考えているところです。当然、個別にということになってまいりまして、高齢者の中でも、特にリスクの高い方については、ケアマネージャーの訪問の際に、熱中症に対する啓発をしていくと同時に、７月から民生委員の協議会、また定例ですので。","voiceIndex":12,"id":"exchange-004"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１９ページの高齢者用、障害者用の防災用品整備というところで、もうちょっと詳しくお聞きしたいんです。それから、先ほど、在宅酸素、人工呼吸器、たんの吸引器を使われている方の人数が約１８０名ということだったのですが、これは三つ合わせた数が約１８０名ということなのでしょうか。それであれば、それぞれの数がわかったら教えていただきたい。","respondent":"原高齢者福祉課長","answer":"こちらのほうは、基本的に在宅の方で、中には充電式を持っていたとしても、充電が十分にされていなかったという緊急の場合がありますので、そういったときに、当然、訪問看護ステーションといったところで十分に把握して対応するのですけれども。","voiceIndex":15,"id":"exchange-005"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"やっぱり、予防・啓発ということで、熱中症がどれほど危険なものなのか、どう対応すべきなのかというあたりを知識として持っているということがほんとうに大事なのではないかと思いますので、１点、お聞かせいただきたい。シェルターと銘打って対策ということであれば、ここはもうちょっと何とか検討ができないのかという思いがするのですけれども、いかがでしょうか。","respondent":"原高齢者福祉課長、間部高齢者いきがい課長","answer":"２４時間対応定期巡回の関係ですけれども、こちらは国のモデルということで、これからいろいろ報告も出していくことになりますけれども、一つは、コールがあったときに、それが別料金かどうかという話だったかと思います。今、実際にシェルターでどのようなことをするかということも検討しているんですが、これから配られるうちわ等もそうですし、ある程度、スポーツドリンク等を窓口で差し上げるという中では。","voiceIndex":17,"id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"幾つかお伺いしたいと思います。では、その財源はどうするのか。品川区は、２３区は、財源的には非常に恵まれているほうだと思うので、そのぐらいは区の中でやっていきますという考え方なのか、どうなのか。そうなってくると、ここら辺は２３区共通で支援していくんだとしたら、国、東京都、そこら辺からどういう、例えば予算づけというのか、そういうあたりは、被災の関係については求めていくのか。","respondent":"原高齢者福祉課長","answer":"今後はどうかですけれども、こういったところは、今の時点ですべての状況を点検し終わっているということではございませんで、緊急に対応していくもの、それから、少しいろいろな情報を集めて対応していくものということで。","voiceIndex":20,"id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問","question":"国、都、今、補正予算等があって、そういうものは各自治体もそこについては手当てをすると思っているのか。場当たり的でいくと、今、震災対策特別委員会でも、災害をいろいろやり出しているから、この１年間の後では、提言も出るのでしょうけれども、所管として、それはしっかり予算要求していくものはあるはずだから、そこらの辺の物事の考え方を、改めて教えてください。","respondent":"工藤生活衛生課長、原高齢者福祉課長","answer":"私のほうからは、被災地の職員支援派遣費を組んでおりますので、そちらのほうについて、少し詳しくご説明します。こちらのほうは、国、厚生労働省から、地震の翌日に、東京都、特別区のほうに、保健師等の要請依頼があったです。先ほど、補正のところで、緊急的なものを中心に、ということでお話しさせていただきましたけれども、これですべて終わりというわけではございませんで、継続して、何が足りないのか、あるいは、今後。","voiceIndex":22,"id":"exchange-008"},{"speaker":"若林委員","kind":"質問・要望","question":"私も何点かお聞きします。それですべてであれば、それで結構ですが、細かい品目等を教えていただきたいと思います。それから、２１ページの安否確認ですが、これはモデル事業ということで、手を挙げていただいたので、ぜひ発展的に取り組んでいただきたいと思いますが、とりあえず、中間報告の時期、それから委員会への報告はしっかりお願いしたいと思いますけれども、いかがでしょうか。","respondent":"原高齢者福祉課長、永尾障害者福祉課長","answer":"民生委員の関係ですけれども、３月１１日の対応です。１件、１件、全部の民生委員に対応を確認したということではございませんけれども、３月、あるいは４月に民生委員協議会を実施しておりまして、その中で報告を受けているところです。視覚障害者は、ちょっと見た目ではわからないということで、やはり白杖がないと、目が見えないということが理解できない方も多いということで、白杖についても、予備ということで用意してあります。それからあとは拡大鏡。","voiceIndex":25,"id":"exchange-009"},{"speaker":"若林委員","kind":"確認","question":"品川区全体での熱中症のところは、さっきの答弁で終りですか。それから、もう一つ、１９ページのバッテリーの関係ですけれども、国のほうから通知があって、注意をするようにという通知が、各病院に行っているという理解でよろしいのでしょうか。はその病院にお任せということでよろしいのか、あえて区のほうで対応していますというものがあるのか、そこを最終確認させてください。","respondent":"原高齢者福祉課長","answer":"そういった中では、私ども、連絡会等を通じてやってありますけれども、そういったものを含めてトータルで考えていく必要があると認識しています。","voiceIndex":28,"id":"exchange-010"},{"speaker":"鶴委員","kind":"提案","question":"２３区の中でも、イベントをそこに設定して、お集まりいただけるような工夫をしている自治体もあると思うんですが、そうした考えが、品川区にもあるかどうか。もう一つが、先ほども話が出ておりましたが、熱中症シェルターですね、ネーミングがもう少しソフトというか、柔らかいというか、集いやすいような名前も考えたらどうかと、これも一つ提案ですけれども、そう思いました。","respondent":"間部高齢者いきがい課長、原高齢者福祉課長","answer":"今回、節電という切り口ではありますけれども、そういった意味で、高齢者の活動する場ということを、改めて認識していただけるような対応をとってまいりたいと考えています。一つのものですべてを賄うことはなかなか難しい状況もございまして、もう一つ考えているのは、エアコンもない、あるいは扇風機も置いていないという家庭も、中にはございまして、そういった方々に対して、シェルターの話も。","voiceIndex":30,"id":"exchange-011"},{"speaker":"鶴委員","kind":"提案","question":"イベントに関しては、高齢者クラブに加入していただくとか、いろいろご提案がありました。それから、先ほどちょっと、品川区でどのぐらいの方が、そうしたところに集まっていただくと、採算性がとれるのか、これはちょっと専門的なことなので、あれですけれども、わからなければ結構ですが、もしわかればちょっと教えていただきたいと思います。","respondent":"原高齢者福祉課長","answer":"どのぐらいの方がシェルターをご利用になると、というような試算ですけれども、そこまで、今の段階では試算をしてございません。","voiceIndex":33,"id":"exchange-012"}]},{"id":"topic-02","title":"平成２３年請願第１４号、国保料の引き下げと区民説明会を求める請願","agenda":"平成２３年請願第１４号、国保料の引き下げと区民説明会を求める請願","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"６月１５日に納付書が一斉に配布されたということですけれども、それで問い合わせも多数あったということですが、電話と窓口それぞれ、細かい数字をお教えいただきたいと思います。それから、問い合わせの中身は、どういったものだったのか、お聞かせください。","respondent":"本城国保医療年金課長","answer":"そのほか、納入通知書の内容のご説明ですとか、あるいは、いつ払ったらいいのかとか、そういう件とか、その他種々のお問い合わせがあったところです。","voiceIndex":48,"id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問","question":"経過措置は２年間とられるということですけれども、３年後には、全部がどんと上がってしまうということですので、納付書でもわかりづらい部分は多々あるわけですから、説明会を開くのは大事な対策ではないかと思うんですけれども、いかがでしょうか。","respondent":"本城国保医療年金課長","answer":"今も、ほんとうにたくさんの電話をいただいていますように、その方の所得が幾らかとか、そういうことを細かくデータを見ながら説明することで、初めてわかりやすいご説明になると考えておりますので、これからも、一般的な説明はパンフレット等でやったのを踏まえて。","voiceIndex":50,"id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"やはり、今のこういう生活も大変な状況の中で、国民健康保険料が上がるというのは、生活の中では一大事だと思うんです。それがしっかりと説明をされてこそ、区民の理解も得られると思いますので、説明会の開催は必要なものだと、私は考えます。そして、経過措置の部分に、高額療養費を、費用相当額として参入させるということですけれども、これはなぜ、高額療養費なのでしょうか、お聞かせください。","respondent":"本城国保医療年金課長","answer":"説明会のことにつきましては、繰り返しになって恐縮ですが、個々の状況は、ほんとうに千差万別ですので、お一人おひとりに対して、窓口、あるいは電話で丁寧にご説明をしていきたいと考えているところです。","voiceIndex":52,"id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問","question":"経過措置が２年間ということで、ここに高額療養費が使われると。４分の３が減額措置だけれども、３年後には、この４分の３が一気にどんとかかってくるわけですよね。この経過措置をもうちょっと長期間取るということはできないのでしょうか。","respondent":"本城国保医療年金課長","answer":"今回も、そういったことも踏まえて、一番円滑にいくには、２年間、その後、本則に至るという形で想定しています。","voiceIndex":54,"id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"２年の間に区民にどうしろというのか、ちょっと素朴に思ったのです。３年後には、一気に２倍以上に跳ね上がる方もいらっしゃる。かといって、この２年の間に収入が上がるわけではないわけですから、ほんとうにもうちょっと丁寧な対応が必要だと思います。今現在の滞納者世帯、またそのほか資格証や差し押さえ、短期証など、件数をお聞かせいただきたいと思います。","respondent":"本城国保医療年金課長","answer":"一方で、先ほどの短期証世帯と資格証世帯ですが、年度末の数字ですが、資格証については１３５世帯、短期証については３,９７４世帯という状況になっております。差し押さえの件数ですが、途中の時点の数値ですが、１０月時点では９６件です。","voiceIndex":56,"id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問","question":"今、お聞きしたように、やはり滞納されている方、収納率は８３.３１％ということですけれども、これだけ短期証や資格証、差し押さえが出ているということで、今の区の収納率をどう考えておられるのか、教えてください。","respondent":"本城国保医療年金課長","answer":"収納率の状況を見ますと、先ほど、ご説明させていただいたように、今年度は、そういうことで前年と比較して微減になって、その前も微減ということで、平成１８、１９年度という場面では向上していたものが、今は若干微減傾向にあります。","voiceIndex":58,"id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"質問","question":"国民健康保険料もそうですけれども、今の状況のもとで、税金も上げられて、ほんとうに生活も逼迫していると思うんです。家賃を払って、税金を払って、国民健康保険料を払ったら、それこそ病院に行かれないというような生活をされている方も、ほんとうに増えてきている状況です。区民の実態としては、どのようにお考えでしょうか。","respondent":"本城国保医療年金課長","answer":"今、ご説明させていただいたところと重複してしまうかもしれませんが、そういう厳しい経済状況であるということで、そういうことを踏まえまして、先ほども均等割の説明の中でご説明しましたが、通常であれば、医療費がこれだけ上がってくる中で、保険料が変わらないということは。","voiceIndex":60,"id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"こういう実態に対しては、どう考えられているのでしょうか。窓口の方は、こういう実態をお聞きになっていると思うんですけれども、そういう窓口の苦情、それから、問い合わせ、ここまでの値上げを強いるということに対して、納付書を送られた後の区民のこういう実態に対して、どう考えられているかということについて、まずお聞かせいただきたいと思います。","respondent":"本城国保医療年金課長","answer":"社会保険の制度としての国民健康保険料としては、税とは構成原理自体が異なっているということも、あわせてご認識いただければと思うんですが、税については、所得控除等々、いろいろなことをすることによって、可能な限り可処分所得を把握して、負担能力に応じて際限なく。","voiceIndex":62,"id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"このことに対して、どう考えられているのか、ひとつお聞かせいただきたいと思います。それが、今や３万９,９００円ですから、去年からは据え置いたとしても、これそのものが、ほんとうにずっと毎年上がり続けていて、低所得者にとって、ほんとうに大変な事態になっているという、そこのところは、ぜひとも認識していただきたいと思うんですが、そのことについて、一つお聞かせいただきたいと思います。","respondent":"本城国保医療年金課長","answer":"順番は前後するかもしれませんが、まず、均等割の、今までの増加につきましては、冒頭のご説明でもさせていただきましたように、医療全体の上げ幅と連動するような形で保険料も上がってくる中での均等割の推移ということで、改めて、ご理解いただければと思います。","voiceIndex":64,"id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"高齢者。それをあえてそういうふうに、区のほうが、一般財源を投入するというのはおかしいということ、そのことが、私は納得いかないし、今までは、高額療養費という形でずっと入れてきたわけですから、これを減らすのではなくて、これからも続けていっていただきたいと思います。このことが１点です。そういうところに対しては、区としては、どう考えられているのでしょうか。","respondent":"本城国保医療年金課長","answer":"その他、先ほどの一般財源の投入にもかかわる話ですが、私が申し上げましたのは、これだけ一般財源を投入しているということ自体、特別区の国民健康保険を支えている姿勢が、まさにあらわれているところだとご認識いただきたいという意味でお話ししました。","voiceIndex":66,"id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういう状況が、私は、品川区の中で広がっていると思うんです。だけれども、その２３区であっても、これだけ大変な実態が起こっているというところで、ぜひ、一般財源を引き下げないという方向でやってほしいということが一つです。そういう点では、国庫負担を増やすということに関しては、区民の思いも、品川区の思いも、国の思いも一致すると思うんですけれども、その点ではいかがでしょうか。","respondent":"本城国保医療年金課長","answer":"そのような中で、２３区を含めた全国市長会自体も、国民健康保険の構造的な弱さに対しては、国に応分の責任を果たしていただくということは、それはそれでとても大切だということは十分に認識しておりますので、全国市長会等があるたびに、国民健康保険財政に対する支援は。","voiceIndex":68,"id":"exchange-023"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そうすると、１兆円を超えて国庫負担が増えるということになるんです。そういう点からも、私はこれは、ぜひとも、区のほうからも求めていただきたいと思いますけれども、ひとついかがでしょうか。変更になったことは、仕組みとして変わったわけですから、なぜこんなに値上げになるのかというところを、ぜひ説明責任を果たしていただきたい、このことをお聞かせいただきたいと思います。社会保障なんですよ。","respondent":"木下健康福祉事業部長","answer":"２点目、説明会の問題ですけれども、品川区としては、新しい制度が始まるとき、例えば介護保険制度もそうでしたし、後期高齢者医療制度が始まるときも、地区別説明会を行いました。","voiceIndex":71,"id":"exchange-024"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"区民に対して、そういうふうな言い方は失礼だと思いますし、何を指して特定の考え方と言われているのでしょうか。私は、ぜひとも取り消していただきたいと思います。そういう形でいっぱい意見が出たのであれば、もっともっとたくさん説明会を開けばいいではないですか。そういう形で、区が説明責任を果たすべきだし、そういう場面で、区民の声を区が受けとめるという姿勢こそ、持っていただきたいと思います。","respondent":"木下健康福祉事業部長","answer":"後期高齢者医療制度のときの説明会というところで、言ってみれば、制度に反対だというお話がたくさん寄せられたということでありまして、そういう客観的な事実を申し上げたところです。","voiceIndex":73,"id":"exchange-025"},{"speaker":"石田（秀）委員","kind":"質問","question":"結論から言いますと、不採択であります。生活保護までに至るのかどうかという問題があるけれども、その前については、やはり今の状況の中では、ご負担をいただく部分が出てきて、いたし方ないだろうと考えていますし、これは皆さんに聞かれても、我々会派としても、そういうスタンスで臨んでいるということであります。ですから、我々は、総合的に意見を言わせていただくと、この請願については不採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-026"},{"speaker":"若林委員","kind":"質問・要望","question":"理由は、残念ながら、制度的な旧ただし書き方式の中で、区民の約２５％の方々に保険料の値上げがあるといったことから、引き下げという請願が出されたわけですけれども、今の議論を聞いていてもわかりますように、国民健康保険で言えば、これまでも、私ども従来から言っておりますとおり、国全体、都道府県、取っ払った国全体の一元化でありますとか、また、公費負担。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-027"},{"speaker":"向委員","kind":"質問","question":"先に結論から申し上げると、不採択です。請願項目１、国保料を引き下げてくださいということに関しては、品川区としてのお考えもお伺いしまして、重々理解できまして、会派としても話し合いを行いまして、こちらについては、先ほどおっしゃっていましたが、やはり公平性の確保もあると思いますので、今回、不採択ということで、申し上げします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この不況のもとで、ほんとうに生活も大変になっている中で、健康や命を守るはずのこの制度が、命を奪うものになっている、社会問題になっているということで、今、議論の中にもありましたけれども、新しい算定方式に変えることで、２万３,０００人の方が負担増になるということを、もっと重大に受けとめていただいて、国民健康保険を、命を守る制度にしっかりとするために、払える保険料にしていくためにも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-029"},{"speaker":"鈴木（博）委員","kind":"意見","question":"請願者の方のお気持ちは、非常によくわかるんですが、国民健康保険料の引き下げに関しましては、これは保険全体の制度の問題もありますので、これだけ引き下げるというのは、賛成しかねるところがあります。無所属品川に関しましては、結論的に言えば、不採択ということで態度表明をしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":86,"id":"exchange-030"}]},{"id":"topic-03","title":"平成２３年陳情第３号、品川健康センター７Ｆホールに鏡の設置を求める陳情","agenda":"平成２３年陳情第３号、品川健康センター７Ｆホールに鏡の設置を求める陳情","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"鏡のあるフロアがあるということですけれども、サークル等が使えるようにはならないのでしょうか。エスフォルタに任せているということですけれども、ここを一般のサークルが使えるようにはならないのでしょうか。","respondent":"小川健康課長","answer":"そちらの部分につきましては、先ほど申し上げたました健康づくり施設と位置づけておりまして、１年を通じて、全体に１００以上のコース型教室を、もう既に組んでおりまして、一般の方がご利用をするということは、基本的には難しいかと考えます。","voiceIndex":94,"id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問","question":"私は、簡単に言うと、多くの区民が使える形がいいと思うので、賛成ですけれども、お伺いするのは、もしやるとしたら、どこにつけると考えるのか。７階だけそう思うのか、３階の会議室も、あそこは会議をやっているけれども、同じような考え方で使っている場合もあるから、それはどう考えるのか、それをお聞かせください。","respondent":"小川健康課長","answer":"ただ、だからと申しまして、８ｍ全面に鏡を取りつけるのは、基本的には難しいということで、専門の業者に見てもらったところ、構造上、幅約１ｍぐらいの鏡を４枚から６枚程度取りつけることが可能だということを聞いております。","voiceIndex":96,"id":"exchange-032"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そうすると、あそこはどういうふうにやるのか。手すりをつけるのかどうかわからないのですけれども、そこら辺の物理的なことを、多分、もう調査をかけられていると思うので、ほかの施設もどうなっているのか知らないけれども、ついているところがあるなと、私もそこまで全部見ていないからわからないけれども、そこら辺の点を、もう一度教えていただきたいと思います。","respondent":"小川健康課長","answer":"他の団体が利用したときに使い勝手が悪くならないような形でいろいろ配慮が必要ではないかとは、認識しています。","voiceIndex":98,"id":"exchange-033"},{"speaker":"石田（秀）委員","kind":"意見","question":"先ほど言ったように、ぜひ安全面だけ。そうすると、そこの壁にくると、今言った安全性の問題で１２cm出るのであれば、やっぱりそういう形をとらないとだめだと思うし、もう一段言わせていただくと、あまりその工事のために何日も休館するのはやめたほうがいいと思うので、それこそ１日とか２日でやる方向を考えたほうがいいと思いますし、そこら辺のところは配慮していただければ、と思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":100,"id":"exchange-034"},{"speaker":"向委員","kind":"質問","question":"どれぐらいの期間、実際に１３カ月前から予約ができると伺っていますので、今利用されている団体にとっては、使えない時期が長期になるといけないと思うんですが、安全性の面を考えると、しっかり壁の補強とかをしないといけないと思うんです。そのあたりを、ご説明いただければと思います。","respondent":"小川健康課長","answer":"専門業者の話では、こちらの構造上、安全確保のために壁の補強が必要だということで、工期については、５日から７日間程度かかるということを聞いております。","voiceIndex":101,"id":"exchange-035"},{"speaker":"若林委員","kind":"質問","question":"これまで、指定管理者は、こういう声をどのように聞いていたのでしょうか。そして、区はどのようにお聞きになっていたでしょうか。これまでの検討状況と、今回は、陳情という形で、あえて出されたんだと思いますが、そこら辺、ちょっと状況を聞かせてください。","respondent":"小川健康課長","answer":"指定管理者は、平成２１年度からなんですけれども、基本的に、窓口でのお問い合わせとして、鏡はありますかという問い合わせは多いということですが、鏡をぜひ取りつけてほしいという声は、指定管理者の窓口にも、また区の窓口にも、特にここ何年かは挙がってきてございません。","voiceIndex":103,"id":"exchange-036"},{"speaker":"若林委員","kind":"質問","question":"わかりました。さっき、１ｍ×数枚ということでしたが、１ｍというのは縦の長さですか、横の長さですか。要するに、縦と幅は、どういう大きさですか。","respondent":"小川健康課長","answer":"簡易な見積もりではありますが、縦が１,８９０mm、幅が１,０５９mm。それが鏡１枚の縦横です。それが、スライド式になると４枚程度になるだろうです。","voiceIndex":105,"id":"exchange-037"},{"speaker":"若林委員","kind":"意見","question":"わかりました。いずれにしても、取りつけることによって、より区民へのサービス向上ということで、前向きにとらえていきたいと思います。それから、２点目の、早急な対応って、例えば、この委員会が終わって、スケジュール的にどんなふうになるのか、早急なというのは、何かスケジュールを考えていますか。","respondent":"小川健康課長","answer":"ですので、経費的なこともありますが、実際の工期についても、それ以降、きちんとまとまった期間を、工期として押さえておく必要があろうかと考えます。","voiceIndex":107,"id":"exchange-038"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"利用されている方が、ダンスが３０％ということで、かなりこういう要望を持っている方はたくさんいらっしゃるんだろうなと、改めて思ったんです。そういうふうなところから、要望にこたえて鏡はぜひともつけていただきたいと思うんですが、鏡の種類として、キャスター付の鏡もあり得るということもお聞きしたんですけれども、その検討はされたのか、ちょっとその点だけお聞かせください。","respondent":"小川健康課長","answer":"キャスター付の鏡につきましては、保管の場所ですとか、また、持ち運び等の安全面等を考えますと、なかなか難しいかなと、こちらでは検討しています。","voiceIndex":111,"id":"exchange-039"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"私も、できればしっかりとしたもののほうがいいのではないかと思うんですけれども、ここでは、ぜひ早急な対応を望みますということですので、何とかそこら辺のところを、来年度予算で１年後というよりも、もっと早くにつけるという可能性の検討はできないものかと思うんです。","respondent":"小川健康課長","answer":"こちらの施設のいろいろな部分での優先度ですとか、いろいろなこと考えますと、やはりきちんと予算取りをして、来年度に向けてということが望ましいと思いますし、その間につきましては、区内でも鏡のある施設もありますので。","voiceIndex":113,"id":"exchange-040"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"先ほども言いましたけれども、私は、多くの区民に使っていただきたいと考えています。高齢者の方々も、ここは、ダンスとかでも多く使われていると思いますので。そういうことの中で、ちょっとだけ違うことを言いますが、ぜひそれに合わせて準備室２の扱いも考えてほしいと思いますけれども、基本的に、この陳情は、私の意見は採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":123,"id":"exchange-041"},{"speaker":"向委員","kind":"質問・要望","question":"結論から申し上げると、賛成です。やはり、今、数字で出ている稼働率４８％で、そのうちダンスの使用率が３０％というのは、駅から歩いて１分ぐらいというあの立地条件を考えると、もっとどんどん使っていただきたいと思いますので、工期の問題、コストの問題をいろいろ考えながら、早急に対応していただければと考えます。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-042"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私も、結論から言うと、賛成です。向委員と同様に、たくさんの方に使っていただけるということや、やはり、鏡がないところでのダンス教室は、想像しただけでも、やる気やモチベーションの面で難しいと思うので、ぜひつけて、皆さんに元気に使用していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-043"},{"speaker":"山内委員長","kind":"質問","question":"その他を行います。私のほうから、今定例会の一般質問にかかわる所管質問について、ご案内申し上げます。本件は、委員会活動の活性化という観点から、各常任委員会において、当該会期中の一般質問にかかわる当該委員会の所管質問を行うというものであります。本会議での質問の繰り返しにならないようお願いいたします。所管質問がございましたら、ご発言をお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-044"},{"speaker":"石田（ち）委員","kind":"質問","question":"石田秀男議員の質問の特別養護老人ホームのところで、有利に取得できるよう多面的な情報収集に努めるという、その有利なというのはどういうことか、そして多面的な情報収集というのは、具体的にお聞きしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":131,"id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3296#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":49572,"voices":133}},{"id":"h23-20110627-8","meetingId":"h23-cm06","date":"2011年6月27日","dateIso":"2011-06-27","committee":"建設委員会","time":"午前１０時００分～午後０時０９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２３年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"平成２３年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"武内委員","kind":"質問・要望","question":"内容が多岐にわたるので質問も多くなってしまって申しわけないのですが、２５ページの放射線量測定器購入２台、これは年内に間に合うかどうか調べているのでしょうが、大体いつぐらいに納入できるのかということと、あと購入した後どういうふうに使う予定なのかということを教えていただきたい。最後に同じページのＬＥＤについても、もうちょっと詳しく。","respondent":"野呂瀬環境課長、品川防災整備担当課長、藤橋都市整備下水道課長、柏原住宅担当課長","answer":"どういう、どれぐらいのものをという、多分景品のことだと思いますけれども。住宅の除却工事につきましては、費用全体の２分の１を助成することを考えております。今回の高潮・津波に対する基礎調査につきましては、ハード対策というよりも警戒避難方策を考えるための基礎調査という位置づけで実施するものです。件数としましては一般住宅で３０軒ほど、マンションや賃貸住宅等々も想定していまして、そちらのほうは４軒ほど。","voiceIndex":5,"id":"exchange-001"},{"speaker":"武内委員","kind":"質問","question":"それから一般質問でもお伺いさせていただいたんですが、全体で３４軒見込んでいるということで、考え方はいろいろあると思うんですけれど、やはり７月１日からいよいよ１５％の節電も始まる中で、非常に今関心を皆さん持っている中で、かといって過度な節電をしてしまうと熱中症等の問題が出てくることが心配されている中でお願いするという意味で言えば。","respondent":"野呂瀬環境課長、品川防災整備担当課長、柏原住宅担当課長","answer":"ただし、精密機械ということもありますし、取り扱い方の説明とかもありますので、個人のお宅とかというところまでの貸し出しは考えてございません。区としてもこの制度をまず出しまして、空き家の持ち主の方がどういう対応をとるかというところを様子を見ていきたいと考えております。そういったところも見ておりますので、電球取りかえだけということにつきましては、個人で対応していただくものであろうという判断もありまして。","voiceIndex":10,"id":"exchange-002"},{"speaker":"武内委員","kind":"質問・要望","question":"ありがとうございました。節電コンテストをやるということで５,０００世帯となっているのであれなんですけれど、そういう考え方もぜひ、ここではもう無理かもしれませんけれども、今後取り入れていただきたいと思いますので、とりあえず要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-003"},{"speaker":"井上委員","kind":"質問・要望","question":"それから次のページの防災普及教育費のところのシステム開発委託９００万円なんですけれども、地図が小さくて見にくいとか、水の災害とか、いろいろなことで地図がかぶっていてと、そういう対策もあると思うのですが、ここからまたすぐ一歩進んでシステム開発ということですが、そういう研究をどんどんやることはいいのかもしれないですけれど、本当にそういうものが使い勝手がいい。","respondent":"中山防災課長、藤橋都市整備下水道課長、岩田都市環境事業部長","answer":"初めの質問の毛布のクリーニングですけれども、議員ご指摘のとおり、せんだっての帰宅困難者対策で使用した毛布２,７００枚です。さらに調査結果を踏まえまして、高潮・津波対策の課題を整理し、適切な避難対応などの検討を行う予定です。先ほどの毛布等の財源補正の関係なんですけれども、政府は一応、新聞報道によりますと、東北３県への支援とか復旧に他の自治体が予算を支出した場合は。","voiceIndex":15,"id":"exchange-004"},{"speaker":"井上委員","kind":"質問","question":"先ほどの防災システムのところですけれども、開発だからこれからやっていこうという補正をつけているんだと思うんですけれども、そういうことが突如ここに、３月１１日でこの補正になったのか、こういったことを考えていて、必要であって補正にしたのかというところなんですけれど、先ほどお伺いしていたら、ツールとしてパソコンを見られる人とか帰宅困難者対策の誘導とか。","respondent":"中山防災課長、片田防災まちづくり事業部長、岩田都市環境事業部長","answer":"３月１１日の東日本大震災によってこれを持ち出したわけではございません。ただ一応それを重ね合わせて、防災情報のところを加えて一体の地図の中で検索できるようなものを考えている状況です。だからこれは直後の対応にどうするかというよりは、いわゆる昔全戸配布しました防災地図、その地域。","voiceIndex":19,"id":"exchange-005"},{"speaker":"井上委員","kind":"質問・要望","question":"それからちょっと１点、大きなところで部長に答弁いただくのではないかと思うんですけれども、今回、節電用品購入ということで大きくいろいろな、環境課が主管だと思うのでここでお伺いするんですけれども、全部で６４７台の扇風機の購入ですけれども、これは２８度に設定して扇風機、また冷房のときにも使われるだろうという大きなところでは理解をするんですけれども。","respondent":"岩田都市環境事業部長","answer":"これは国もいろいろなマニュアルの中で、冷房温度を下げて個別には扇風機を活用してくださいということを言っておりますので、それに基づいて総務のほうが立案をしたというものです。それで冷房温度２８度というのは、昨年までの冷房温度２８度ではないんです、今回は。","voiceIndex":23,"id":"exchange-006"},{"speaker":"大沢委員","kind":"質問","question":"３１ページの建設型区民住宅管理費ですが、居宅内修繕委託ということですけれど、修繕するにはどんな基準があるのかということ、どのような内容によって修繕を行うことが満たされるのかということ、それでどれぐらいの戸数を見積もっているのかということの２点を教えてください。","respondent":"柏原住宅担当課長","answer":"ただこちらに計上させていただいた分については、ファミーユ西五反田の西館と東館、こちらは内部の間仕切りになっていますのが石こうボードだったのですが、こちらにひび割れであるとかそういったものが全体で１１９戸出まして。","voiceIndex":25,"id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"１７ページの災害時応急物資確保費ということで、毛布のほうは先ほど聞きましたけれど、備蓄物資購入費ということで、当然品川区のほうから宮古市に救援物資で出した補充ということが一つなんでしょうけれど、その中で足りないものを商店街から応援を頼んで集めて送ったということですが、その品目の中で足りなかったものについて、品川区でも新たに備蓄しようというような考え方のものはないんですか。","respondent":"中山防災課長","answer":"私どもが提供した物資以外で必要だと報じられたものに、アレルギー対応食品があります。これは人口の１％と言われているんですけれども、いわゆる厚労省が指摘しているアレルギーの対象２５品目を除いたものをこれから備蓄してまいります。","voiceIndex":27,"id":"exchange-008"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"そこをどういうふうに整理されているのか、まずご説明いただきたいと思います。土木としてチームで動いているということは理解しながらも、そこは伺いたいと思います。それとこの補正のことですけれども、補正で追加した事業の性格、位置づけについて伺いたいと思います。","respondent":"片田防災まちづくり事業部長","answer":"東京都の基本的な対策に対する方針等が出てくることを当然想定していますので、場合によって新しい状況が出てくるとすれば、第２陣としての補正ということも当然考えることだと考えていますので、状況を踏まえながら適正な、タイムリーな時期をとらえて。","voiceIndex":31,"id":"exchange-009"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"まだそんなに詳しく見ていませんけれど、転倒によるけがというのが１９％で多いなと思うのは、やはり地震発生時は慌ててしまうというところのあらわれなのかなと思ったんですけれど、それはよく研究する必要があると思いますけれど、そこをどうお考えなのか、１点伺いたいと思います。そことの関係で、先方自治体からどういう要請があるのか、そこをご説明いただけますか。","respondent":"片田防災まちづくり事業部長、中山防災課長","answer":"そういう状況を含めて、区のほうとしても対応を行っている状況です。日光の関係ですけれども、８月ですとあとわずかになってございまして、入所者の方々にも焦りが出てきているというようなことです。","voiceIndex":33,"id":"exchange-010"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"品川区に避難してきた方で今区民住宅にお住まいの方が２９世帯ありますけれども、やはり夏に向けてのクーラーの設置の要望が非常に強いんですね。こういう同様の動きがなぜできないのか、もしかして予算規模からすると補正まで組まなくてもというところがあるのであれば、夏に向けてこの対応をしっかりすべきではないかと思うんですけれども、いかがでしょうか。","respondent":"柏原住宅担当課長、品川防災整備担当課長","answer":"そもそもその６カ月についてどうするかというところについても今、まだ検討している段階です。冷房器具につきましても、そういった状況を見ながらというところがあります。９０％の件ですが、当然区としても一つの目標として動いているところです。この中で今、耐震改修、耐震建て替え、そのほかいろいろな方法がないかということで、今回除却というものを補正予算で上げている状況です。","voiceIndex":36,"id":"exchange-011"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"区民住宅のクーラー設置につきましては、夏ももう本番直前というか既に暑いわけですから、ぜひそこは進めていただきたいと思います。一方でこれは相手がある話ですし、いろいろご家庭の事情もある中でですから、そこにはいろいろな工夫や丁寧さも当然必要だと思いますけれども、今、耐震診断で２カ月待ちなわけですよね。ぜひそこは最後にご説明いただきたいと思います。","respondent":"品川防災整備担当課長","answer":"ただ、ほかにも東京都で耐震診断を登録している事務所に連絡をしていただければ、２カ月待ちにならない業者もありますので、もし急ぐ方については、こういったところを利用していただければいいというふうに考えております。","voiceIndex":39,"id":"exchange-012"},{"speaker":"大西委員","kind":"質問","question":"今のことに付随して日光の光林荘ですけれど、あそこは８月末までですか、今は食事の提供とかもされていると思うけれど、食事は大体１日当たりどのぐらいの金額を予算として出ているのかということと、区民住宅とかだったら当然自分たちで食事とかつくると思うんですが。","respondent":"中山防災課長、高山防災計画担当課長","answer":"議員ご指摘のとおりでございまして、現在７８名が入所しておりますけれども、やはり身の振り方のない人が１人でもあってはいけないということで、富岡町と頻繁に情報のやりとりをして、富岡町からも頻繁に来ていただいて。日光の食事代につきましては、１人１日１,０００円ということで計上しています。","voiceIndex":41,"id":"exchange-013"},{"speaker":"武内委員","kind":"質問","question":"品川区民の方でも、自分の持っているアパートがあいていて、そこを無償でいいから使ってくださいという声を実際に私もいただいていたんですけれども、前にお聞きしたときもそんなことも少し考えてみたいということをおっしゃっていたんですけれど、今、それはどうなっているんですか。東京都の動きと合わせて。","respondent":"柏原住宅担当課長","answer":"民間の方たちの住宅の提供という部分ですが、無償で提供したいという方やいろいろな方等いらっしゃったんですが、今回どのぐらいの期間、被災されてきた方が住むかということもありまして、例えば３カ月なら無償でいいよとか。","voiceIndex":44,"id":"exchange-014"},{"speaker":"武内委員","kind":"質問・要望","question":"いずれにしても７万５,０００円とか１０万円というのは被災者が払うわけじゃないですよね。もしそれがだめならだめでマッチングさせる努力をもうちょっとしてもらいたい気がするんですが、これは要望しておきますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-015"}]},{"id":"topic-02","title":"を行います。 初めに(1)の平成２２年度品川区一般会計予算事故繰越し繰越計算書","agenda":"を行います。 初めに(1)の平成２２年度品川区一般会計予算事故繰越し繰越計算書","exchanges":[{"speaker":"武内委員","kind":"質問","question":"事情はよくわかります。一番上の、７月からスタートすると、これで大体どれぐらい全体的に工期が延びたことになるのか。全部が全部そうではないと。そうするとその違いというんですか、一つ一つ個別のケースで違うのかもしれないけれど、何か傾向として、どうしてこの３つだけがこういう形になってしまったのかという理由が、ある程度わかっているのだったら教えてください。","respondent":"藤橋都市整備下水道課長","answer":"で、７月に入りまして、電線類地中化工事に着手し、７月中には終わる予定です。補助１８号線の事業自体は今年度も予定しているものがありますので、事業全体の工期の遅れは今のところ想定しておりませんで、来年度中に終わる見込みです。","voiceIndex":60,"id":"exchange-016"},{"speaker":"中塚副委員長","kind":"意見","question":"説明の中で、電線類地中化の部品をつくっている生産地が東北地方にあって、被災された影響でとのご説明がありましたけれども、ということはそこの工場が復旧しないと、要するに先々影響を及ぼしてしまうのか、そうはいっても全国的なところで何とかカバーし得るという判断なのか、そこをちょっとご説明いただけますか。","respondent":"藤橋都市整備下水道課長","answer":"詳細については、私どもではちょっと把握しておりません。それから東京電力以外の私どものほうの部品につきましても、想定していた会社から入らない場合はほかの会社に切りかえてという形で調達した事例はございました。","voiceIndex":62,"id":"exchange-017"}]},{"id":"topic-03","title":"専決処分の報告について（報告第１５号）","agenda":"専決処分の報告について（報告第１５号）","exchanges":[{"speaker":"武内委員","kind":"質問","question":"内容についてはわかったんですけれど、２月２１日の和解と損害賠償額の決定ということなんですが、その後に委員会はなかったですか、委員会があったのかわからないんですが、このタイミングですね。今この時期なのは、もうちょっと早く報告できなかったのか、無理だったのか、その辺だけ教えてください。","respondent":"稲田道路公園課長","answer":"示談成立後、私どもの事務処理の都合上この時期になりました。予定が少し合わなかったということで。","voiceIndex":69,"id":"exchange-018"},{"speaker":"武内委員","kind":"質問・要望","question":"今の感じだと、急げばできるときもあるということですよね、状況によって。ただ要望で、やはりできるだけ早く、そういう機会があるなら、これは２月ですから、もうちょっと早くできないのかなと疑問に思ったので、もっと早くできるならそうしていただいて、なるべく早くやっていただけると助かると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-019"},{"speaker":"井上委員","kind":"提案","question":"ただのクレームではなく、事故があって初めて「やっぱりね」ということではなくて、どういう基準をつくって改修をするのかという、これからもそういう視点が必要かと思うんですが、どういう声に対して対策をとっているのか、またそれを強化していく必要があるのか、どういったふうに考えているのかちょっと疑問なんですけれど、いかがでしょうか。","respondent":"稲田道路公園課長","answer":"そういう情報に対しましてはまず現場を見て、それが早急に対応しなければいけないものか、区民に危険を及ぼすものなのかという判断をしまして、対応していっております。そういうところで、区民の皆様方の通報におきましても対応しております。","voiceIndex":72,"id":"exchange-020"},{"speaker":"井上委員","kind":"確認","question":"ここはずっと長らくこういう状況だったということですが、ここについては声があったのか、なかったのかを確認したいと思います。","respondent":"稲田道路公園課長","answer":"ここにつきましては、区民からの通報等はございませんでした。","voiceIndex":74,"id":"exchange-021"},{"speaker":"井上委員","kind":"質問","question":"どういうところに危険があってどうなのかという、多分庁内での基準があると思うんですけれど、そういうものをちゃんとマニュアル化してつくってあるのかどうなのか、一つだけ伺います。","respondent":"稲田道路公園課長","answer":"内容につきましては、これは現場を見て調査をするんですね。この穴ぼこがへこんでいる状況でしたら、下水管をのぞいたり調査をしまして、現場の状況によって対応していっているという状況です。","voiceIndex":76,"id":"exchange-022"}]},{"id":"topic-04","title":"専決処分の報告について（報告第１６号） 次に、(3)専決処分の報告について（報告第１６号）","agenda":"専決処分の報告について（報告第１６号） 次に、(3)専決処分の報告について（報告第１６号）","exchanges":[{"speaker":"井上委員","kind":"質問","question":"そのときに区の職員の方なのか、借り上げ車というか車と運転手すべて委託の方なのかで傾向があるのか、指導、教育の部分でそれが重要になってくると思うんですけれど、そういったところに何か傾向があるのかどうかということと、またあそこの北品川のところから出てくる車は、子どもたちも歩道橋を渡るようにはなっているんですけれども、結構スピードを上げてくる。","respondent":"太田品川区清掃事務所長","answer":"大変こういう言い方は恐縮ですが、率でいくと０.１％の事故発生率という形になっているところです。それから雇上については委託契約ということでやってありますので、基本的に事故が起きた場合には委託会社が責任を持って対応するということになってあります。","voiceIndex":83,"id":"exchange-023"},{"speaker":"井上委員","kind":"意見","question":"私は、報告が雇上の部分ではないというのを今日初めて知ったんですけれども、区民としては清掃車がどちらかというのは関係ないということで、こちらのほうの事故件数も把握は当然必要だと思うんです。そういう意味で今おっしゃったような１３台、３１０日で０.１％というような、同じことで報告をお願いしたいんですが、わかりますか。","respondent":"太田品川区清掃事務所長","answer":"ただ雇上会社についての台数全体でいえば、申しわけありません、今すぐ出ないんですが、５０台程度の雇上会社が品川区だけで走ってありますので、それの３１０日を掛ければ１万５,０００分の５ということで、さらに率は低くなってくると、そういう状況になっているかと思います。","voiceIndex":85,"id":"exchange-024"}]},{"id":"topic-05","title":"しながわ節電コンテスト","agenda":"しながわ節電コンテスト","exchanges":[{"speaker":"武内委員","kind":"質問","question":"例えば７月で削減できましたと応募をして、上位２０名に入っているかもしれないですけれど、そうするとその方は８月、９月もダブって応募できるのかどうかということと、この目的をもう１回教えてください。","respondent":"野呂瀬環境課長","answer":"何も節電コンテストで商品をもらうためのものでは、それはそれでありますけれども、一つのきっかけづくり、これをきっかけにしていただいて、今後節電に取り組んでいただくためのアクションを起こしていただけたらという形で考えてあります。","voiceIndex":96,"id":"exchange-025"},{"speaker":"武内委員","kind":"確認","question":"最近テレビですごくやっていますよね。本当かどうか確認はとれていませんけれど、テレビでやるぐらいだからある程度確認はとっているのでしょうが。これはコンテストなのでしようがないんですけれど。もうやらない」なんていうふうにならないように、ぜひ何か「こうやってやるとこうなりますよ」的なものは少し工夫して、やっていただいたほうがいいんじゃないかと思うんですけれど、どうですか。","respondent":"野呂瀬環境課長","answer":"節電コンテストはこのチラシなんですけれど、そのほかに今までも６月１日号、２１日号の広報しながわ等々で節電をお願いしますという呼びかけはしています。","voiceIndex":98,"id":"exchange-026"},{"speaker":"中塚副委員長","kind":"意見","question":"２０％以上の節電ということで、僕の家にも先日来まして、去年とどうだったのかなというふうに見ていたんですけれど、案外減っていないんですよね。これは削減割合の上位２０位ですよね、要するにこういう工夫をしたとか、こういう家族で取り組んだとか、子どもたちとどういう話し合いをしたとかではなく、単純に率だけで上位２０位ですよね。こういうのはどうなのかなというのが率直な疑問なんですよね。","respondent":"野呂瀬環境課長","answer":"それと２０％というのは、国の方針では１５％となっていますけれど、あまりコンテストには特化したくないとは思っていましたけれども、１５％という同じではどうなのかということを考えまして、一応２０％ということで削減率は設定させていただきました。","voiceIndex":100,"id":"exchange-027"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"いろいろな工夫とかそういうものを、うちの家庭ではこうやりましたよと、そういうことも必要なのかなと思いますけれど、上位２０位ですからまさに減らせば減らすほどなんですよね。どういう検討過程で出てきたのかご説明いただきたいのと、これ自身はどこか国や都の補助事業になっているのか、それとも単独なんですか。","respondent":"野呂瀬環境課長","answer":"もう１点、いろいろお考えはあると思いますけれど、例えば荒川区も同じようなことをやっていますけれど、荒川区は通算での削減率というのはないというふうに聞いていますけれども、通算でやっていただいた方に賞をあげるというのが第一義的な目的ではなくて。","voiceIndex":102,"id":"exchange-028"},{"speaker":"井上委員","kind":"質問","question":"関連なんですけれども、今年新規でエコワットを貸し出すという事業があります。それが今どういう状況なのか、開始がいつなのか、全然情報がないので、それについてちょっと説明をお願いします。","respondent":"野呂瀬環境課長","answer":"貸し出しではなくて、やっていただいた方については今後のこともあるので、この電力簡易測定器というものを差し上げるというふうに考えております。","voiceIndex":105,"id":"exchange-029"},{"speaker":"大西委員","kind":"意見","question":"ちょっと皆さんのお話と一緒なんですけれど、体調を崩すと節電しても意味をなさないということがあろうかと思うんですけれど、私たちの常識からすると、エアコンを使うのをやめると随分節電効果になるんじゃないかというのが普通に考えるところだけど、現実的にはエアコンの温度を２度下げても１.２％しか節電にならないということがあった場合、ご案内のとおり熱中症になるのは６０代以上がほとんど７０％。","respondent":"野呂瀬環境課長","answer":"今、委員がご指摘のとおり、それは私どもでも一番気がかりというか、これからＰＲする中でも健康を害されて、本当に我慢大会みたいな形になっていったら私どもも困りますので、節電の意味と無理のない範囲でやっていただくというＰＲは。","voiceIndex":109,"id":"exchange-030"},{"speaker":"大西委員","kind":"確認","question":"それと私が言っているのは、確認したいのは、２度ぐらい下げても、要するに２６度と２８度ということはありますが、設定温度を下げてもそんなに効果はないんですよということをアピールしておかないと、東電なり何なりに確認して、そういうことよりもこういう点に重点を置いて節電していったほうが削減にはなりやすいし。","respondent":"野呂瀬環境課長","answer":"おっしゃる点を含めて、発信していきたいと考えております。","voiceIndex":111,"id":"exchange-031"}]},{"id":"topic-06","title":"区内の放射線量等の測定結果","agenda":"区内の放射線量等の測定結果","exchanges":[{"speaker":"井上委員","kind":"確認","question":"保健センターのどういったところに測定器を置いているのかということの確認と、ホームページで、今ちょっとわからないんですけれど、前にリンクが、台東区と港区だったかと思うんですが、増えているのかわからないんですけれど、根拠は何なんだろうという、２３区中２つの区へのリンクが張ってあって、そこの測定を出していたんですけれど、何でそこなのかなというのがちょっとわからなかったんですけれど。","respondent":"野呂瀬環境課長","answer":"荏原保健センターにつきましては、玄関脇の中庭というんですか、エントランスのところで測定しております。それとリンクを張った理由ですけれども、この測定結果に対する説明文をやはり港区と台東区が載せておりまして、わかりやすいということもありましたので、載せてあります。","voiceIndex":118,"id":"exchange-032"},{"speaker":"井上委員","kind":"質問","question":"品川保健センターのほうの目黒川は、地上何ｍではかっているのかということだけ教えてください。","respondent":"野呂瀬環境課長","answer":"１ｍです。","voiceIndex":120,"id":"exchange-033"},{"speaker":"大沢委員","kind":"質問","question":"最初の資料の記述の中で、「ただちに健康に影響をあたえるものではない」というこの部分で、今後の放射線対策に対して区はどのような考えを持ちながらこの事業を今後進めていかれるのか、ちょっと教えてください。","respondent":"岩田都市環境事業部長","answer":"ホームページにアップするとき、この単位をどういう形で説明するかというのは、実は非常に悩みました。非常に難しいんですね。そもそも今回も、空中の放射線量はシーベルトという単位で測定をしております。砂とか水はベクレルという単位で公表しております。","voiceIndex":122,"id":"exchange-034"},{"speaker":"大沢委員","kind":"質問・要望","question":"ベクレルとシーベルトというのはわかったので、最後にちょっとお願いですが、ただちに健康に影響云々ということですので、ある程度１年先になるか、何十年先になるかということはもう目に見えてわかっているわけですし、そこのところの危機管理の対策というのは所管が違うかと思うんですけれど、それを含みおきしながら、この「ただちに健康に影響をあたえるものではない」という。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-035"},{"speaker":"武内委員","kind":"確認","question":"というのは、すごく今、テレビとかいろいろなところで専門的なものがちらほらちらほら、情報だけが出てきている中で、我々もいろいろなものを読んだりしても、両方の意見があったりするもんですから、結局どういうふうにお伝えしていいのかなと、あまり変なことを軽々しくお伝えしてもいけないし、かといってあんまり不安をあおるような伝え方をしてもいけないということで。","respondent":"岩田都市環境事業部長、野呂瀬環境課長","answer":"この表現を聞きますと、今はないけど将来あるかもしれないと、逆に悪いほうへ悪いほうへ国民はとってしまうので、やはり我々も言葉は慎重に、かつ安心していただけるような数値も考えながら表現方法を今考えている状況で。ですから今後プールについては、今のところですけれども測定する予定はございません。","voiceIndex":125,"id":"exchange-036"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"補正のところでもちょっと触れられていたかもしれないんですけれど、測定器購入が２台ですよね。区民からの要望についての対応に関して確認したいと思いまして、ちょっと納期が１２月２７日と先ではありますけれど、そこをやってほしい、あそこをやってほしいという区民要望についてはどういう対応を考えていらっしゃるのか、ご説明いただきたいのが１つ。","respondent":"野呂瀬環境課長","answer":"それに対しての貸し出しにつきましては、基本的には東京都のほうから品川区に貸したものであるので、それの又貸しはなかなか難しいような状況で聞いております。","voiceIndex":130,"id":"exchange-037"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"区民の要望について、貸し出しではなくて、要するに区か業者かわからないけれども、ここをはかってほしいといったとき、そういう区民要望についての対応はどう考えていらっしゃるのか。東京都から配られたものを、区民に貸すのではなく区がはかりに行くとか、そういう要望との関係での対応をご説明いただきたいんですが、いかがでしょうか。","respondent":"野呂瀬環境課長、岩田都市環境事業部長","answer":"品川区内は２２km四方ぐらいのエリアですので、例えば隣から数百ｍ離れたとしても基本的には心配ないということでご理解いただいて、やはり個人のここについてはかってくれというご要望については。ただ、学校がそれをやるか、保育園がやるかはちょっと、今私はお答えできませんけれども、不安を払拭するためであれば、最初の一、二カ月、我々が自転車で走り回ってやるのは、当然自治体の職員の責務だと考えています。","voiceIndex":132,"id":"exchange-038"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"ちょうど総会の時期だけに、区民の関心が高い事項だけに備えたいんですけれど、質問は、今の時点で課題や問題意識というのをどんなふうに考えていらっしゃるのか、区の問題意識や課題の整理についてのご説明をいただきたいということです。要するに高層住宅で区が考えている課題や問題意識について、ご説明いただきたいということです。","respondent":"片田防災まちづくり事業部長","answer":"今、お話しいただきましたけれども、ちょっと確認なんですけれども、構造的な問題以外のソフト的なお話で、私どもが考えている課題ということでよろしいでしょうか。","voiceIndex":138,"id":"exchange-039"},{"speaker":"中塚副委員長","kind":"質問","question":"構造的な問題は大分この間議論されてきたので、住民の不安はむしろソフト的なところだと思うので、ソフト的なところについてです。要するにライフラインが切れたらどうしようとか、戸建て住宅でなくて集合住宅ですから、なかなかいろいろご意見があって、今時点での区のお考えを。","respondent":"片田防災まちづくり事業部長","answer":"わかりました。","voiceIndex":140,"id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4008#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":38049,"voices":144}},{"id":"h23-20110627-9","meetingId":"h23-cm06","date":"2011年6月27日","dateIso":"2011-06-27","committee":"文教委員会","time":"午前１０時００分～午後０時１７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を47件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第３６号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"第３６号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"条例変更なので、東京都に準じてきているというお話なんだけれども、ここで例示したのは補償額が上がっている数字があるんだけれども、内容的に下がっているものも随分あるわけで、その辺は、給料とかそういうものとの関連でこういうふうなものが出てきてしまうのか教えてください。","respondent":"和氣学務課長","answer":"今回は、そういう意味では上がっているものが多いのですけれども、全体の給与の動向といいますか、賃金推移の動向で変わっていくものです。今回については上がっているのが全体の傾向です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"毎年改定をされているということなんですけれども、去年と今年と特に内容的に変わっているところがあるのかどうかと、あと、昨年のときは実際にこの条例にかかわる公務災害に当たられた方が今までいらっしゃらなかったというようなことを記憶しているんですが、その後の部分でどうなったのかを教えていただきたいと思います。","respondent":"和氣学務課長","answer":"全体の状況を見て、実際に薬剤師とか、歯科医とか、医師の全体の所得水準とか、そういうものを勘案して出ています。先ほど、全体は上がっている傾向にあると言いましたが、薬剤師で下がっているというところです。","voiceIndex":7,"id":"exchange-002"}]},{"id":"topic-02","title":"の第３２号議案、平成２３年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"の第３２号議案、平成２３年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"渡部委員","kind":"確認","question":"幾つか伺います。防災資機材について、幾つか分かれて説明がありましたけれども、これは一番最初にご説明いただいた発災時に園児が２日、これはすべてにおいてその基準ということでよろしいでしょうかという確認です。これはもう補正されていたんですか。ということは、丸腰だった状態でこのヘルメットということでよろしいんでしょうか。","respondent":"吉岡保育課長、和氣学務課長","answer":"今ご説明いたしました内容は、保育園、幼稚園、幼保一体施設、それからオアシスルームでございまして、それぞれ従来の施設とも２日間の想定です。できたら７月中にはみんな決めたいとことですが、なかなかいろいろ条件が折り合いがつかなくて、富岡町の町長も８月３１日と認識していますので、３１日というのは帰ってくると思います。","voiceIndex":23,"id":"exchange-003"},{"speaker":"渡部委員","kind":"質問・要望","question":"ヘルメットを先に。ヘルメットはすごくいいことだと思います。今、真っ白のものを見せていただいて、印刷とかはしないんですか。学校名とか。要望しておきます。箱根の問題なんですけれども、私費会計でということで、負担感、今回、５年生は１泊で行くと思うんですけれども、本来、日光でやるときと、箱根に変わったことによる負担増というのは生じていないんですか。お願いします。","respondent":"和氣学務課長","answer":"ヘルメットの件ですが、まず学校名は入ります。それから、個人持ちになりますので、個人名も書いてもらうことを考えております。それから、箱根のほうですが、光林荘だと２泊なんですけれども、今回、１泊ということになっていますので、保護者の方の払う金額は変わりません。","voiceIndex":26,"id":"exchange-004"},{"speaker":"阿久津委員","kind":"質問・要望","question":"それに加えて、防災ヘルメット、先ほどご説明がありましたけれども、考え方として、まず第一に身を守るということと、第二に、今の中学生は体が大きいですから、大人のかわりとして防災の手助けをするという観点がございましたけれども、今回このヘルメットを配ることによって、ちょっとうがち過ぎかもしれませんが、いざというときに行き過ぎた犠牲精神みたいなものが出て、自分の命を捨ててまで。","respondent":"吉岡保育課長、齋藤庶務課長","answer":"オアシスルームについては、園庭という考え方はございませんので、収納ボックス、室内に置くような収納ボックスで検討しています。もう１回確認しておりますので、今いろいろチェックリストを挙げておりまして、専門業者にお願いしなければいけない点については、また専門業者にお願いする予定で、今、点検、確認しています。","voiceIndex":29,"id":"exchange-005"},{"speaker":"阿久津委員","kind":"質問","question":"一般のフェンス等については、これは調査点検というのは、震災後に一斉に行っていらっしゃるんでしょうか。","respondent":"齋藤庶務課長、和氣学務課長","answer":"塀、擁壁、玄関、昇降口、出入り口、ひさしなど、外壁も含めてすべて点検をしています。それも子ども用ではないので、どうしても子ども用といいますと、自転車に乗っているああいうヘルメットとか、幼児用のものはありますけれども、そういうこともありまして、検討はいたしますけれども。","voiceIndex":32,"id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"第一に、ベビーフードを２日間程度というお話だったんですが、ベビーフードというと、どっちかというと、赤ちゃんの小さい子のイメージが強いんですが、普通に食べられるお子さんの食事の備蓄をどうするのかなというのをあわせてお伺いしたいのと、２日程度でいいのかどうか。何かもうちょっと必要ではないかと思うんですが、その辺の２日の目安をなぜ立てられたのかというのを１つお伺いしたいのが１つです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問","question":"運営の維持管理とか、そういった面でお伺いします。いですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-008"},{"speaker":"飯沼委員","kind":"意見","question":"なので、入っていないので入れてほしいなという立場での発言なんですけれども、いけませんか。その辺、どう考えていらっしゃるのかという。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そうですね。認可の公立のところは交代ではかるようになっていますけれども、私立のほうはどうなっているのかなと思うのと、ぜひ入れていただきたいという声が上がっているので、その辺、お考えを聞かせていただきたいと思います。","respondent":"浅野委員長、吉岡保育課長","answer":"この放射能測定の件については、答えられる範囲で、もし答えられるようでしたらお願いします。私立の保育園の園長ともこの間会合でお話しする機会がございまして、そういうご希望もあるやに聞いておりますので、今後検討していきたいというふうには考えてありますが、今現在のところ。","voiceIndex":40,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もう１つは、ヘルメットのところなんですが、先ほどのご答弁をいただいてかなりわかったんですけれども、小学校と中学校のところの教員とか職員の方は、もう既にヘルメットというのは１つずつ確保されているのか、その辺と、あと、擁壁のところは、基本的には地震の後の目視でその後の５カ所の点検になっているのかちょっとお伺いしたい、お願いします。","respondent":"吉岡保育課長、和氣学務課長、齋藤庶務課長","answer":"それからあと、地デジの対応ですけれども、こちらもあと１カ月ぐらいでもう地上波が終わってしまうということなので。教員のヘルメットですが、３月中に全部配備が終わっております。擁壁のコンクリートのサンプリングをして、酸化度ですとか、強度ですとかを物理的に確認している、こういう調査です。","voiceIndex":43,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"意見","question":"今の擁壁のところなんですが、私も何カ所か見たんですが、この間たまたま伊藤小学校の横を通ったら、子どもたちの絵が、もしも落ちると危ないということで削りとられていたんですが、見えているところを見ると、かなり本当にひびが入っていて傾いているんじゃないかなと心配なところとか、あと、中の本当に砂利の混ざっているのが、何かコンクリートと混ざり具合がこれでいいのかななんて。","respondent":"齋藤庶務課長","answer":"伊藤小学校の件につきましても、専門家が確認しておりまして、直ちにということではございません。調査をして危険であれば、来年度中には必ず対応するです。","voiceIndex":47,"id":"exchange-012"},{"speaker":"須藤委員","kind":"質問","question":"何点かお願いします。日光ですけれども、８月中にそこの使用を整理してもらって、９月からお子さんたちにというお話なんですけれども、どうしても再避難する場所が見つからないということは想定をしていないですか。そういった場合にも、品川区のお子さんたちの事業に差しさわりない状況とかというのを考えておかなければいけないのではないかなと思うんですが、そのあたりはいかがでしょうか。","respondent":"和氣学務課長","answer":"基本的には、富岡町のほうもいよいよ職員を派遣して聞き取り調査をやって、最終的には対応すると言っておりますが、万が一ということで考えて、今、危機管理室のほうと協議をしていて、最終的にはどこかで受け入れることを考えようというふうに検討しているところです。","voiceIndex":52,"id":"exchange-013"},{"speaker":"須藤委員","kind":"質問・要望","question":"やはり大変な状況なので、あんまりきちっきちっという、約束したからこうだよという形にならんと思うので、そのあたりは気配りというものをとっていただきたいと思います。それから、保育園で二、三日お預かりするというようなお話もちょっと出ていたんですけれども、そのあたりは、現実的には今どういう状況、もう避難のところからお預かりするという意味なのかどうなのか、その辺を教えてもらいたい。","respondent":"吉岡保育課長","answer":"保育園、幼稚園のお預かりですけれども、基本的に登園時間を過ぎて園児が園にいるときに発災したという想定ですけれども、その中では、通常ですと夕方あるいは夜の早い時間にはお迎えに見えるわけですけれども、それが先般の３月１１日の大震災でもそうでしたけれども。","voiceIndex":54,"id":"exchange-014"},{"speaker":"須藤委員","kind":"質問","question":"そこへみんなの区民の協賛者みたいな人も名前、いわゆる広告ですよね、そういう形をとったりなんかして、品川区全体で防災意識を高めていくという１つの糧になってくれるといいなと思うんだけれども、そういった考え方はいかがでしょうか。","respondent":"和氣学務課長","answer":"来年度からも、まだ来年度予算のところですが、新７年生にヘルメットをお配りしていくですが、今ご指摘の点についても大変重要な話だと思いますので、検討させていただきたいと思います。","voiceIndex":56,"id":"exchange-015"},{"speaker":"須藤委員","kind":"質問・要望","question":"今度の補正で、今回の東日本大震災に対応してこういう予算が組まれてきているんですけれども、我々議会としても、学校というのは今一番避難所としては耐震をしていますよというので安全で、むしろ学校の中で生活したほうが危険が少ないと、表へ飛び出して、表へ整列させたりということではなくて、ある程度落ち着くまでは学校にいたほうがいいよというので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-016"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういう意味では、やはり身を守るということで、子どもたちの近くに置いているということを、要望なんですけれども、指導していただけるようなお願いをしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"防災資材の面が充実と、あと、放射線量の先ほどの測定のところもぜひ私立などの要求も実現させていただきたいと、充実をお願いいたしまして賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-018"}]},{"id":"topic-03","title":"平成２３年請願第１３号、子ども達の教育環境・地域の避難所としての施設改善を求める豊葉の杜学園について設計変更に関する請願","agenda":"平成２３年請願第１３号、子ども達の教育環境・地域の避難所としての施設改善を求める豊葉の杜学園について設計変更に関する請願","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"１つには、ここには１３町目、「今年６月現在約３万人が住んでいます」と。先ほど、３,０００枚ですか、地域に配られているというあたりでは、情報がきちんと伝わっていないのではないかなと思うのと、インターネットで見ましたら、最終的な設計ができ上がった段階のインターネットが載っていましたよね。","respondent":"齋藤庶務課長","answer":"どのような施設を建設するかは、区長が決めて、紛争予防条例に基づいてご説明。そして、ご意見を反映させていただいた結果、施設の位置、耐震、日照に関するもの、こういった議員の皆さんのご意見をちょうだいした計画となっております。","voiceIndex":74,"id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問","question":"私は学校というのは本当にシンプルでわかりやすい、小学校１年生、６歳、７歳からの子どもたちが、生活をし、学びをするという意味では、こんなにも複雑な形状をしている小学校、中学校がほかにあるのかどうか、その点をお伺いしたいのと、この設計の責任というのはだれが負っているのか、区教委として、どのように設計が行われるまでチェックをされたのか、なぜこのような計画でよしとしたのか。","respondent":"齋藤庶務課長","answer":"何か誤解というか、あると思うので、１個１個ご説明申し上げます。小中一貫校は大規模校です。","voiceIndex":76,"id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特に低学年の１年、２年、３年、４年は南棟に普通教室はありますけれども、北棟のアリーナとか、図書館とか、特別教室などに行ったときに、実際に災害があったときに、だれがどう避難誘導をして校庭まで避難をするのかというのがとても心配だと言われているんですが、まずこの点を１つお伺いしたいのと、消防庁のチェックで問題がないというご答弁だったんですけれども。","respondent":"冠木指導課長、齋藤庶務課長、田村教育次長","answer":"ですので、今回、委員のお話の調理室等々で火が出たという場合には、当然これ、防火管理区域なりになっていますから、防火扉であるとか。給食室で火事が起きた場合も、基本は延焼しないで給食室の中だけが燃えるという、こういう構造になっております。私が庶務課長で５年前からスタートでかかわっていたので、やりとりして、なかなかご理解いただけないようなので、１枚目の資料を、先ほど。","voiceIndex":78,"id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"できないんですよね。この間、私も予算のときに伺ったら、５カ所避難場所がありますとおっしゃったんですよね。とっても小さくて拡大しないと見えないような小さい図面１枚きりで、とてもわかりにくいのもあったんですけれども、私はまずわかりやすい図面を出してほしいなと思うんですが、今日いただいた図面で、私が先ほど質問をした８年生、９年生がどう校庭に避難をするのか、全く答えていないですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"とても大事な、私はここの書いていらっしゃる皆さんも同じ心配を持っています。質問します。なので、一番肝心なところを答えていただいていないんです。火災が起きたときにどう避難をするのか、あと、複雑な形状の中で子どもたちがあちこちで遊び、学んでいるときに、どう教職員がその子どもたちを把握して安全に校庭に避難をすることができるのか、まずその点をもう１回答えていただきたいと思います。","respondent":"冠木指導課長","answer":"しかしながら、この施設については、万全な体制で設計をした防火上何の問題もない施設ですので、それをまずご理解いただきたい。","voiceIndex":84,"id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"中学生と大分体格が違う小学生の休み時間に、中学生が校庭を使用することができるのかという、また、１・２年生は東側の遊具のあるところで遊べるそうですが、３年生以上は広いスペースが必要だと考えますがどうなんでしょうかと。すまいるスクール横の玄関に十分な広さをとり、場合によっては北棟使用学年の昇降口として常時使えるようにしてはどうでしょうか。もう１回お伺いいたします。","respondent":"齋藤庶務課長","answer":"先ほどから、この資料の２番目でご説明しておりますので、繰り返しはしませんが、避難路は、消防法で求められたものプラスありまして、全部で３１カ所、避難階から出られる。","voiceIndex":87,"id":"exchange-024"},{"speaker":"飯沼委員","kind":"意見","question":"先ほどのご答弁で答えていただいていません。教育の現場、今の教職員の方もそうなんですが、教育の現場、あとＰＴＡ保護者の皆さん、地域の方々からの心配の声、たくさん出されていると思うんですけれども、それをどう受けとめて意見に反映をされたのか、反映されていないものが大変多いんですけれども、その辺の理由はなぜなのか答えてください。","respondent":"田村教育次長","answer":"それで、ＰＴＡのほうも、今までやったことないんですが、夜、先ほど言った母体校のＰＴＡの役員、時間制限なしで実際に不安だと思うような内容は言ってくれと、もちろん法律的にできる、できないの話があるがということで、先ほど冒頭お話しした温水プールだとか、光庭の話。","voiceIndex":90,"id":"exchange-025"},{"speaker":"須藤委員","kind":"質問","question":"今の委員の発言は、小中一貫校、もともと反対だから、いろいろな場面でいろいろ話をお聞かせしてもらったんだけれども、私ども、この問題、先ほど説明いただくと、５年前から、平成１７年からスタートしましたというので、会派の中で文教委員会の報告をいただいたときに、そのときに委員の仲間からは、地元もみんな賛成して、いい形で進んでくると。","respondent":"田村教育次長","answer":"ＰＴＡの役員も３０人以上来ていたので、各学校、ＰＴＡの役員を通じて、うちのほうで資料を全部準備して、先ほど言った３,０００部というのが、学校長を通じて、保護者だとか、役員以外の部分についても、町会関係も含めて３,０００部、６号までお知らせして、質問については。","voiceIndex":92,"id":"exchange-026"},{"speaker":"須藤委員","kind":"提案","question":"そのとき我々会派の中でいろいろ地元でこういう問題が起こっていますよというようなお話があれば、またそれに対してというような動きがあったんだろうと思うんだけれども、非常にスムーズに話が進んでいますというのは、文教委員会のメンバーから報告いただいてきているので、ここへ来てこういう話になってくると、今、最初に担当課長が説明したように、４つの議案が今議会で提案されてきているので。","respondent":"田村教育次長","answer":"委員ご指摘のとおりです。これで契約関係が反故になりますと、違約金が発生します。","voiceIndex":94,"id":"exchange-027"},{"speaker":"須藤委員","kind":"意見","question":"いろいろなものを区の施設をつくるというときにいろいろな声があって、まずはしっかり地域の方々の声を聞いてくださいというのを議会から、区民の話でなくても、そういう形でお願いしてきたところなので、なおさらこの荏原東については、早い時期から課題になっていて、文教委員会にも報告をしっかりいただいて、我々も議会の中でそういう準備が進んできているので、今日ここに出されてきたのは。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":96,"id":"exchange-028"},{"speaker":"渡部委員","kind":"質問・要望","question":"やはり私どもの少年野球チームは地域に住んでいないけれども、そこを活動拠点としてお借りしている団体としてもいろいろなお話をさせていただいて、ある意味、要望も連絡会、ここの準備をされている方に対して要望してというような形でお話を何度か、例えば今のこの工事が始まる段階、保育園をどうするとかというところからも伺っていたので、意外な気持ちがまずしています。","respondent":"齋藤庶務課長","answer":"この跡地は高齢者施設を予定しておりまして、その関係で収容人員が５００人、ですから２３０人ほど減ってしまいますが、ここの代替につきましては、今後、補完する施設を検討するということで、全体で見ますと。","voiceIndex":97,"id":"exchange-029"},{"speaker":"阿久津委員","kind":"意見","question":"先ほど来、何度もご説明いただいていますとおりでございまして、結論を出すべきだと考えています。内容につきましては、今回は不採択と考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":110,"id":"exchange-030"},{"speaker":"飯沼委員","kind":"意見","question":"子どもたちの安全安心の生活、学びの場を最優先にすべきでありますし、先ほど時間がなくて申し述べられなかった校庭の問題を１つの校庭で１年生から９年生が工夫をするといった言葉で本当に我慢を強いる使い方になってしまうと思いますので、ぜひここに掲げてあるように、子どもたちのことを最優先の環境につくり直す、今からでも遅くないので、禍根を残さないためにも。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":112,"id":"exchange-031"},{"speaker":"渡部委員","kind":"意見","question":"結論を出します。不採択なんですけれども、ただ、安全の問題、訓練は本当に必要だと思います。各学校で、相当今、品川区は一生懸命やっていますので、それはしっかりとやってください。結論を出して不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":113,"id":"exchange-032"},{"speaker":"吉田委員","kind":"意見","question":"やはり結論を出して不採択なんですが、私は自分も豊葉の杜の一保護者として、また、元教員としましても、これも本当にいろいろな誤解もあると思うんですけれど、新しい学校として、希望と光の注ぐ建物ということを思い、先ほどの訓練だけはしっかりしていただくということで、不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":114,"id":"exchange-033"}]},{"id":"topic-04","title":"平成２３年請願第１５号、区立小中学校の給食直営校の存続を求める請願","agenda":"平成２３年請願第１５号、区立小中学校の給食直営校の存続を求める請願","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"久しぶりの学校の給食の請願なんですけれども、改めてやはり委託の問題を考えていかなければいけないなと思っているのと、２点目の避難所の給食の提供のところは、この間、震災が起こった後に公共の施設がしっかりとした耐震の建物でしっかりとその地域にあることと、自治体の職員がしっかりと確保されていることで地域の子どもたちや障害者や高齢者の皆さんの安心を確保できるということで。","respondent":"和氣学務課長","answer":"そこら辺はぜひご理解をいただきたいというふうに思います。委託業者イコール悪という考え方はぜひお捨ていただきたいというふうに思ってあります。","voiceIndex":123,"id":"exchange-034"},{"speaker":"飯沼委員","kind":"質問","question":"委託イコール悪なんてだれが言っているんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問・要望","question":"委託の皆さんは、本当に一生懸命やっていらっしゃるし、現場にいらっしゃる職員の方は、委託のまんまじゃなくて、本当に正規で採用して、正規の職員として働いていただきたい人がいっぱいいらっしゃると。私は、この働いている方も一生懸命ですけれども、委託契約という仕組みに問題点を言っているんです。委託の問題点。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問","question":"この請願は、基準となる直営校を残してほしい。基準となる直営校というのは、直営の職員を残してほしいということですから、やっぱりここですよね。なぜこの直営校を残してほしいかというのは、品川の、ここにも書いてあります優れた給食を残してほしい、継続してほしい、なくさないでほしい、この思いがあるからこそ、この直営校、基準となる直営校を残してほしい。","respondent":"和氣学務課長","answer":"ここで水準を維持するために、みんな必死になって、おいしい給食、いろいろな食材をどういうふうに加工するかを含めてやっていることでございまして、私どもは、ほかはどうか知りませんが、品川区の教育委員会はそんなにもろいことは行いませんので。","voiceIndex":127,"id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問","question":"今のところは入っていないとさっきの保育園のところでも、契約の中には入っていないということですけれども、私はどんなときにおいても、やはり身近にいる自治体の職員が力を発揮する、そういった意味では、この災害時、この東京品川でも何が起こるかわからないといったところでは、しっかりとした直営の職員が何人か残っていることによって、いざとなったとき。","respondent":"和氣学務課長","answer":"そういう方も含めて避難してくるわけですから、そういう人的な資源を十分に活用して、調理施設をどうつくるかというのは、そこでしっかり考えていけばいい問題だと考えておりますので、調理師がいないとできないことは全くないと考えています。","voiceIndex":129,"id":"exchange-038"},{"speaker":"飯沼委員","kind":"意見","question":"一部の方からはまずいと聞いたけれども、親からは直接ないと、私、これ、聞く耳がないから聞こえないんだと思っていますよ。子どもたちからも直接声が上がっています。毎日食べる給食です。本当に事故が起こっては困るし、おいしさは微妙ですよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":131,"id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問","question":"委託だったら、まずかったらすぐ注意して直せる、直営だったら直せない、これは区教委の管理能力がないということではないですか。それは大変失礼だし、現場の方にも失礼じゃないですか。委託で直るというのは、それはもしかしたら首をすげかえるということではないですか。育てることではなくて、もうだめなものはどんどん切っていくというやり方で全体的にレベルアップするのでしょうか。","respondent":"和氣学務課長","answer":"それはすぐにわかることであります。先ほど言ったように、あんまり極端に受けとめられたら本当に困るんですけれども、それは素養の問題であるということを言いたかっただけの話でありまして、それは給食がどちらにしても調理師がしっかりとつくっているかどうかの問題です。","voiceIndex":132,"id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問・要望","question":"つくっている者として食材をどういうふうに選んできたのか、どういうふうにつくったのか、どういうふうに食べてほしいのか、このことまでしっかり子どもたちに会えたときに伝えたり、手紙を書いて伝えたり、そういったことで残っている食事、残菜を減らしている、頑張っているんだという声を伺って、私はそのとおりであると思うんです。なので、委託よりもやはり直営のほうが優れています。","respondent":"和氣学務課長、田村教育次長","answer":"実際に安くなります。単純に財政効率から委託にしたわけではございませんので、民間のノウハウを生かすことを考えて委託にしているということでございまして、単なる安上がりのためということではございません。その間、今、飯沼委員のお話だと、ダブっているという形ではなく、給食で直営校を委託、調理代行に出すときに、やはり用務職に転職が１つあったり、特例転職といって、区の私たち事務と同じような形の試験を受けて。","voiceIndex":134,"id":"exchange-041"},{"speaker":"阿久津委員","kind":"意見","question":"結論を出すべきだと思います。先ほどご答弁がありましたけれども、教育委員会が最終的な責任を持つということで、請願は今回は不採択ということでやってください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":139,"id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問・要望","question":"結論を出します。採択していただきたいと思います。水準を守るために直営校は絶対に必要であると思っています。避難所機能も行政の職員で本当にしっかりとやっていただくことが安心につながると思いますので、ぜひ採択をしていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":141,"id":"exchange-043"},{"speaker":"渡部委員","kind":"質問","question":"結論を出します。僕も給食納入業者をやっていたり、食料品の仕事をずっとやっていて学校給食は何度も何度も質問させていただいていたんですが、実はやはり区としてのしっかりした方針というのは大事だと思います。前から何度か質問させていただいた中で、栄養職員の方々がいろいろルートを組んでやっていただけるということだったので、それで基準がしっかり守れると思います。不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":142,"id":"exchange-044"},{"speaker":"吉田委員","kind":"質問・要望","question":"私は、結論を出したほうがいいと思います。それで、ちょっと一言申し上げたいんですけれども、厳しい目で委託業者を見ていただいて、それはもうずっと変わらずに、だれもかれもお母さん方もみんなよくしようと思ってこういう話も来ていると思うんです。そういう中で、危機感を持って一生懸命対応していただきたい。そういうことで、よろしくお願いいたします。不採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-045"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"民主・改革ネットの阿部委員の福祉と子育てのところなんですが、ちょっとメモを置いてきてしまったので、福祉と子育て、両方にかかわって項目があったんですが、中身詳しくなくてはだめでしょうか。ちょっと手元に今ないので。後で出していいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":149,"id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問","question":"ちょっと資料なくてごめんなさい。大ざっぱ過ぎてだめですかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":151,"id":"exchange-047"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4730#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":41440,"voices":160}},{"id":"h23-20110627-5","meetingId":"h23-cm06","date":"2011年6月27日","dateIso":"2011-06-27","committee":"総務委員会","time":"午前９時５８分～午後２時３０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を64件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の第３３号議案、職員の育児休業等に関する条例の一部を改正する条例","agenda":"の第３３号議案、職員の育児休業等に関する条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"この際、これは公務員の関係ですけど、育児休業がとれるようにというのは、公務員に限らず広く民間にもそういう方向で広がっていると思うんですけれども、現実的に品川区内の、こういう制度がどのくらい制度化されているのかと実態がどうなっているのか、もしわかれば教えていただきたいし、ぜひ促進する方向で区としても働きかけが必要なんじゃないかなというふうに思っているんですけど。","respondent":"堀越人事課長","answer":"区の対象職員ですけれども、特に予定があるというわけではございませんが、職員数、再任用短時間勤務職員ですと、平成２３年で２１１名在籍をしています。それから、無給かどうかという部分ですが、給与については支給されません。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"対象になる方が２１１名ということで、これから始まる制度ですから今すぐどうこうというんじゃないと思うんですけど、わかりました。データがないというのは調査していないのかどうか、そこまでわからないんですけど、していないのであれば、やっぱりしていくということで、やるべきではないかなというふうに思っております。これは意見として述べて、以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"},{"speaker":"阿部委員","kind":"質問","question":"制度の整合性という意味で、この仕組みをお願いするんですけれども、ちょっと２点ほどお伺いしておきたいんですが、再任用ということで、この再任用短時間勤務職員、これは年齢は何歳から何歳ということなんでしょうか。改正内容は、対象職員が在職期間１年以上というのは、再任用短時間勤務職員としての在職期間になるのでしょうか。そうすると、この制度の対象期間というのはどうなってくるんでしょうか。","respondent":"堀越人事課長","answer":"細かい、いろいろ請求の手続等はあるんですけども、定年を終えられて再任用１年目で実際に取得という場合も引き続くというような、見なすというような部分がありますので、そのような扱いになっております。","voiceIndex":8,"id":"exchange-003"},{"speaker":"阿部委員","kind":"意見","question":"そうすると、６０歳、再任用になった直後に対象になるということも見なし規定があればあり得ると。ただ、６５歳、まあ、６４歳ぐらいまではこの制度が使えるねということでよろしいんですね。事実上配偶者しかないかな。そんなことを言ってはいけないんでしょうけれども。理解しました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":10,"id":"exchange-004"}]},{"id":"topic-02","title":"第３４号議案、品川区特別区税条例の一部を改正する条例","agenda":"第３４号議案、品川区特別区税条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"大震災で被災された方々への特別措置と、そういう趣旨ということがわかったんですけれども、対象者が品川区内にどれくらいいるかとか、そういう補足をどういうふうにしたらいいのかというのをちょっと教えていただきたいなと思います。","respondent":"高森税務課長","answer":"今対象者がどのぐらいいるのかというご質問をいただきました。具体的には、この雑損控除について、平成２３年１月１日現在、品川区に居住をされていた方で、３月１１日現在被災地で被災された方につきましては、平成２３年度分の住民税について適用になります。","voiceIndex":22,"id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"自分がこういうふうな特例措置があるかどうかも知らない人もいるかもしれないし、そういう方々のないようにフォローしていくということがまず大事だと思うんですけれども、区役所としてこれを適用していただくために、どういうふうな働きかけをこれからしようというふうに考えておられるのか、その辺をひとつ伺いたいと思います。","respondent":"高森税務課長","answer":"住宅ローン控除につきましても、引き続き１回、控除をやっていただければ、それが継続した形で控除が受けられるという形になってありますので、この辺のところは既に３月１５日までに申告をお済みの方であっても、被災をされ、また雑損控除が適用になるということであれば。","voiceIndex":24,"id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"それともう一つ、品川区の条例は第３１４条についてなんですけれども、地方税法第３２３条の減免措置条例という、ここも該当というようにちょっと聞き及んでいるんですけれども、その辺については今回の品川区の条例改正では入っていないというふうに思うんですが、そのあたりのことをどういうふうに考えたらいいのかなと思ったんですけど。","respondent":"高森税務課長","answer":"減免制度というのは、賦課の段階で減免するという、賦課をした、今回の住民税のお話でいけば、６月９日に普通徴収を発送しまして、６月３０日が１期分の納期だったわけです。","voiceIndex":26,"id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"最後に。特別措置法をつくって条例改正する中で、さらに対象者を広げるとか、範囲を広げて権利的にはしっかりと守っていくと、そういう意味での法律改正、条例改正がされているんだなと私は思ったんですけども、そこを改正しなくてもできるんじゃないかという意見も一方にある中で、どういうふうにこのところを整理したらいいのかなというのがわからないので教えていただきたい。","respondent":"高森税務課長","answer":"それは実際の実績としてなかなか、例えば漁業をやられている方であれば、何年か収入が本当に低い形で進んでいくんだと思われます。そういうふうなことを見ますと、現実的な対応としては、今回の法律は現実に則した形で即効性があるというふうに理解しております。","voiceIndex":28,"id":"exchange-008"},{"speaker":"阿部委員","kind":"質問","question":"これは手続的には被災証明か何かが必要になってくるということなんでしょうか。現実としての運用について教えてください。それから、これは申請先は税務署になるんでしょうかね。ただ、品川区としても、やはりこの制度に対する広報とかご相談というのは、充実していくべきと思うんですけれども、この体制についてはどのようにお考えになっているんでしょうか。","respondent":"高森税務課長","answer":"東北５県につきましては、市町村のほうと税務署が一体になって申告書等を受け付け、所得税の申告書という意味での申告書については受け付けるというか、今回の実態につきましては、住民の方がまず出向いていただいて、状況を聞きながら大体このぐらい。","voiceIndex":30,"id":"exchange-009"},{"speaker":"阿部委員","kind":"質問・要望","question":"なので、そこはもう少し被災者がある程度把握されている部分はあると思いますので、学校に通われているとか、あそこに住んでいらっしゃるとか、公共の住宅に住んでいらっしゃる方も多いと聞いていますので、漏れのないようにきちんと広報をしていくことはぜひ積極的にやっていただきたいと思うんです。もう一度ご答弁をお願いいたします。","respondent":"高森税務課長、荒井広報広聴課長","answer":"パブリシティにつきましては、ホームページのほうに、実は税務課のいろんなご案内だとか、いろんなものをスタンダードな形での例示をさせていただいていますので、その中でまずは周知をさせていきたい、皆さんにお知らせしていきたい。はその中で周知していきたいと思います。","voiceIndex":34,"id":"exchange-010"},{"speaker":"阿部委員","kind":"質問・要望","question":"皆さんがホームページにアクセスできる状況にあるかどうかというのは、ちょっと私実態を把握していませんが、かなり疑問なところもありますので、もう少しアナログな方法をぜひ強化していただきたいなと思います。区民相談の一部であっても構わないと思いますけれども、どういう相談体制ですか。相談体制はこの件についてはどのようにやっていらっしゃるんでしょうか。","respondent":"日下部企画部長","answer":"ただ、区民相談として対応できる中身というのは、やはり限られておりますので、区民相談から今度はそれぞれの内容についてご紹介をするということで、被災された皆さん方もいろんなやっぱり悩みとか相談をお持ちだと思いますので。","voiceIndex":37,"id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"それはよしとして、今後何かこれが効果があるのかと思ったときに、引き続き継続してローンの控除の特例が受けられるとなったとしても、実際に効果が、被災された方にあるんでしょうか。実際にそんな効果はあるのか。いっときだけのような気がするんですが、ちょっと詳しく、内容がよくわからないので、条例改正ということなので、ちょっと教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"あくまで前倒しで控除が受けられて、継続して受ける、それに尽きるわけですか、それだけで結構ですからお答えください。","respondent":"高森税務課長","answer":"この条例改正につきましては、大きな中の一つの手段ということです。そういうことでご理解いただきたいと思います。","voiceIndex":42,"id":"exchange-013"},{"speaker":"鈴木委員","kind":"質問","question":"雑損控除の関係なんですが、品川に移ってきた方というのは、そんなに数は多くないと思うんですよね、この対象者。メインはそっちだと私は見ていてそう思ったんですが、この親族という範囲をどこまでにするのか、これがよくわからなかったので、そこら辺を教えてください。範囲によっては相当広くなってくると思うんですが、その辺を具体的にお願いします。","respondent":"高森税務課長","answer":"扶養親族という形なんですけども、この方は総所得金額が３８万円以下という形になりますので、給料であれば１００万円以下の収入の方が扶養親族の対象になりますので、申請自体はそれほどなのかなと思います。","voiceIndex":44,"id":"exchange-014"},{"speaker":"鈴木委員","kind":"質問","question":"扶養親族だけ、同居しているということですよね。区内にお住まいの方が親族ということは、今まで住んでいた方に対しては全然対象にならないというふうに判断して、あくまでも品川区に移られた方だけが対象ですよという感じなんですか。","respondent":"高森税務課長","answer":"１月１日現在に被災地におられた方で、それ以降来年の１月１日に生計を一にしている扶養親族という方が対象になるというふうに理解しています。","voiceIndex":46,"id":"exchange-015"}]},{"id":"topic-03","title":"の第３７号議案、土地の取得","agenda":"の第３７号議案、土地の取得","exchanges":[{"speaker":"塚本委員","kind":"意見","question":"大変に大きな金額でありますので、私も区民に聞かれて、いろいろと説明をしなくちゃいけないところもあるかと思います。この土地取得に至る経緯といいますか、そもそもの第一三共株式会社の申し出があったというところなのか、いろんな発端があっての今回の契約だと思うので、あらましで結構ですので、ちょっと経緯をご説明いただけますか。","respondent":"阿部経理課長","answer":"第一三共のほうから、今の社宅用地、２２５の６のほうですけれども、そこも含めて一体としての売買はどうでしょうかという申し入れがあったということを聞いております。そういう申し入れがありましたので、区としても改めてそれを検討いたしまして進めてまいりました。","voiceIndex":59,"id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"区が公有財産審議会で価格、どの程度の価格がいいのかということも議論していただいて、買おうというふうに決定したその過程で、私どもはこの間の第１回定例会、予算特別委員会の中でも主張してきたんですけれども、特別養護老人ホームは３,０００m2ぐらいの土地がないとつくれないということで、目を皿のようにして探していると、そういう区の姿勢がずっとこの間表明されていて。","respondent":"阿部経理課長","answer":"左側の社宅の用地、２２５の６です。これは約３,６００m2という広さです。土地につきましては、特別養護老人ホームという話ですけれども、先ほどから申し上げているように、ここにつきましては、当初から品川学園の校地として取得をするということで検討を進めてまいりました。","voiceIndex":61,"id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"やっぱり区としていろんな土地が出たというときに、区民要望との関係で、いろいろと検討されるというふうに思うんですけれども、区民要望というのをどういうふうに区としてはとらえていらっしゃるのか、ちょっとその辺、一般論というか、一般論と同時に、今回のところは初めから特別養護老人ホームということは検討の素材になっていなくて。","respondent":"日下部企画部長","answer":"先般の本会議でも、これは健康福祉事業部長のほうからもお答え申し上げましたけれども、今後の高齢者の人口の増加等を考えると、やはり今後特別養護老人ホームの増設についてもさらに必要だという認識のもとで用地の確保に向けて。","voiceIndex":63,"id":"exchange-018"},{"speaker":"南委員","kind":"確認","question":"ちょっと一つ先ほどの説明を伺っていて確認したいのは、地域から校庭を広げる努力をしてほしいという声があって、たまたま資材置き場として使っていたところを、そういうふうに買うつもりでいたということですけど、新たに追加する部分については、資材置き場じゃなくて社宅があって、使われていなかった土地であったにしても、新たに追加をして買ってくれというふうになったわけですよね。","respondent":"本間副区長","answer":"そこの跡については、区として今企画部長等々が説明したとおりの地元からの要望等もありますので、是が非でも学校用地として購入したいという強い購入希望を区から相手方に申し入れをして、それで相手側で内部で検討していただいたという経緯です。","voiceIndex":65,"id":"exchange-019"},{"speaker":"南委員","kind":"確認","question":"最後に確認のつもりなんですけど、今の副区長の説明はそれなりにわかったつもりだし、私としてもそんなに認識の違いはないなと、今まで説明を伺っていた点での違いはないなというふうに思っていたんですけども、一つちょっと確認したいのは、当初は資材置き場として借りていたそこのところは、購入させてほしいという地域の要求もあった中で、区としては購入をしたいと決めて申し出をしたと。","respondent":"本間副区長","answer":"一連のこの土地の購入の経過の中では、教育施設を充実するという大前提で会社側と話を進めてきたですので、ひとつご理解をよろしくお願いいたします。","voiceIndex":67,"id":"exchange-020"},{"speaker":"須貝委員","kind":"質問","question":"７,００７m2ということで、５１億円。この坪数、ちょっとすみません、坪数で我々換算するしかないんですが、１坪当たり相当安く売っていただいているのかな。すごく努力されていると思うんですが、坪数に換算すると１坪幾らぐらいですか。","respondent":"冨久増用地担当課長","answer":"価格の水準ですが、基本的にはおおむね近辺における相場とほぼ同等の水準であろうと考えておりまして、特にこの土地をお安く譲っていただいたという事実はございません。","voiceIndex":69,"id":"exchange-021"},{"speaker":"阿部委員","kind":"質問・要望","question":"区の負担が教育施設であれば１割で済むということを考えれば、やはり教育施設という形で取得するというのは、むしろ区としてはそうしなければ背任だろうと思うぐらいのことだと思っているんですけれども、確認しますけれども、今教育施設の目的のしばりというのは、運用ではおおむね２０年ぐらいだったかなと思うんですが、それでよかったでしょうか。","respondent":"本間副区長、榎本企画財政課長","answer":"後段のほうですけれども、先ほど私が公租公課代程度でお借りしたと説明いたしました。それが前提となって、何か今回の価格で特にその分の配慮というものは一切ございません。教育用途の制限の部分の年数ですけれども、今回この起債に当たっては、償還年数２５年ということで考えておりますので、一応２５年までは教育用途で使うということで考えております。","voiceIndex":72,"id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"うちも賛成します。賛成の理由は、先ほど申し上げましたように、本当に悩みました、正直にね。住民要求を教育施設の充実としてとるか、特別養護老人ホームをとるかと、ここのところで非常に悩んだんです。しかし、特別養護老人ホームの充実も、これもしっかり進めていただきたいということもお願いしておきたいと思います。それから、質問をちょっとしなかったんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"態度表明ですから質問はしません。質問はちょっとしなかったんですけれども、この土地を購入することで一貫校、あるいは品川の全小中学校の校庭、施設の充実の点では、かなりいい充実になっているんじゃないかと思うんですけども、ほかの一貫校と比べても断トツですよね。ですから、そういうことについて条件整備をしっかり進めていただきたいと、これも要望としてお願いしておきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-024"}]},{"id":"topic-04","title":"の第３８号議案、国文学研究資料館跡地内建物解体工事請負契約","agenda":"の第３８号議案、国文学研究資料館跡地内建物解体工事請負契約","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"解体の対象から１号書庫だけは残っておりますけれども、たしかこれは何か文化財ではないですけど、意図があって残すはずだったと思うんですけど、ちょっとその辺、教えていただいてよろしいでしょうか。","respondent":"宍戸施設整備課長","answer":"この１号書庫ですが、大正４年に建てられた様式としてもかなり価値があるのではないかということで、文化的な価値を考慮して、この１号書庫については残すというふうに聞いております。","voiceIndex":88,"id":"exchange-025"},{"speaker":"阿部委員","kind":"質問","question":"解体する部分はアスベストとかは使われているものなんですか。当然あれば、その手続にのっとって工事をやると思うんですけど。","respondent":"宍戸施設整備課長","answer":"いわゆる吹きつけアスベストですね、問題になる飛散する可能性が非常に高い吹きつけアスベストについてはございません。ただし、建材については、含有建材はありますので、それにつきましては法律に基づきまして適正に安全に処理をするというふうなことで考えております。","voiceIndex":92,"id":"exchange-026"},{"speaker":"南委員","kind":"質問","question":"解体工事期間というのがどのくらいなのかちょっと伺いたいんですけど。","respondent":"宍戸施設整備課長","answer":"それで、一応工期が３月までですので、実際の解体作業については、２月ごろ終わりまして、３月に検査、手直しというふうなスケジュールにおおむねなるのではないかというふうに考えております。","voiceIndex":94,"id":"exchange-027"},{"speaker":"南委員","kind":"質問","question":"中心的な施設、書庫が２と３とあるんですけれども、そこは建物的にわからないですけど、素人から見てもどういうものなのかなと思うんですけど、いわゆる本館というんですか、そこの５階建てのところはかなり大きな施設だし、こちら側は池もあるし、足場を組むのも、樹木もあるし大変かなというふうに思っているんですけども、全然わからない素人のところで申しわけないんですけど。","respondent":"宍戸施設整備課長","answer":"実質的に６カ月ということで、やや長目にとっております。","voiceIndex":96,"id":"exchange-028"},{"speaker":"鈴木委員","kind":"質問・要望","question":"１点だけ確認です。この池の部分、今開放している部分は、工事期間中、開放は取りやめにするのか。それと、この道はすごく狭いから、工事の車もかなり大型車が入ると思うんですけど、交通の問題も十分注意していただきたいというお願いです。","respondent":"宍戸施設整備課長","answer":"これもいろいろ所管課と話し合いというか、検討はしたんですけれども、安全面を考慮して、一応閉鎖するような方向で今話を進めているところです。","voiceIndex":98,"id":"exchange-029"}]},{"id":"topic-05","title":"の第３９号議案、（仮称）品川地区小中一貫校新築外構その他工事請負契約の変更","agenda":"の第３９号議案、（仮称）品川地区小中一貫校新築外構その他工事請負契約の変更","exchanges":[{"speaker":"阿部委員","kind":"質問・要望","question":"確認させてください。工期が来年の３月９日までなんですけれども、これは一遍にこの時期に使えるようになるんですか。それから、舗装工事とありますけれども、校庭の仕上げというのはどうなるんでしょうか。何か結構学校のほうなどから人工芝とか、いや材質は云々という話、要望も出ていたみたいですけれども、この舗装工事の内容というのは決まっているんですか、まずその２点、お願いします。","respondent":"阿部経理課長、宍戸施設整備課長","answer":"１点目のグラウンドの工期の件です。ちょっと１０ページをお開きいただいて、今申し上げたとおり下の図の右側の第一グラウンド、これにつきましては、先ほど申し上げたように工期の変更はございません。グラウンドの舗装方法ですけれども、一応ダスト舗装というふうなことで考えております。土の舗装ということで考えております。","voiceIndex":111,"id":"exchange-030"},{"speaker":"阿部委員","kind":"質問","question":"この外構工事、今のお話ですと、まず第一グラウンドのほうがこの契約でやると。その場合、連続して植栽なんかも全部土地で区切って、後半にここからまたつなげるという形なのか教えてください。それから、ダスト舗装、これも第一グラウンドについてはダスト舗装で、第二グラウンドについては、まだ舗装の内容はこれから検討するということでよろしいんでしょうか。","respondent":"阿部経理課長、宍戸施設整備課長","answer":"第２グラウンドの契約の件ですけれども、これにつきましては、今回とは別に改めて今の予定では今年度の１１月か１２月を予定していますけれども、そのときに契約案件として出てくる。これは多分議案にはならないだろうと思います。それで、第二グラウンドにつきましても、今回の契約には入ってございませんが、設計は進めておりまして、第一グラウンドと一体的に使用するというのを念頭に、こちらもダスト舗装の予定です。","voiceIndex":114,"id":"exchange-031"},{"speaker":"阿部委員","kind":"質問・要望","question":"学校とか保護者から、またいろいろなダスト舗装でないものについての要望が出ていたと思うんですけれども、その中でダスト舗装を選択された理由を教えてください。","respondent":"宍戸施設整備課長","answer":"少年野球ですとかサッカーですとか、その他、テニス等も含めまして、多用途に対応できるというのが一つと、人工芝というお話がございましたけれども、やはり価格のことなども考慮した上でダスト舗装にしたというものです。","voiceIndex":117,"id":"exchange-032"},{"speaker":"南委員","kind":"質問","question":"第二グラウンドは、今年の１０月ごろ新たに報告になるという話なんですけれども、私は第二グラウンドをプラスして７,０００万円でできるんだなと思って考えていたんですけれども、全然それは別で、第一グラウンドのところだけだということなんですね。第二グラウンドを一緒に整備するというふうにできないのは、時間的な差があるからかなと思ったんですけど、改めてその点を伺いたいと思います。","respondent":"阿部経理課長","answer":"もう一点は、整備の内容がグラウンドといいましても、校庭と内容が若干違ってまいります。それによって別途発注したほうがいいだろうという判断がありますので、主にその２点から今回は第一グラウンドだけの変更です。","voiceIndex":119,"id":"exchange-033"},{"speaker":"南委員","kind":"質問","question":"ですから、整備の内容が違うというのが、第二グラウンドのほうは地域開放、少年少女のスポーツにも、第一グラウンドのほうもできるわけで、ちょっとその辺の違いを設ける理由というのがいま一つわからなかったので教えてください。","respondent":"阿部経理課長","answer":"もう一つは、整備の内容が違えば当然業者が違ってまいりますので２回に分けてやるということと、もう一点は、それに合わせまして、工事としては当然ながら区内発注になりますので、そういう意味では区内の業者の方が受注する機会が増えるということもあります。","voiceIndex":121,"id":"exchange-034"},{"speaker":"阿部委員","kind":"質問・要望","question":"要望の色合いが濃いんですけれども、今ちょっと内容の話が出ましたので教えていただきたいと思います。地域開放、学校で使っていないときには地域開放という話を聞いております。運用については、ここでは詳しく質疑する場所ではないとは思っておりますが、ちょっと使い方のイメージ、もしご答弁いただけるようであれば、ご答弁をいただき、またそうでなければ要望というふうにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":123,"id":"exchange-035"},{"speaker":"南委員","kind":"質問・要望","question":"それで、北棟と南棟でそれぞれ先ほど説明があったんですけれども、改めて北棟は５・６・７・８・９年生で、南棟が幼稚園と保育園の就学前の子どもと１・２・３・４年生ということで、それぞれ何人ぐらいの規模の児童・生徒数になるのかを北棟、南棟、それぞれで確認をしたいと思いますので教えていただきたいと思います。それがまず一つです。とれあえずそういう点で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":138,"id":"exchange-036"},{"speaker":"南委員","kind":"質問・要望","question":"それで、３月の予算特別委員会のときにも、この問題を私どもは指摘をして、安全上、避難路の確保の点では問題があるんじゃないかというふうにたしか質問したんですけども、その際にシミュレーションをしてみるという話だったんですけど、シミュレーションをした結果がどうだったのか、それでなおかつ安全だというふうに確認できたというのが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":141,"id":"exchange-037"},{"speaker":"南委員","kind":"質問","question":"立派な施設ができる、あるいはそういう点では住民の期待もあるかもしれません。それから、４階建てのところに小学校の５年生、６年生が学習する教室が４階のところにつくられるわけですけども、この３階建ての施設のところと、この４階建てに教室を配置せざるを得なくなったという、そこの事情についてはどういうことなのか、ちょっとそれについては先ほど答弁がなかったので再度伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-038"},{"speaker":"伊藤委員長","kind":"質問","question":"今、南委員のご指摘の中で、ほかの委員会の資料を使って質問されているようでありますけれども、総務委員会の資料をもとに今日は審議しておりますので、できましたら質問をやり直してください。やはり委員長としては、ほかの委員会の資料を引用されて質問されますと委員会の運営上、いろんなそごが生じる可能性がありますので、改めて質問してください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":145,"id":"exchange-039"},{"speaker":"南委員","kind":"質問","question":"中身的には同じだというふうに思っています。それで、総務委員会で出された資料の１６ページですね。ですから、この道路との関係で非常に不安があると、こういうふうに指摘をせざるを得ないと思うんです。ですから、この点での子どもの避難というのを、やっぱりもう少し配慮した設計図になっていいんじゃないかなというふうに思っておりますが、その点についていかがかと、そういう質問です。","respondent":"宍戸施設整備課長","answer":"敷地周辺はぐるっと回れるようになっておりまして、南側はもちろん区道がありますけれども、東側もいずれ、かなり広い道路に面するというふうなことで、敷地条件そのものもそう悪い、例えば行きどまりのような敷地ではございませんし。","voiceIndex":146,"id":"exchange-040"},{"speaker":"南委員","kind":"質問・要望","question":"それで、一つその質問についてちょっとお答えいただきたいのと、それから小中一貫校をつくるというコンセプトで設計されたという点で、やっぱり普通の学校よりは大型の、大規模な学校に、施設規模になるわけで、そういう点で非常に普通の学校だったら一面、さっきおっしゃったようなハーモニカ型という言い方がいいのかどうかわからないですけど、そういうすべての太陽の光が当たって風通しがよくなる。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":150,"id":"exchange-041"},{"speaker":"須貝委員","kind":"確認","question":"私ちょっと１点だけ確認でお聞きしたいんですが、北棟と南棟、連絡通路で結ばれているということで、安全は十分確保されていると思うんですが、建物の基礎が違いますよね。ちょっと基礎が違うということでお聞きしたいということです。","respondent":"宍戸施設整備課長","answer":"それで、この庁舎でもそうですけれども、違う棟をつなぐ場合には、エキスパンションジョイントといいまして、揺れの違いを吸収する空間、それとそれをカバーする金物を使って、その辺を吸収するようになっておりまして。","voiceIndex":153,"id":"exchange-042"},{"speaker":"原委員","kind":"質問・要望","question":"パースで見ただけで平面図はあるんですけど、立面図、断面図がないので、そこがわかったら教えていただきたいのと、あとは安全上という意味で聞きますけど、どのぐらいの人数というか生徒数、大きい子から小さい子までいるので重量がわかれば後で教えていただきたい。これが一つ目の質問です。それで、２者が辞退をされている。これの経過を教えてください。","respondent":"阿部経理課長、宍戸施設整備課長","answer":"辞退のほうからお答えします。実は、委員ご指摘のとおり三者申し込みがあったうち、二つの業者が辞退ということですけれども、一つは第１グループの会社が、第二東名の道路工事を受注して工事中でございました。それと重量なんですけれども、大変申しわけありませんが、ちょっとわかりません。","voiceIndex":155,"id":"exchange-043"},{"speaker":"原委員","kind":"質問","question":"一番心配なのは安全上の問題なので、これは判断としては通路だけというふうに解釈していいのか、先ほど東京電力とかいろんな動線の問題ですとか、そうするとこの通路の中にいろいろ入ってくるのかどうなのか、完全にその辺のところ、通路だけなのか、もしくはいろんなケーブル類とかの関係がいろいろかかわってくるものなのか、その辺を総務委員会の範囲で結構なので教えてください。","respondent":"宍戸施設整備課長","answer":"すみません、ちょっとケーブルや何かがどのぐらいというふうなことはあれなんですが、基本的には通路だけで、いろいろな設備類は入ってきていなかったと思います。","voiceIndex":158,"id":"exchange-044"},{"speaker":"原委員","kind":"質問・要望","question":"そうしましたならば、これは質問じゃなくて、お願い事ですけれども、やはりこういう通路、それから橋なんかもよくあるんですけど、橋梁なんかも、とにかく安全を特に注意していただきたい。ですから、片方で固まっちゃうと、さっきからずっと南委員からも出ているように、その辺のところですので、その辺はしっかりと、でき上がってからということではなくて、もう一回詰めていただきたい。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":160,"id":"exchange-045"},{"speaker":"阿部委員","kind":"質問","question":"少し重なるかもしれませんけれども、渡り廊下について伺いたいと思います。もう一つ、特別支援教室が２階にありますけど、当然できているとは思うんですけれども、バリアフリーでどちらのほうの４フロアにも移動できるようになっているのか、ちょっと図面からわかりにくかったものですから教えてください。","respondent":"宍戸施設整備課長","answer":"それとバリアフリーですけれども、図面では確かにわかりにくいんですけれども、北棟は北棟、南棟は南棟で、バリアフリーで車いすの方がすべてのところに行けるかどうかというチェックは当然ながらしてございまして、例えば南棟の場合は。","voiceIndex":161,"id":"exchange-046"},{"speaker":"阿部委員","kind":"確認","question":"そうすると、北棟からの避難通路、それで校庭に抜けていくというのは、これは道を横切るというのも避難通路になっていると考えていいのか。確認させてください。","respondent":"宍戸施設整備課長","answer":"したがいまして、法令上あるいは消防や何かとの協議の上では、北棟は北棟で一つ完結して避難ができるかどうか、それから南棟は南棟で完結して避難ができるかどうかというのを検討してございまして、避難した先でさらに南棟の校庭に一時的に集まるというふうなことの場合には。","voiceIndex":163,"id":"exchange-047"},{"speaker":"阿部委員","kind":"質問","question":"要は北棟にいる生徒や教職員は、非常時のときにはどこに逃げるんですか。必ずしも運動場ということじゃなくて、どこか外に出ればいいよという話なんですか。そこのイメージがつかめなくて。","respondent":"宍戸施設整備課長","answer":"すべて屋内の連絡通路を通るということではなく、北棟の避難階段で１階までおりて、避難通路を通って校庭側に南棟の校舎のわきを通っていくというルートも含めて最終的には校庭に一時避難をするというふうなことだと思います。","voiceIndex":165,"id":"exchange-048"},{"speaker":"金野副委員長","kind":"質問・要望","question":"電気設備のほうですけれども、２番の非常用発電機設備、北棟と南棟の屋上にそれぞれ設置というふうになっているんですが、ここに書いてあるように、非常用のときは２時間で足りるのでしょうかというか、これで大丈夫なんでしょうかということと、それから５番の情報通信網の設備ということで、電話線を引いていく工事だと思うんですけれども、特に今回災害時、この間事件が大井二丁目であったときに。","respondent":"宍戸施設整備課長","answer":"それと、電話回線についてなんですけれども、その辺、今回の災害を受けて、ある程度できる範囲内で対応したいと思いますけれども、今のところ通常の電話回線の仕様で入ってあります。","voiceIndex":167,"id":"exchange-049"},{"speaker":"金野副委員長","kind":"質問・要望","question":"給排水の水道管、理解はしているところです。下水道はしてくださっているということですが、水道管という試みもわかりました。電話回線ですね。契約の案件で、これは契約が済んでいることなんですが、ここら辺、どうなんでしょうか。お願いをしたいところであります。もう既に設計図ができているところなんですけれども、どうなんでしょうか。お考えをちょっと聞かせてください。","respondent":"宍戸施設整備課長","answer":"確かに非常時じゃない、通常時の場合のバリアフリーということで、基本的にはエレベーターを使って上のほうの階に行っていただくんですが、非常時のときにすべてスロープでつなぐとなると、相当な面積も食いますし、距離も必要になるということで、車いすの方がいらっしゃって。","voiceIndex":169,"id":"exchange-050"},{"speaker":"金野副委員長","kind":"確認","question":"確かにスロープだけでは避難ができないので、多くの方の手をお借りして避難をしていくんだろうと思いますが、全部スロープで結ぶということではなくて、一部の階段はそういった場所もつくられるといいのかなと、そんなお考えはどうなのかなというところを確認させていただきました。意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":171,"id":"exchange-051"},{"speaker":"南委員","kind":"質問","question":"何でそんなことを言うんですか。今までの質問の中で２回やっている方だっていらっしゃるじゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":173,"id":"exchange-052"},{"speaker":"南委員","kind":"質問","question":"それから今節電、省エネルギーだとか、それからあとエネルギーの問題で電気設備のところでは、いろんな対応がされていると思うんですけど、省エネの対応、空調設備ですか、ここのところでそれぞれの施設に応じた設備を導入しているというふうに理解するんですけれども、ＣＯ２との関係ではどういうふうに、ＣＯ２の排出をできるだけ少なくするとか、省エネルギー。","respondent":"阿部経理課長、宍戸施設整備課長","answer":"辞退の件ですけれども、３者のうち二つのグループが辞退したということについては、私どもとしては非常に残念だと考えています。ただ一方で、ほかのグループが、他者が辞退をしたというふうなことを知り得る状況にございません。ＣＯ２削減につきましては、例えば屋上緑化のほか、ひさしとかルーバーによる日射のコントロール等により、ＣＯ２削減を図っているというものです。太陽光発電も小さいものですけれども、載せてあります。","voiceIndex":175,"id":"exchange-053"},{"speaker":"阿部委員","kind":"質問・要望","question":"ただし、先ほども述べましたとおり学校の中での避難の仕方というのは、やはり学校独特のものもありますし、ただ、法に適合しているというだけではなくて、きちんと学校としての安全の確保の仕方ということ、どれだけ学校が責任を持って安全を確保できるのかということをきちんと教育委員会と詰めて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":181,"id":"exchange-054"},{"speaker":"南委員","kind":"質問","question":"私は反対です。反対の理由は、避難路の関係で、一定程度先ほどからコンセプトは伺いましたけれども、しかし、７００人近い子どもたちが避難をするという点では、そしてまたこの南側の校庭に避難するという点についても、植栽も含めて前面の道路もあるというところで、やっぱり緑を整備するということは大事な視点ですけども、避難というふうに考えたときに、この図面を見たときには、やはり不安が残ります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":182,"id":"exchange-055"},{"speaker":"須貝委員","kind":"意見","question":"賛成です。ちょっと一言だけ。今回やっぱりこれだけ設計図が複雑というか、多岐にわたっていろいろ工夫されてつくられているんですが、やはりわかりにくいということならば、ある程度模型というのが必要になってくるんじゃないかなということをちょっと思いましたので、自分の意見として思ったことを述べします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":183,"id":"exchange-056"}]},{"id":"topic-06","title":"の第４４号議案、清水台小学校（2)棟）改築その他工事請負契約","agenda":"の第４４号議案、清水台小学校（2)棟）改築その他工事請負契約","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"改築工事の間は、授業はどうなるんでしょうか。子どもたち、最初の段階からお聞きして申しわけないんですけど、改築の間は一たん既存の校舎を壊すんですか。ちょっとごめんなさい、勘違いをしているかもしれないんですけど。どういう全体像になるんでしょうかということを教えてください。","respondent":"阿部経理課長","answer":"実はここに仮設校舎を建てております。ですから、この仮設校舎で授業を行いまして、今回の2)棟の改築を行うという形になっています。もう仮設校舎を建てております。","voiceIndex":192,"id":"exchange-057"},{"speaker":"阿部委員","kind":"質問","question":"仮設校舎で来年の夏まで授業を行って、来年の夏休み以降からこの新しい校舎をオープンするということでよろしいんでしょうか。それと、ごめんなさい。清水台小学校は、擁壁の工事をするという話もあったかと思うんですけれども、それはスケジュール的には同じ時期なんでしょうか。","respondent":"宍戸施設整備課長","answer":"それで、擁壁工事ですが、2)棟の旧校舎を解体すると同時に、擁壁の部分の工事を先行させてやってございまして、擁壁の工事というのは、ここの部分のちょうど工事です。","voiceIndex":194,"id":"exchange-058"},{"speaker":"南委員","kind":"質問","question":"工期がこれから１年間、来年の８月１７日までなので、１年ちょっとぐらいの期間かなと思うんですけど、規模が比較的小さいので、１年ぐらいで工期が完了するというふうに理解していいんでしょうか。それと今プレハブが建っているというところは、この工事が終わったときにはこの学校の校庭というふうにイメージしていいんでしょうか。なかなかちょっと地域的にもわからないので教えていただければと思います。","respondent":"宍戸施設整備課長","answer":"新校舎ですけれども、鉄骨造です。鉄骨造の上、２階建てということで、工期としては１年間ぐらいで十分できるというふうに思ってあります。","voiceIndex":198,"id":"exchange-059"},{"speaker":"南委員","kind":"質問・要望","question":"わかりました。中原街道に面しているというところで、地域的には住宅街で静かなところではありますけども、比較的交通量の多いところに面しているという点で、その辺の配慮をしっかりされた植栽になっていただきたいなと、ちょっとそういう思いがあって伺いたいと思います。","respondent":"宍戸施設整備課長","answer":"外構の全面的な改修、がらっとレイアウトや何か、植栽や何かもやり直すというふうなことでは考えてございませんで、当然仮設校舎を撤去したときに補修が必要になりますので、その範囲内での補修というのをやりつつ、校庭として使えるような仕様にしていくというものです。","voiceIndex":200,"id":"exchange-060"}]},{"id":"topic-07","title":"の２、「その他」","agenda":"の２、「その他」","exchanges":[{"speaker":"南委員","kind":"質問","question":"共産党の石田ちひろ議員の、原発からの撤退、自然エネルギーへの転換に関する一般質問に関連をして、少しだぶってしまうところもあるかもしれませんが、原発に対する区の姿勢、とりわけ区長の考えを伺えなかったので、それについてなどもお聞きしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":211,"id":"exchange-061"},{"speaker":"伊藤委員長","kind":"質問","question":"今、南委員から原発に関しての所管質問を行いたいとのお話がありましたが、なかなか難しいのではないかと思います。明日、理事者側に原発や放射線のことをお伺いしたとしても、例えば副区長が答弁できるかといえば、それは無理ではないかと思いますので、委員長としては、別の質問があるのであればお願いしたいと思いますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":212,"id":"exchange-062"},{"speaker":"南委員","kind":"質問","question":"確かにそうかもしれませんが、区として原発そのものをどうみていくのか、どう考えていくのかというのは大切だと思うんです。実際、他の区でも自然エネルギーへの転換ということを言われている区長さんもいらっしゃるので。ですから、この件に関してお聞きしたいと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":213,"id":"exchange-063"},{"speaker":"南委員","kind":"質問","question":"わかりました。そういうことであれば、今回は所管質問は遠慮します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":215,"id":"exchange-064"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1884#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":54472,"voices":217}},{"id":"h23-20110628-6","meetingId":"h23-cm06","date":"2011年6月28日","dateIso":"2011-06-28","committee":"区民委員会","time":"午前１０時００分～午前１１時１７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"を行います。 初めに、(1)の平成２３年度協働事業提案制度の実施","agenda":"を行います。 初めに、(1)の平成２３年度協働事業提案制度の実施","exchanges":[{"speaker":"宮崎委員","kind":"意見","question":"１点だけなんですけれども、実施が１年間ですよね。いろいろ、区民とかに協力してもらうのが１年でどんな感じになるのかなと思うんですけど。評価の仕方というか、そこら辺がわからないんですけれども。","respondent":"今井協働・国際担当課長","answer":"今、２点のご質問いただきました。実施期間が１年間であること、そして評価についてです。","voiceIndex":7,"id":"exchange-001"},{"speaker":"山元委員","kind":"質問・要望","question":"１つだけお伺いします。今回で４回目ということですけれども、現在１１団体、申し込みがあるんですか。今まで、４回目というから１回目、２回目、３回目とあるわけですけれども、今までその回ごとに申し込み団体の推移というんですかね、どのぐらいあって、多いのか少ないのか、その反応といいますか、その辺をちょっと教えていただきたいと思います。","respondent":"今井協働・国際担当課長","answer":"私の説明不足で申しわけありません。こちらは説明会に、テーマに興味を持って内容を聞きにいらした団体が延べ１１団体あるです。今、委員のほうからどのくらいの申し込みがあったかですが、平成２０年度は区から提起する課題、３テーマにつきまして、１団体のご応募がありました。","voiceIndex":11,"id":"exchange-002"},{"speaker":"石田副委員長","kind":"提案","question":"１点だけちょっと。説明会なんですが、これ、１６日と２１日。木曜日と火曜日。これ、平日ですよね。両方とも。それで、社会貢献活動を行う民間事業等も提案できる団体の中に介入されているので、民間がそういった説明会にも来やすいように、できたら週末も検討していただきたいなと思うんですが、その辺、区の考えを聞かせてください。","respondent":"今井協働・国際担当課長","answer":"確かに平日ということはあるんですが、実際この事業を運営していきますと土曜日・日曜日だけじゃなくて平日も、本当に事業としてやっていきますので、やはりかかわりとしては平日も一体になって活動していくことが大切だと考えていますが、一方、委員ご指摘のとおり。","voiceIndex":14,"id":"exchange-003"}]},{"id":"topic-02","title":"の品川区セーフティアップ運動の推進","agenda":"の品川区セーフティアップ運動の推進","exchanges":[{"speaker":"宮崎委員","kind":"意見","question":"事業内容のところで、特にということで４つ例が挙げてあるんですけれども、ほかにはどういうふうにやっているのか。今、私もやはりすごく感じるのは、ここにも振り込め詐欺と書いてあるんですけれども、振り込め詐欺に似てるんですけれども、マルチ商法、マルチまがい商法とか、そういう商取引にかかわる被害といいますか、それも非常に多いなという感じがするんですよね。","respondent":"川崎生活安全担当課長","answer":"したがいまして、マルチ商法に対する取り組みについてやらないのではなく、まずこの４つを重点的に対応して、総数を減らしていく。そして、その次にマルチ商法だとか、空き巣対策だとか、そういうところにも取り組んでいきたいという流れです。","voiceIndex":21,"id":"exchange-004"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、私は、あまり順番を決めるものではないんじゃないかなとは思うんですけれどもね。これをやってからこうだという。要するに区民のほうが注意すべきことをもっと、注意喚起だとか、そういうことが必要であると思う。それはやっちゃいけないとは言わないけれども、まちの住民のほうに注意喚起だとか、そういうものがやはり一番、私はやる必要があるんじゃないかと思うんですけれども。","respondent":"川崎生活安全担当課長","answer":"委員のご指摘のとおり、マルチ商法などの犯罪についてもですね、警察を通じ注意喚起、住民の方へは引っかからないためのアドバイスなどなどについて、こちらから働きかけていくことを考えております。","voiceIndex":23,"id":"exchange-005"},{"speaker":"沢田委員","kind":"質問","question":"街頭防犯カメラの設置というところなんですけれども、今、大体、品川区内でどういうところに設置されているのかなというのと、それによって街頭の防犯カメラでひったくりとか、そういう現場を押さえたりとか、そういうことというのは今までにあったのかなということと、それから、刑法犯の認知件数で２３区中１７位ということで、４３％が自転車盗ということだったんですけれども。","respondent":"川崎生活安全担当課長","answer":"隣の目黒区と比べましても、数字的に言いますと、品川区が昨年は１,１９１件、目黒区が１,００５件、大田区が２,６３６件というところでありますので、極端に多いというところではないんですが、自転車盗がやはり４０％ぐらいを占めていますので。","voiceIndex":25,"id":"exchange-006"}]},{"id":"topic-03","title":"品川学園の校庭","agenda":"品川学園の校庭","exchanges":[{"speaker":"本多委員","kind":"質問","question":"地域開放のスポーツ団体の一番、調整するものが大変な部分になると思うんですけれども、具体的に調整する方はどなたがされるんでしょうか。概要を教えてください。","respondent":"安藤文化スポーツ振興課長","answer":"各団体、連盟等がありますので、まずは連盟内部で調整していただいて、そして、課としては青少年育成課が調整をする形になってまいります。","voiceIndex":32,"id":"exchange-007"},{"speaker":"本多委員","kind":"質問・要望","question":"青少年育成課ということで、区の青少年育成課が直接やってくれればすごくうまくいくんだと思うんですが、管理委員ですか、管理委員。地域の。そういう方に頼んだりするのか、その辺が、本当に公平、公正に、利用登録団体の方たちが納得というか、うまくやっていただきたいという要望なんですけれども、もし何かその点であれば。課が違うんで、あまり答えられないかもしれないですけれども。","respondent":"安藤文化スポーツ振興課長","answer":"青少年のスポーツ団体に対しても、今のご指摘の、ご懸念の調整も速やかに、円滑な調整をしていくために青少年育成課が中心となってやっていこうということで今、協議を進めているところです。それで、調整をして、一定のルールをつくっていこうと思っています。","voiceIndex":34,"id":"exchange-008"},{"speaker":"宮崎委員","kind":"質問","question":"１点伺いたいんですけれども、例えば少年野球ですと、例えば荏原のほうの地域だと主に使うグラウンドですよと。大体、地域で主に使うグラウンドというのはあると思うんですけれども、どういうふうになるんでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"少年野球については、連盟が各地区にそれぞれございまして、基本的にはそれぞれホームグラウンドというのを持っています。しかし、今回のこの品川学園の校庭につきましては、品川地域じゃなくて全体、品川区全体を網羅した対象を考えています。","voiceIndex":36,"id":"exchange-009"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、かなり区内全体からいろいろ集まってくるということになるんですけど、そうすると、ちょっと細かいことなんですけれども、自転車とか、車とかですね、そういう交通手段で来た場合の対応だとかというのは具体的にどういうふうになるんでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"駐輪については、空きスペースをどこかに確保して、そこに駐輪場をつくるというような話で進めています。","voiceIndex":38,"id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"さっきの質問と絡むんですが、かなり、区内全体ですとやはりどうしても使いやすいところと、ちょっと遠いなあという部分とあると思います。使用の枠みたいなのはつくるんでしょうか。近くだとやはり希望が集中すると思うんですけれども。","respondent":"安藤文化スポーツ振興課長","answer":"そういう中で、まず少年野球連盟の中で、連盟同士で調整する。少年サッカーも少年サッカー連盟の中で調整をして、連盟同士、少年野球連盟と少年サッカー連盟が調整をして、青少年育成課から私どものほうに報告されるというような流れを考えています。","voiceIndex":40,"id":"exchange-011"},{"speaker":"大倉委員","kind":"質問","question":"これを見ていて、土曜日・日曜日、祝日、地域のスポーツ団体が使うということですから、地域の学校を利用している一般の子どもたちというのは使うことができないんでしょうか。よく、校庭開放とかというのは、こちらでは考えていないんでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"ここが基本的には子どもたちの遊び場となるような形で考えているというようなお話ですけれども、詳細についてはまた今後、検討して詰めていくというふうにしています。","voiceIndex":42,"id":"exchange-012"},{"speaker":"石田副委員長","kind":"質問","question":"ちょっと、今のと、大倉委員の質問と重なるところがあるんですが、これ、土曜日は第１グラウンドは学校の部活動で利用されるということで、日曜日においては全面、少年少女スポーツ団体。みんながみんな部活動をしているわけではないじゃないですか。","respondent":"安藤文化スポーツ振興課長","answer":"今回、ここで、地域開放の基本的な考えという枠組みを提起させていただいて、今のようにご指摘も、学校のお子さんたちの遊び場としての開放という部分も今後、想定していきながら、教育委員会のほうで考えていくというふうに理解しています。","voiceIndex":44,"id":"exchange-013"},{"speaker":"山元委員","kind":"質問","question":"すみません、１点だけお願いします。今、この図面を見たときに、土曜日、校庭開放なさるということで、その間に野球やったり、いろいろやっている中で、ネットというんですかね、安全性というのか、ちょっとその辺がどういうふうな形になっているのか、ちょっと教えていただければと思います。","respondent":"安藤文化スポーツ振興課長","answer":"第１グラウンドと第２グラウンドについては野球もできるということで、ネット等はないというふうに聞いています。","voiceIndex":46,"id":"exchange-014"},{"speaker":"山元委員","kind":"質問","question":"野球をやったことが、見るだけでやったことはないのでわからないですが、その辺は、第１グラウンドと第２グラウンドで、ボールがここへ来てぶつかるとか、そういう危険はないんですか。","respondent":"安藤文化スポーツ振興課長","answer":"失礼しました。基本的には少年野球が活動している場合は、サッカーをしないとか、サッカーをする場合は少年野球はしないと、基本的にはそんな形ですみ分けをしていくというふうに考えています。","voiceIndex":48,"id":"exchange-015"}]},{"id":"topic-04","title":"観光案内所の開設","agenda":"観光案内所の開設","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"これ、長年のですね、いろんな願いというか、いろんなものが、区民や区内外から希望というか、いろんな要望があって、長年の夢というか、それが実現するというような思いがあって、本当によかったなと思うんですけれども、まず、場所なんですけれども、大井１丁目共同ビル１階というのは社会福祉協議会が入っているビルだと思うんですけれども、道路に面したあのスペースだと思うんですけれども。","respondent":"米田商業・観光課長","answer":"今後、人員配置等の態勢を検討し、あるいは土曜日・日曜日を試験的に開放して、その効果を見きわめつつ、将来的には、将来的にはといいますか、土曜日はなるべく早く開設をしていく。これは観光ガイドボランティア等の配置も含めて、検討しているということで聞いてあります。","voiceIndex":56,"id":"exchange-016"},{"speaker":"山元委員","kind":"質問","question":"ＰＲ活動等ということで、これを見ますと、区内の人を中心に考えていると。やはりそうすると、観光案内所ですか、あまり目立たないところにありますよね。おりていかなきゃないわけだから。そういう意味では、矢印といいますか、こっちにあるよみたいな、何か駅前にそういう札というんですか、看板というか、何かそういうものを設置する予定というのはありますでしょうか。","respondent":"米田商業・観光課長","answer":"そちらのほうに追加で何かしらの案内ができないかということは関係所管との調整を図って、案内をしやすいなような形で今後、検討してまいりたいと、このように考えてあります。","voiceIndex":58,"id":"exchange-017"},{"speaker":"石田副委員長","kind":"質問","question":"観光案内所、先ほど、本多委員からも、やはり土曜日・日曜日、観光ですから、課長も「観光」という言葉を聞いたときに、やはり土曜日・日曜日をイメージすると思うんですよ。","respondent":"米田商業・観光課長","answer":"片や、しながわ観光協会のほうも、現在、平日に通常営業業務等を行っておりまして、そちら、事務局業務等もあわせて開所日をさまざま検討いたしまして、例えば平日を１日閉めてでも土曜日開けるんだというようなことも検討はしていただきましたけれども、その辺につきまして。","voiceIndex":63,"id":"exchange-018"}]},{"id":"topic-05","title":"大井町サービスコーナーにおける図書サービスの実施","agenda":"大井町サービスコーナーにおける図書サービスの実施","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"この事業をやるのにどのぐらいお金がかかるんでしょうか。","respondent":"梶戸籍住民課長","answer":"ただいまの、この事業をするに当たっての費用ですけれども、あちらのほうはスペース的な中身を変えましたので、そちらのほうで１００万円ほどかけてあります。そのほかに、あそこは非常勤職員が入ってありますので、その職員を２名ほど入れたという形になってあります。","voiceIndex":70,"id":"exchange-019"},{"speaker":"藤原委員","kind":"質問","question":"行政サービスコーナーにおけるこの図書の取り扱いのサービスというのはすばらしいと思っているんですけれども、今後、こういう形で、区内でどういう方法でやるかということと、それと、今、課長が言ったように品川図書館が品川区の図書館の中心というか、本部みたいな形でやっているけれども、こういうふうに行政サービスのこのコーナーのこういうシステムがうまくどんどんいくならば。","respondent":"梶戸籍住民課長","answer":"これは今後どういった形で、図書館のほうで見ていくか、今後の数字次第かなと考えております。","voiceIndex":76,"id":"exchange-020"},{"speaker":"宮崎委員","kind":"意見","question":"二葉図書館の休みというか、その関連の説明をちょっと聞きたいんだけれども。まあ、大井町だともっと増えるのかなと思うんですけれども、どのくらいに位置しているのかというのと、あと、大井町行政サービスコーナーというので、今、パソコン等の配置という説明をしてましたけれども、あとほかにどういう、本そのものをですね、どういうふうに備えていくのかとか、どんなふうに考えているのか。","respondent":"梶戸籍住民課長","answer":"二葉図書館との関係なんですけれども、二葉図書館のほうはですね、休館になるから大井町行政サービスコーナーでやるという流れではございませんで、あくまで、今ご説明差し上げたのは、二葉図書館のほうが休館になりますけれども。","voiceIndex":78,"id":"exchange-021"},{"speaker":"宮崎委員","kind":"質問","question":"わかりました。わかりました。で、あと、図書館に行きますとやはり、具体的にこの本というものでは、例えばこういうことを調べたい、こういう感じの本がないかといろいろ相談に乗ってもらったりするんですけれども、ここには、行政サービスコーナーには、どこまで充実するかというのはあるんですけれども、どんなものなんでしょうか。","respondent":"梶戸籍住民課長","answer":"取り扱いは、今行政サービスコーナーにいる職員ですので、図書等の専門的な職員ではございませんので、あくまでも証明書発行と一緒に仕事をしているわけですので、そういった本等の相談とか、そういった業務は原則はできないというか、やらないで。","voiceIndex":80,"id":"exchange-022"},{"speaker":"宮崎委員","kind":"質問・要望","question":"このスペースでどこまでやるかという問題、あとは、本格的な図書館の機能を持たせるかどうかとかいろいろ問題もあろうかと思うんですけど、やはりこういうサービスをやっていくと、今みたいな、もしかしたらそういうどこかいい本がないかとか、そういう注文も出てくるかもしれないですよね。これはちょっと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-023"}]},{"id":"topic-06","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"視察がよくないと言っているんじゃないですよ。視察に行って、視察をしてきて、区政の中にというのはわかるんですけれども、この緊急なときに視察ありきという発想が出たというのはちょっと、どういうもんかなという思いがあるので、まず、調査項目、調査場所という前に、自分の意見として出させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-024"},{"speaker":"本多委員","kind":"意見","question":"実施する、実施しないという前に、やはり我々、付託を受けている区民委員会所管の問題、課題をまず出し合うということが大事なことなんですけれども、それも、課題はこれがあるということで、みんなそれぞれお持ちだと思うのですけれど、それの中で集約して、最終的に実施するかしないか、また判断するときは判断して、８月２２日ぐらいまでに、じゃ、決定をするだとか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":100,"id":"exchange-025"},{"speaker":"宮崎委員","kind":"提案","question":"私自身、特に提案を持っているわけじゃないんですよ。だから、まあ、今、この震災の関係もやはりありますけれども、やはり、やる、やらないというか、もうちょっと深めるというか、問題意識を深める必要があるんじゃないかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":102,"id":"exchange-026"},{"speaker":"山元委員","kind":"質問","question":"逆に、動くことによって、動くというか視察にすることによって、今、委員長がおっしゃいましたけれども、もし相手先、万が一東北のほうに行くようなものがあるならば、ある程度、ご事情もちろんおありでしょうから、だめであれば違うふうに考えればいいのであって、やはり今回の、調査項目もちゃんと出ているので、それを中心にいろいろと皆さんで議論をして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-027"},{"speaker":"本多委員","kind":"質問","question":"例えばものづくりだとか、産業振興、商店街とか、みんなそれぞれ挙げれば切りがないと思うんですが、まずはこの所管事務調査で正副委員長案を出していただきまして、先ほど決まりましたので、この２つの項目を充実する。これにこだわるわけではないんですが、これをまず充実するようなことで組み立てていって、あとそれを膨らませてもいいんじゃないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2610#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":24023,"voices":110}},{"id":"h23-20110628-7","meetingId":"h23-cm06","date":"2011年6月28日","dateIso":"2011-06-28","committee":"厚生委員会","time":"午前１０時００分～午後０時１２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第２期品川区地域福祉計画","agenda":"第２期品川区地域福祉計画","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"ふれあいサポート活動はこれからもどんどん推進していくと思うんですけれども、今現在の利用者がどれだけあるのか。孤立死の現状をお聞きしたいと思います。","respondent":"原高齢者福祉課長","answer":"学校でつくった給食を地域の方にお配りするということで進めてまいっておりまして、こちらはこの３月で廃止となっていますけれども、平成２２年度の実績で約３００人の方にご利用いただいたところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これを読ませていただいて、まず、１０年ということ。ところが、これは東京都第二建設事務所がどうなのか知らないけれども、ちり取りとか、ほうきとか、そういうのは持ってくるけれども、それに対する手間というのかな、町会の人が２０人も３０人も出てやるわけだけれども、基本的には金額ゼロ。だから、ここら辺の考え方をどうとらえていらっしゃるのかなというところを教えてほしい。","respondent":"原高齢者福祉課長","answer":"は最初に、１０カ年のところです。これは先ほども説明の中で、第１期と第２期、理念を含めて変えてございませんということです。内容につきましては、第１期も地域の支えあい、協働、地域でのコミュニティ、こういったところをうたってきました。","voiceIndex":7,"id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問","question":"非常に大変、今のがそのまま聞くわけにはいかないなと思った部分、理念を書いて、皆さん協働してやってください、共助でお願いしますということがずっと書いてあるわけね。個々にいろいろなことをやっていきますよ。別に高齢者クラブの友愛活動があってもいいわけだ。別にそれは。友愛活動としてしっかり事業をやってくれている。私の感覚でいうと。そこはもう一度、再度考え方を教えてほしい。","respondent":"木下健康福祉事業部長","answer":"そのためのインセンティブとして、今ご提案があった部分もあるんだろうと思うんですけれども、本来の姿としては、やっぱり課長が申し上げましたように、やはり地域の中でやむにやまれない心情ですか、見守りをしなければいけない、例えば孤立死の問題について、今。","voiceIndex":9,"id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"一番いいんだと。だけど現実はそうなの。こういうことが個人情報とかいうことで扱われると、わざわざそこを避難路とする訓練もして、そんなばかげた話はないわけで、本当に何でもかんでも過剰だというふうな形が書いてあったけれども、過剰にそういうことをあまりにとらわれ過ぎると、本来の趣旨がどこへ行くのかというのが、わけがわからなくなるときあるので、ぜひこれは気をつけてほしいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"向委員","kind":"質問","question":"私は成年後見人のことについてお尋ねしたいと思います。２人という数は、ゼロではないということは、私自身大変驚きです。こういった中で、品川区としては市民後見人の養成を今後力をさらに入れていかれる上で、大体年間何人ぐらい養成できれば、実際どれくらいの方を年間増やしていきたいかというお考えなのでしょうか。今、市民後見人の会では実際に受任をしているのは１０件、９件ぐらいだと伺っています。","respondent":"原高齢者福祉課長","answer":"１つの事例で、救急車が呼ばれた場合に、その方が親族はどういった方なのかとか、あるいはどういうような病院にかかっているとか、そういったものを救急キットということで冷蔵庫の中にそういった情報を入れておく、それによって救急隊が入ってきたときに素早く対応ができる。","voiceIndex":12,"id":"exchange-005"},{"speaker":"向委員","kind":"質問・要望","question":"毎年５０人養成するということで、私ももうちょっと具体的にお伺いすればよかったんですが、となると、私もちょっと養成講座に出たことがありまして、２０人ちょっと、そのときは参加されていたんですが、実際その中でまだ市民後見人になっている方はいらっしゃらないようなので、５０人程度を養成するとなると、実際動ける方はこの中でどれくらいの方、手を挙げてくださるかなというところがあるので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-006"},{"speaker":"鈴木（博）委員","kind":"質問","question":"常に私はいつも、その質に関してどうなのか。どうやっていろいろと力づけられてサポートされたかと、そちらのほうが問題だと思うので、その辺の質の評価というのはどうなっているのかなということ、１つ読ませていただいて感じました。それに関して一度お聞きしたいと思っていたので、それもご一緒に、ちょっとお聞きしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-007"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"私もこちらでは駆け出しなので、これからもいろいろと情報を仕入れて、いろいろ教えていただきたいと思いますし、今の施策が軌道に乗るように心から応援しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-008"},{"speaker":"若林委員","kind":"質問・要望","question":"最後に、３８ページのデータのほうになりますが、(11)のボランティア活動や助け合いへの参加意向ということで、約５０％弱の方が「ぜひ参加したい」、また、「誘いやきっかけなどがあれば参加したい」とあるんですが、これ、年代別に大体どういうデータになっていましたでしょうか。ちょっと確認のために教えていただきたいと思います。","respondent":"原高齢者福祉課長","answer":"こちらにつきましては、顔が見える中でというお話も、私も当然考えてございまして、今、品川第二地域センターはモデル事業で実施しておりまして、そういった中で、ニーズであるとか、そういったものを十分把握する中で。","voiceIndex":21,"id":"exchange-009"},{"speaker":"若林委員","kind":"質問・要望","question":"１点目のほうは、これは社会福祉協議会の人材育成という部分も当然絡んでくると思いますけれども、場所は１つだけれども、配置を厚くすることによって２つ、３つに割っていく、この地域はＡさん、この地域はＢさん、そこには地域センターの職員の方もかぶさっていくというコーディネーター的な、やっぱり地域計画、細かい視点でぜひ見ていただきたいなということは要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それともう１つは、その１つとして、地域センターのコーディネーターというのがあるのではないかと思うんですが、このコーディネーターは、品川第二地区で平成２１年度から、荏原第二地区はいつからやってきたのかがちょっとわからないんですけれども、やってきたということで、先ほどご報告がありましたけれども、品川第二地区でされていたのが民生委員のＯＢの方ですか。","respondent":"原高齢者福祉課長","answer":"今後の展開、評価というんですか、検証ですけれども、荏原第二地域センターのほうでも実施いたしますので、品川第二地域センターのほうは平成２１年度から考えれば３年ですけれども、荏原第二地域センターがこの秋にスタートしますので。","voiceIndex":24,"id":"exchange-011"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"先ほどお聞きした中に、新たなこの計画の中でコーディネーターの配置というのは、そのうちの１つだと思うんですが、それ以外のところで新たな事業の主なものというのがありましたら、教えていただきたいということもお願いしましたので、それがありましたら、ひとつお願いしたいと思います。検証して１３地区に配置されるというのがいつからになるのかということを改めて教えていただきたいと思います。","respondent":"原高齢者福祉課長","answer":"そういったところでは、１７ページにあります生活面で最も支援が必要なというところでご案内させていただきましたけれども、食事でありますとか、あるいは買い物、見守り、憩いの場、こういった４つの視点の中で生活面の支援が必要だということで。","voiceIndex":26,"id":"exchange-012"}]},{"id":"topic-02","title":"平成２２年度品川区介護保険制度の運営状況","agenda":"平成２２年度品川区介護保険制度の運営状況","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"９ページの徴収方法別対象者のところの普通徴収のところで、７７.９％とありますけれども、単純計算すると、滞納されている方が２,７５７人というふうになるんですが、こういった滞納されている方は、ペナルティか何かを受けてしまうのか、滞納されている方がサービスを受けたいと思ったときには受けられないのかどうなのかと、そういったあたりをお聞きしたいと思います。","respondent":"原高齢者福祉課長","answer":"区の対応といたしましては、こうなる前にご利用者様のほうに通知を出させていただいて、予告通知という形で、そうならないためのご案内をさせてもらう中で対応しているということで、基本的には先ほどの１年以上等々については、該当者は今のところいないです。","voiceIndex":32,"id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"徴収率のところで、滞納者には、やはり保険料と同様に介護も命にかかわることだと思いますので、ぜひ個々の払えない状況なども考慮していただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-014"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"多分区外のところで入れないという状況があるのかと思うんですけれども、そこら辺のところがわかったら教えていただきたいのと、それから、現場からは特養ホームにぜひ夜間も看護師を配置してほしいという要望をいただいていまして、実際に看護師が、部分的ではありますけれども、配置されているというところがあると思うんですけれども。","respondent":"原高齢者福祉課長","answer":"認定率の１％増のところですけれども、私どももここのところについては、数値として把握に努めているところです。１つ、高齢者人口が増えているというところ。そういった中でも、新規の申請が増えているといったところが、ひとつ着目する点ではないかと思っているところです。","voiceIndex":37,"id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それで、老健でも６０人ぐらい増えているわけですけれども、こういうふうに老健や特定施設、有料老人ホームのところが増えているという背景というか、そこら辺のところを区としてどう考えられているかということを１つお聞かせいただきたいのと、もう一つ、さまざまな給付費は棒グラフで出ているんですけれども、市町村特別給付はトータルでどれぐらいになるかということも。","respondent":"原高齢者福祉課長","answer":"市町村特別給付の関係ですけれども、金額といたしましては、資料には載ってございませんけれども、２,４００万円ということで数字を把握しています。","voiceIndex":39,"id":"exchange-016"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ありがとうございました。老人保健施設なんかは、特養ホームに入れないために待っているという方が入らざるを得ないという状況もありますし、有料老人ホームも、もうどうにもならなくてということで入らざるを得ないという状況もありますので、改めて私は特養ホームの増設をぜひ急いでやっていただきたいということを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-017"}]},{"id":"topic-03","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"石田（秀）委員","kind":"意見","question":"これは、後で正副にお任せしますけれども、せっかく老健をつくろう、特養をつくろうという話もあって、老健の中でも医療法人という形ではないんだけれども、医師会みたいなところが老健をやっているという施設が広島にあるそうでありまして、せっかくそういう介護とか、今いろいろな話も出ている中で、そういう施設があるのであれば、そこはどうかなという考えがあるということで、あとはお任せします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-018"},{"speaker":"鶴委員","kind":"提案","question":"ほかの自治体でもさまざま幾つかありますけれども、そうした施設を今後品川区の中でも、今既存のところの改装等も含めて、参考にできるのではないかと思いましたので、それを提案したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今年度の所管事務調査が精神保健福祉という項目が入っていますので、精神障害の親の会のほうからも要望として出されています、ＡＣＴ。ＡＣＴ－Ｋというのが京都で、この本もいろいろ出ているんですけれども、かなり実践が豊かにされているということで、１つの項目の中にぜひ入れていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-020"}]},{"id":"topic-04","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"自民党の石田秀男議員の一般質問の中の、特養ホームのところでの「有利に取得できるよう、多面的な情報収集に努める」と、この有利なというのはどのようなことか。多面的な情報収集というのは、具体的にどういうことなのか、教えていただきたいと思います。","respondent":"原高齢者福祉課長","answer":"そういった中でも、今後を考えますと一定程度必要という認識の中で、そういったことにさせていただきました。「有利に取得できるように多面的な情報収集」ですけれども、特養を考えますと、約３,０００平米程度の土地が必要になってくると認識しております。","voiceIndex":56,"id":"exchange-021"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ、やはり特養ホームのところは今までの議論の中でもあるように、求められているところですので、安価にというのもそうですけれども、少しでもそこら辺を出してというか、公表いただいて、増設へと結びつくようにしていただきたいと思いますけれども。要望でいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"すみません。もう一度、質問のほうお答えいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-023"},{"speaker":"石田（秀）委員","kind":"意見","question":"それは地主さんもそれは当たり前のように売るけれども、そういう情報がうっかり手を出していくことによって、地主さんも、どうせなら、安いけれども区に売ろう、１,０００坪も持っているような地主なんだから、そういう人も出てこないとも限らないから、うっかり何回か手を出して負けるということも１つの情報提供になるわけだから、どうぞうっかり手を出してほしいなと思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":64,"id":"exchange-024"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ある一定の大きさの土地を売るときには、自治体にも必ず声をかけなければならないというのがあると思うんですけれども、そういうところでの情報というのは、もちろん区のほうとしても特養ホームを購入するというところでも検討されていると思うんですけれども、公有地確保法で区にこの土地を、そういうものというのはないんでしょうか。","respondent":"木下健康福祉事業部長","answer":"すぐそこの土地の件はございましたけれども、あの社内で検討中ということでありますけれども、やはり歴史的経過から言えば、当然区のほうにも一定の情報提供等が今後あると考えていますので、区としては、やはりそういう機会があればなるべく活かしていくのは。","voiceIndex":65,"id":"exchange-025"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それとあわせて、３,０００平米ということにもこだわらずに、もうちょっと小規模でもぜひ土地を探していただくというところでは、小規模もほかの施設等の併用も含めて検討していくというのが、今までの区の答弁では姿勢としてあったと思うんですけれども、そこのところは変わらないということでいいのかどうかも、ちょっと確認させてください。","respondent":"山田副区長","answer":"そのほかの都有地であるとか、さまざまな状況の中でそれぞれの機関からお話があったり、またうちのほうから働きかけてそうした情報があれば、検討は進めていきたいという姿勢です。","voiceIndex":67,"id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3298#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":39432,"voices":76}},{"id":"h23-20110628-8","meetingId":"h23-cm06","date":"2011年6月28日","dateIso":"2011-06-28","committee":"建設委員会","time":"午前１０時００分～午後２時０３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を66件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"を行います。 初めに(1)街路灯節電対策周知用看板の設置","agenda":"を行います。 初めに(1)街路灯節電対策周知用看板の設置","exchanges":[{"speaker":"武内委員","kind":"質問","question":"スローガンの件で募集したけれども、１件のみの応募ということで、節電は非常に今、関心が高いわりに、これについては、ちょっと残念な結果だなと思っているんですけれども、この辺のなぜあまり応募がなかったのかなというところはどのようにお感じになっているか、どのようにとらえているかということをまず、教えてください。","respondent":"稲田道路公園課長","answer":"それで、区民の考え方というか、気持ちということなんですけれども、私ども、この看板を実際に地元に設置していって、今後、区民の皆さんが意識を向上して、あるいは気持ちを盛り上げていっていただけることを期待しながら考えている次第です。","voiceIndex":7,"id":"exchange-001"},{"speaker":"武内委員","kind":"質問","question":"なかなか人によっては「あ、そうだよな」と思う方が大勢かもしれませんけれども、中にはやはり２割、３割ぐらいの方は「そんなこと言ったって」という声もあると思います。これから暑い夏に、この間みたいに３９度とか、きょうも東京は三十二、三度になるんでしょうから、暑くなったときに、夜、みんながクーラーをつければ大停電になって大変だよという、そう言われればそうだなと。もしわかれば。","respondent":"稲田道路公園課長","answer":"公園灯が約８７％の節電でございまして、６万８,２５１kwの約１００万円程度の減額というところで見ております。","voiceIndex":9,"id":"exchange-002"},{"speaker":"武内委員","kind":"質問・要望","question":"そうすると、両方で月額約３００万円ぐらい減になるという、これは非常に区にとってもありがたいお話なんでしょうけれども、ただ、一方で、区民の中には、夜、危険になるところがあるんじゃないかとか、そういう声もある。そういうところに充てるとか、何かそういう安全対策のためにこの浮いた分を充てるとかというような考え方をすることはできないのかどうか、どうなんでしょうか。","respondent":"岩田都市環境事業部長、中村建築課長","answer":"節電の件につきましては、ご案内のとおり東京電力が発表している昨年度の電力需要を見てみますと、１日のうち、これは夏ですけれども、夏のピークの需要は午後の１時から３時ごろと夕方の７時から９時なんです。これがピークが来る。先ほど、私道の整備の件でお話が出ましたけれども、現在、この地震とは全然関係なく、従来からの老朽化による私道の整備の申請が増えているですので、この辺はまた予算の措置も含めて所管と相談して、検討。","voiceIndex":11,"id":"exchange-003"},{"speaker":"武内委員","kind":"質問・要望","question":"ただ、本当にきついという声も聞かれるところもあるので、それについては細かくお願いしたいのと、あとはやはりまたちょっと今、言うのがいいのかどうかわかりませんけれども、大震災が起きると停電になってしまうということも考えると、これから今この削減されたものをどうこうというお話もさせていただきましたけれども、いろいろな対策の中でＬＥＤというか、太陽光ですね、太陽光を昼間蓄電して、夜。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-004"},{"speaker":"井上委員","kind":"意見","question":"啓発という意味ではあるんだろうと思うんですけれども、ほとんどが街路灯で、夜の関係のスローガンということで、夜、先ほどもちょっと出ていましたけれども、見えるかというようところがあると、蛍光塗料みたいな反射鏡とか、反射の塗料とか、そういった工夫もあっても、そんなにコストは変わらないのではないかと思うので、そういう工夫があってもいいのかなということを思うので。","respondent":"稲田道路公園課長","answer":"それと、これの設置期間ということなんですけれども、やはりこれは電力需要がどの程度になるかというのもまだ見通しが立っておりませんので、また、その街路灯を点灯するのかどうかという話もありますから、電力需要を見ながらです。","voiceIndex":16,"id":"exchange-005"},{"speaker":"井上委員","kind":"質問・要望","question":"外を歩いている側とすると、昼間、こういう看板を見ても、特にそんなに意識もなく通ってしまうんですけれども、暗いときに「あ、ちょっと気をつけなくては」とか「自分たちもあまり夜遅く不必要な外出を控えなければ」とか、そういう意味では、街路灯を消しているところに対しての周知にもなるので、暗いときに何も見えない、ただの置物になってしまったら意味がないので。","respondent":"稲田道路公園課長","answer":"そのご意見を出していただいた方にもお話をしまして、確かにおっしゃられるとおり暗いという場所もありますし、言われた方は自分の目の前が消えたので暗いよという感じで、その辺は私どもの目で見て、地域の方の意見を聞きながら丁寧に対応させてもらっている状況です。","voiceIndex":18,"id":"exchange-006"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"もう１点、すみません、ちょっと考え方をご説明いただきたいんですけれども、節電へのご協力のアピールはわかりますけれども、「防犯に対する自衛」と書いてありますけれども、これはどういう意味なのか、いわゆるどのような犯罪に対して自衛を区民に求めているのか、そこの考え方についてはご説明いただけますでしょうか。","respondent":"岩田都市環境事業部長","answer":"したがいまして、障害者への対応につきましても、我々はいわゆる生活道路を預かっている区ですから、国道や都道のようにばさっと機械的に全部消してしまうことは、もちろんできません。","voiceIndex":23,"id":"exchange-007"},{"speaker":"中塚副委員長","kind":"質問","question":"緊急事態と言うのであれば、品川区として企業に対してちゃんと定時で帰れるように、そういうご協力ができないかと、そういう働きかけはあわせて行っているのか、家族や個人の努力や声かけとありますけれども、働いている方ですから、雇われているわけですから、そういう企業への働きかけについてはどうお考えなのか、最後に伺いたいと思います。","respondent":"岩田都市環境事業部長","answer":"これは、先だって節電ビズのご説明の中でも説明させていただきましたけれども、品川区内の商工会を通じて品川区内の事業所については節電にご協力をお願いしますというＰＲをしておりますし、一般区民の方にも、「広報しながわ」とホームページ等あらゆる媒体を使って。","voiceIndex":25,"id":"exchange-008"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"節電へのＰＲや協力を求めているのは重々承知なんですけれども、要するに就業時間後はもう帰りましょうと、その働きかけですよね。そこについては行っているのか。やはりそういう会社の努力や協力がなければ、なかなかうまくいかないと思うんです。そこの点について。","respondent":"岩田都市環境事業部長","answer":"そういう、ありとあらゆる工夫で何とか電力の供給量に見合うように需要を抑えていくことが一番大事だろうと考えていますので、今後、さまざまな形でどういう工夫をすればこれが乗り切れるかということは、これからいろいろまた検討してまいりたいと思います。","voiceIndex":27,"id":"exchange-009"}]},{"id":"topic-02","title":"親元近居支援事業の実施","agenda":"親元近居支援事業の実施","exchanges":[{"speaker":"武内委員","kind":"意見","question":"これは、１０万ポイントを上限ということなのですけれども、何分の１とかそういうのはないんですね。引っ越し費用とかそういうものは大体１０万円を超えると思うんですけれども、そうすると、１０万ポイントがそのまま何分の１とかというのではなくていただけるということでいいのかどうかということと、あと、これは引っ越してくる若い世帯に対してお支払いするというかお渡しするという考えなのか。","respondent":"柏原住宅担当課長","answer":"ポイントにつきましては、引っ越し等々の費用につきましては、大体は１０万円以上、大体そうなると思いますけれども、上限を１０万ポイントとしておりますので、それ以上かかった場合は１０万ポイントをそのまま交付するというものです。","voiceIndex":34,"id":"exchange-010"},{"speaker":"武内委員","kind":"質問・要望","question":"わかりました。いわゆる、こちらに若い方が住んでいて、どうしても品川区からは出るわけにはいかないんだけれども、おじいちゃん、おばあちゃんが地方に住んでいて、２人でいるときはいいんだけれども、亡くなって今は１人になってしまったとか、それでこちらの品川区に引き取りたいけれども、一緒には今はなかなか住めないから、近くに住んでいただきたいという逆バージョンです。","respondent":"柏原住宅担当課長","answer":"どういったお声があるかというのは、今後ちょっとお声を聞きながらというところもありますので、その辺はどういった展開になっていくかということを考えていきたいと思いますが、八潮の住み替え相談センターでそういったお話も聞いたりしておりますので。","voiceIndex":36,"id":"exchange-011"},{"speaker":"大沢委員","kind":"質問・要望","question":"申し込み方法について、考え方を聞かせていただきたいんですが、すべての条件を満たすということが必要。１番から９番までですか、非常に多くの書類を出さなければいけないんですね。実際問題として、ここまできちんとして出せる、３５件ということがありますけれども、３５件、これが応募し得るものかどうかという点の見込みを教えていただきたいんですけれども。","respondent":"柏原住宅担当課長","answer":"見込みにつきましては、そういったところも含めて、初めは５０件程度と考えていたのですが、予算の関係もありまして三十何件というふうにしたんですけれども、現在、６月の先週２１日から広報を始めたんですが、思った以上に問い合わせが多うございまして、今。","voiceIndex":38,"id":"exchange-012"},{"speaker":"大沢委員","kind":"質問","question":"応募は予想以上にあるということで、先ほど住宅担当課長がおっしゃったように、このすべての要件と申し込み方法については、ある程度弾力的に運用しながら審査をしていただけるということでとっていいのでしょうか。","respondent":"柏原住宅担当課長","answer":"例えば住民票は、品川区内に入っていただくのが条件であったりしますので、その辺は弾力的にするというのはちょっと難しいのですけれども、居住面積のところであるとか、あと、例えば戸籍を出してくださいというような部分も、住民票で確認ができるようであれば。","voiceIndex":40,"id":"exchange-013"},{"speaker":"大沢委員","kind":"質問","question":"その意味で私は伺いましたので、そのような対応をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-014"},{"speaker":"井上委員","kind":"質問・要望","question":"目的のところなんですけれども、この目的、私はこの事業についてよくわからないので、賛成というよりも異議ありという視点で質問していきたいと思っているんですけれども、どういった課題からこの目的になったのか、何が解決できるのかというそこのところを少しはっきりと示していただきたいと思います。","respondent":"柏原住宅担当課長","answer":"この目的です。実は、この前の事業といいますか、今年度の４月まで行っておりました二世帯住宅助成という事業がございました。こちらは、昨年度の事務事業評価等々によりましていろいろな経緯を含めて庁内で検討した結果、今年度をもって廃止という形になっております。","voiceIndex":44,"id":"exchange-015"},{"speaker":"井上委員","kind":"質問","question":"その先、展開、翌年どうしていくのかとか、結果を見て進めようとするのか、これが継続した住宅政策、二世帯のほうであれば経済活性は、家を建てたり確かにあると思うんですけれども、これは民間の賃貸もオーケーと言えば、そんな経済活性もどこに生まれるんだろうという、あまりよくわからないんですけれども、この先、これをどうするのかも含めて、ただ代替だという施策なんでしょうか。","respondent":"柏原住宅担当課長、片田防災まちづくり事業部長","answer":"経済部分につきましては、建物云々の経済よりは地域の、例えば今回はマイスター店を何店か選ばせていただいたのですけれども、こちらを使っていただいて、品川区にはこんないいお店があるんですよというようなご紹介をしながら。やはり地価が高いとか、一緒に住むこと自体がなかなか難しい時代になってきていると、そういう中で、もちろん介護まで話が行けばよろしいんですけれども、やはり近くにスープの冷めない距離に住んでいただいて、今、子育て等も含めて。","voiceIndex":46,"id":"exchange-016"},{"speaker":"井上委員","kind":"意見","question":"１０万円をポイントがという、そういうふうにならないと思うし、親世帯も必要に応じてそういうことをされているので、こういうことがなくても本当に必要な人たちはそういうふうにひとり暮らしの親を呼んでいたりとか、そういうことにする中で、何かこれは親の人たちがいたりとか、そうではない人たちにとっても税金を本当に効果をねらって打つのであれば、もうちょっと違う展開なんだろうと思うんですが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":49,"id":"exchange-017"},{"speaker":"武内委員","kind":"質問","question":"一番最後のお店、２０あるんですけれども、これはどんな基準で選んだんですか。","respondent":"柏原住宅担当課長","answer":"こちらは、商店街連合会とお話しさせていただきまして、私どものコンセプトをお話しさせていただいて、マイスター店を最初は全部というお話もちょっと話はしていたんですが、三世帯で交流ができるようなお店ということをお話したところ、連合会で。","voiceIndex":51,"id":"exchange-018"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"今回の事業、これをすることによっての波及効果はいろいろあるだろうけれども、先ほどの説明ですと、主たる目的は、要するに一緒に住むと安心だと、それにこたえたいという、そういう事業だという説明なんでしょうか。もうちょっとご説明いただきたいと思ったんです。そこをどんなふうに整理をされているのか、それをどうこたえようとしているのか、そこをちょっとご説明していただきたいと思うんです。","respondent":"柏原住宅担当課長","answer":"経済的にその負担云々というよりは、やはり三世帯の交流であるとか、先ほども申し上げましたけれども、触れ合いであるとか、そういったところを深めていただくとか、そういった意味合いでつくり上げた事業です。","voiceIndex":54,"id":"exchange-019"},{"speaker":"中塚副委員長","kind":"質問","question":"確かに同居するのはちょっと、今まで長い間別々に生活していて一緒に住むのはちょっとという話もよく伺いますし、また、そうはいっても近所であれば安心するという話もよく伺いますし、そのときにいろいろお話を伺うと、例えば近所でお部屋を借りるにしても、家賃ですよね。そういうところの不安の声をよく伺うんです。とりあえず新しい事業ですから、そこの考えについてもお伺いできますか。","respondent":"柏原住宅担当課長","answer":"この事業ですべてをというふうにはちょっと考えておりませんで、この事業は、今申し上げたように相互扶助がうまく進むようにと、促進するようにということで始めた事業ですので、ただ、そういった、例えば引っ越しをするに当たってちょっと不安があるとか。","voiceIndex":56,"id":"exchange-020"}]},{"id":"topic-03","title":"大井町駅周辺地区まちづくり構想","agenda":"大井町駅周辺地区まちづくり構想","exchanges":[{"speaker":"井上委員","kind":"質問","question":"あまり詳しくないので、その辺からお聞きしたいんですけれども、今おっしゃいましたＮＰＯとの、この構想がＮＰＯが主体になっているような今の説明で、ちょっとその関係がよくわからないんですけれども、ＮＰＯだったら任意団体であって、ここのまちを代表している方たち等ではないのではないかという、一般的に言えばそうなんですけれども、その意味で。","respondent":"三宅都市開発課長","answer":"この構想のまとめるに当たりましては、これは品川区が中心に考えておりまして、決してＮＰＯ「まちづくり大井」に決めていただくという形のことではなくて、ご意見をいただいたです。","voiceIndex":63,"id":"exchange-021"},{"speaker":"井上委員","kind":"質問","question":"こういったときに、そこの皆さんが入っているＮＰＯだから、そこから意見を聞いて一緒にやっていますというものにしたいのか、そうではなくて、ちゃんとここに入っていなくてもいろいろな方がいらっしゃる、そういう人たちにもちゃんとそういう状況が与えられて意見交換の場があるのか、そこがしっかりと、たまたまメンバーがそうであったからということとは全然話が違うと思うので。","respondent":"三宅都市開発課長","answer":"そのような運用を考えておりまして、当然、今後、周知をしていくわけですけれども、必要に応じて内容の追記・変更はやっていく、そういう性格のものでございまして、これから先ほどご説明しましたように周知を図っていく中で取り入れるべきご意見をいただいた場合には。","voiceIndex":65,"id":"exchange-022"},{"speaker":"井上委員","kind":"質問・要望","question":"広くちゃんとご意見が反映できるような仕組みとして取り組んでいただきたいと思うんですが、今おっしゃった強制力がない構想であるということで、だとすれば、今、この「大井町駅周辺地区まちづくり構想」が決定稿として品川区が示しますという状況なのかどうかということと、であるならば、この構想はどういう経過をとって構想として説明するに至ったのか。","respondent":"三宅都市開発課長","answer":"ただ、その性格上、常に改善を図っていくべき性格のものであって、状況の変化もありますし、よりよい意見、上位構想は「市街地整備基本方針」というところがあって、基本的にそれに沿った内容になっていますので、さらに細かいところで書くべきことは生まれてくると思いますので。","voiceIndex":67,"id":"exchange-023"},{"speaker":"井上委員","kind":"質問","question":"ということは、その構想を決定したところの会議体はどういう会議体で、メンバー等、どういうところで示されたものなんでしょうか。","respondent":"三宅都市開発課長、片田防災まちづくり事業部長","answer":"こちらは、品川区の「市街地整備基本方針」という上位の方針に基づいた部分的な詳細計画です。したがって、その中身の決定につきましては、庁内で意思決定をしております。それを現在、今年と来年、２年かけてマスタープランの改訂を行うことで一応考えていますので、その中の個別計画という形の位置づけが出てきますので、その中でも位置づけていきたいというようことを考えてあります。","voiceIndex":69,"id":"exchange-024"},{"speaker":"井上委員","kind":"質問","question":"この構想は先ほどもおっしゃった地域の方たちに示してご意見をいただくということでしたので、どういうスケジュールで今考えられている、ここには５年から１０年のシナリオということなので、緊急ではないのかもしれないですけれども、今、これを構想ができました、議会だけではなくて区民の方、関係者の方だけではない方もすごく広い範囲なので、知っている必要があると思うんですけれども。","respondent":"三宅都市開発課長","answer":"このあたりは、またＮＰＯとの意見交換をして、スケジュール、あと方向を検討していきたいと思います。町会長も皆さん、参加いただいているので、町会を通すことは当然に当たっていきます。今考えていますのは、「広報しながわ」にも載せるような方向を考えております。","voiceIndex":72,"id":"exchange-025"},{"speaker":"井上委員","kind":"質問・要望","question":"計画が具体的になってきて初めて知ったということで、いろいろな方が具体的にならないと想像がつかないということで問題になってきますので、幾ら発信してもなかなか受け手が関心を持っていただけないということもあるかもしれませんが、十分にそういうところは大きなまちづくりなので、みんなで一緒に地域の人がかかわれるような対応をぜひ進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-026"},{"speaker":"武内委員","kind":"確認","question":"１点確認なんですけれども、スケジュールの件で、今、井上委員からもありましたけれども、３つの視点から短期、５年から１０年のシナリオにしたい、また、長期２０年のシナリオの計画を設定というようにあるんですけれども、これは先ほど防災まちづくり事業部長がおっしゃったようにマスタープランの中の個別計画に位置づける予定だということなので、そのマスタープランの今年、来年とおっしゃっていたので。","respondent":"三宅都市開発課長、片田防災まちづくり事業部長","answer":"２ページ目に言葉と図でお示ししていますけれども、これも、すぐこの５年期間でできるものと、もうちょっと長期にかかるものというふうに、今、これをまとめて表示しておりますけれども、短期的にできないものは長期にねらっていこうと。ただ、このマスタープランそのものは、短期、長期ということではなくて、いわゆる一言で言えば長期なんですけれども、２０年先、３０年先の品川区としてのまちづくりの絵柄といいますか、構想ですよね。","voiceIndex":76,"id":"exchange-027"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"もう一つ、この構想ですけれども、この構想の中で考えている、目指している規制緩和について、容積率の緩和や高度利用など、どういった規制緩和を考えていらっしゃるのかご説明いただきたいと思います。３点目が、この構想は決定したというご説明だったんですけれども、税金による補助事業を考えているのはどの地区なのか、地区名を教えていただきたい。","respondent":"三宅都市開発課長","answer":"基本的に駅に近い部分では商業機能の充実で、その外延部には業務や住宅なども含めた複合機能を導入していきたいということ、あるいは都市計画道路の整備とあわせて周りの面的なまちづくりも考えていくといった、そういう大きな方針、考え方を示しておりますので。","voiceIndex":83,"id":"exchange-028"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"裏面に基本的なまちづくりの方向性が書かれていて、どういう方向性を考えているのか伺いたいんですけれども、土地利用のところで、まちに人を呼び込み滞在性を高める、広域交通アクセスの利便性を活かしていく、都市基盤に歩行者の滞留・集散空間をつくっていく、とありますけれども、要するにほかの地域から人を呼び込められるまちを目指していこうという姿を描いていらっしゃるのか、その辺。","respondent":"山崎マスタープラン担当課長、三宅都市開発課長、片田防災まちづくり事業部長","answer":"ただいま上位計画について再度ご質問がありましたので、私からお答え申し上げます。さまざま検討している段階です。それがもし決まっていたとしても、こちらの構想の中でそういうところまでうたうものではない性格となっております。ですので、先ほどの質問の中でもどういう規制緩和とかそういうものがあるんですかというご質問ですけれども、そうではなくて。","voiceIndex":85,"id":"exchange-029"},{"speaker":"中塚副委員長","kind":"質問","question":"大枠の考え方というお話がありましたけれども、要するに人が集まるまちとして開発していきたいということなわけですよね。こういう中でこういう開発を進めれば、人が集まってくるというのをどういう見込みを持って進めているのか、ここは伺いたいと思います。もう１点一緒に伺いますけれども……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-030"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"もう１点だけ。別の角度から伺いますと、何らかの形で税金を投入する補助事業となっていく。そういうところについては、今、どういうお考えをお持ちなのかご説明いただきたいと思います。","respondent":"三宅都市開発課長","answer":"今、副委員長がおっしゃったように、人が集まるようにビルを建てるというところは考えてございません。人が集まるように、例えば土地利用で書いてあるように魅力的な商業機能ですとか文化機能というものをつくっていく。","voiceIndex":91,"id":"exchange-031"}]},{"id":"topic-04","title":"五反田駅周辺にぎわいゾーンまちづくりビジョンの策定","agenda":"五反田駅周辺にぎわいゾーンまちづくりビジョンの策定","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"先ほどの大井町に比べると、これは随分その先を行っている計画だというふうなイメージを持っているんですが、このまちづくりの実現化方策の中でこういった大きな五反田駅、ＴＯＣ、ゆうぽうとの周辺ということは、拠点の動きによって随分と時間もかかるだろうし、いろいろあると思うんですが、この計画の中で品川区がどういうふうな位置にいるのか、どういうふうな関係を持たなければ進められないのか。","respondent":"三宅都市開発課長","answer":"そのときに、この地域でにぎわい、要するに人を呼び込む拠点になっているわけですから、そこの機能継続をこうしたビジョンで地元も求めていますよというところを示しながら、まずは機能継続、そのにぎわいの拠点として存続させてくださいということ、あと。","voiceIndex":98,"id":"exchange-032"},{"speaker":"井上委員","kind":"質問","question":"その「まちづくりの基本方針」のところでは、「ビジョン（案）骨子」というふうになっているので、これは。どういうふうなスケジュールでこの「案」が取れて決定稿になっていくのかという、その先の道筋と、もう一つはゆうぽうとの周辺は、ゆうぽうとが何らかのＴＯＣのような建て替えとか、そういう時期的なものでそういう状況になっているのか、その辺の情報を教えてください。","respondent":"三宅都市開発課長","answer":"周知の方法も一緒にご相談して、一緒に地元に説明に入っていくと。それについては、今後ちょっと具体的に相談をしていくつもりです。それから、ゆうぽうとの建て替え計画ですが、こちらは特に何か具体的な動きがあるということではございません。","voiceIndex":100,"id":"exchange-033"},{"speaker":"井上委員","kind":"意見","question":"開発に向けて組合とかをつくるときには、地権者とかそれなりの権利とそういう資格を持っている方というふうになると思うんですけれども、ここの場合の「五反田地域街づくり協議会」は、任意団体として自分たちのまちを考えたいということなのか、それとも、ちゃんとした組織として品川区と対等に話をする団体か、そういう団体の位置づけなんですけれども、メンバーは何人かは書いていなくて。","respondent":"三宅都市開発課長","answer":"こちらは、何かどこかの具体的な区域で開発を考えている方の集まりではございません。広く五反田のこの地域のまちづくりを考えていこうということでできた組織です。この地域の町会長、商店会長は、皆さん、漏れなく加わっていただいております。","voiceIndex":102,"id":"exchange-034"},{"speaker":"井上委員","kind":"質問","question":"任意の団体であるということだと思うので、そういったときには、やはりそういう既存の団体を品川区がどういうふうに位置づけるかということだと思うんですけれども、そういう中で門戸を開いてたくさんの方がそこにかかわっていいですよ、みんなで一緒に考えましょう、ということなのか、もう構成メンバーは町会長と、企業と、こういうメンバーだけでここはつくるんですよということなのか。","respondent":"三宅都市開発課長","answer":"バランスよく地元の方のご意見は、この「五反田地域街づくり協議会」である程度出していただけたと考えていますが、ただ、皆さんのお考えを聞いたところまでは至っていないと思いますので、この協議会に入っていない方にも周知は必要だと。","voiceIndex":104,"id":"exchange-035"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"もう一つ、ＴＯＣの建て替え計画が予定されているとありますけれども、この「五反田駅周辺にぎわいゾーン」の中で数あるビルの中でＴＯＣをかぎとしてとらえているのか、３つの拠点の１つととらえているわけだけれども、その要素や位置づけについてご説明いただきたいと思います。","respondent":"三宅都市開発課長","answer":"建物更新の問題ですが、それぞれ建て替わっていくという中では、例えば先ほど、駅からの回遊性がちょっと不足していると認識しているわけですが、例えば１階にメーンのネットワーク、歩行者が通る動線については、両側にお店が連続したほうが。","voiceIndex":107,"id":"exchange-036"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"ＴＯＣからは何らかの要望が上がっているのか、規制緩和の手法をどう品川区は考えていらっしゃるのか、そこもご説明いただきたいと思います。先ほど、区画整理の関係で容積率が十分に機能していないというか、そういう問題がありましたけれども、ＴＯＣからの要望、あと品川区で今どういう規制緩和の手法を考えているのかご説明いただきたいと思います。","respondent":"三宅都市開発課長","answer":"規制緩和についてですが、このあたりは、まださまざまな方法を検討している段階でございまして、具体的にどの手法というところには至っておりません。複合市街地ゾーンのところ全体を１区画というところで大きくは何かその開発をするというところは考えておりません。","voiceIndex":109,"id":"exchange-037"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"それはいつまで待つのか、そういう期限があるのか、そこはどう考えているのか、そこの考えについてご説明いただきたいと思います。そして、もう一つ、道路の反対側に旧第一日野小学校の暫定活用が今続いておりますけれども、このことと、この「五反田駅周辺にぎわいゾーン」のこのまちづくりビジョンの策定は、何か関係があるのか、そこをどう見ているのか、ご説明いただけますか。","respondent":"三宅都市開発課長","answer":"具体的なＴＯＣの建て替えの時期ですとかその辺については、ＴＯＣとしても早くやりたいという思いはおそらくあるんでしょうけれども、まだ今の段階では、さまざまな都市計画手法も含めて内部検討が主になっている段階ですので。","voiceIndex":111,"id":"exchange-038"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"ここに書かれていることはＴＯＣのところがポイントだと言いながら、一方でＴＯＣが動かなければ動かないという、そういう関係にあるのか、いつまで待つのかという話も、要するに相手頼みという、そういう、今、状況にあるのか、そこがよく見えてこないので、もう一度ご説明いただきたいんです。","respondent":"片田防災まちづくり事業部長","answer":"ですので、ＴＯＣがもしそういう建て替えを進めるという段階になってくれば、品川区としてもそういう全体的な方針に基づいて逆に指導していくという立場にありますので、今、ここの中でのＴＯＣがどうのとか、ゆうぽうとがどうのこうのとか、そういうことではなくて、ただ。","voiceIndex":113,"id":"exchange-039"},{"speaker":"中塚副委員長","kind":"意見","question":"２つ目のご説明がよく本当にわからなかったので、要するに旧第一日野小学校とそれは関係がないというお話があったんですね。だけれども、この開発のことと関係がないというのか、でも、今のご説明だと、今後の動向によって位置づけが変わることもあるという話だった。そこをちょっとご説明いただけますか。","respondent":"片田防災まちづくり事業部長","answer":"直接、旧第一日野小学校のほうとの関係はございません。このまちづくりビジョンとは関係はございません。","voiceIndex":116,"id":"exchange-040"}]},{"id":"topic-05","title":"大井町西地区市街地再開発事業の状況","agenda":"大井町西地区市街地再開発事業の状況","exchanges":[{"speaker":"井上委員","kind":"質問","question":"余計だと思うんですけれども、この黄色い部分のところは、同じフロアではどういうものが入るのか、そういう情報はあるんでしょうか。","respondent":"三宅都市開発課長","answer":"このあたりは、まだ組合内部でのいろいろな権利者が戻るところをどこにするかとか、あと、テナントとしてどういうところを入ってもらおうか、誘致しようかというようなことをやっているところでございまして。","voiceIndex":123,"id":"exchange-041"},{"speaker":"武内委員","kind":"質問・要望","question":"こういう形で無償で申し出があったという、もうちょっと経緯を教えていただきたい。いわゆる品川区から何か暗にお出ししたのか、あと、今まで再開発でやはりこういう形で同じようなケースがあるんでしょうか。","respondent":"三宅都市開発課長","answer":"大井町西地区につきましても、品川区としましても共同化、こちらの地権者が力を合わせて再開発をやるということで支援などもしておりますので、そういう、広く税金を投入していただいているというようなところから組合としても何か貢献できないかというところで。","voiceIndex":126,"id":"exchange-042"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"無償譲渡で認可保育園の設置となるわけだけれども、この床についてどう使うというのは品川区の判断ということでいいのか、それとも、再開発組合から例えばどんなふうにという言い方なのかよくわからないですけれども、何か要望というか、そういう関係はあるのか、そこをまずご説明いただきたいと思います。それと、無償譲渡は無償譲渡ですけれども、１１４坪という結構大きい床ですよね。","respondent":"三宅都市開発課長","answer":"２点目なんですが、基礎床の面積に応じた一権利者といいますか、権利を持って将来にわたって皆さんと一緒に維持管理をしていくということです。","voiceIndex":129,"id":"exchange-043"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"それが１つの商業スペースの中で行われるわけですよね。そこをご説明いただきたいと思います。店舗は、入居が決まっていないけれども、もともとはあそこは商店街だったわけですから、そことの関係で、今、どういう事業としての進みぐあいなのか、そこもちょっとご説明いただけますか。","respondent":"三宅都市開発課長","answer":"ですから、おおむねこういう用途というのはありますけれども、まだそれはちょっと外にお知らせする段階ではないということでご理解いただきたいと思います。最終的に残る方ですが、今のところ約６０人、組合員になっておりますので、戻る方は大体そのぐらいです。","voiceIndex":131,"id":"exchange-044"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"先ほど伺ったのは、保育園の隣がどういう業態になるのか、やはり人が行き交うわけですよね、お子さんも、職員も、あといろいろ食材を納入する業者も含めて。そういう関係で、いや、隣は隣で何でもいいんですよという、そういう考えなのか、それとも一定、何か考えや、ルールや、何かもう議論があるのか、そこがご説明にはなかったので、そこをご説明していただきたいと思います。","respondent":"三宅都市開発課長、片田防災まちづくり事業部長","answer":"当然、お隣の区画の方も、ある程度こういう、こちら側の考えは聞いた上で、そこの区画をとって考えている業態で支障はないかという検討もいただいております。例えば保育園であれば、２階からおりてきて、どちらかというと東側に出るようなルートになってありますので、所管のほうとしても間仕切りというか、隣が例えば２階の部分の保育園の隣がどういう用途になるかはちょっとあれですけれども。","voiceIndex":133,"id":"exchange-045"}]},{"id":"topic-06","title":"(6)東日本大震災に伴う道路事業等への影響","agenda":"(6)東日本大震災に伴う道路事業等への影響","exchanges":[{"speaker":"武内委員","kind":"質問","question":"電線・電柱を地中化していって、大きな震災のときにも倒れてこないように非常に安全でいいと思うんですけれども、逆に今度地下に入れるということで、今まで、今回は影響なかったと思うんですけれども、いわゆる中の耐震化というんですか、地面の中で管がおかしくなっていたりすると、元も子もないと思うので、その辺は、今回の東日本を踏まえて大丈夫だということで進んでいるということで。","respondent":"藤橋都市整備下水道課長","answer":"その阪神・淡路大震災の対応を踏まえて現在設計されておりますので、その地下に埋めた点検用のボックス、それから管も含めまして耐震性能を高めたもので施工されておりますので、現時点では被害があると、そういったことは考えておりません。","voiceIndex":142,"id":"exchange-046"},{"speaker":"中塚副委員長","kind":"意見","question":"住民への説明について、先ほど機会をとらえて説明したいというお話でしたけれども、どういう方法を考えていらっしゃるのか、またちょっとご説明ください。","respondent":"藤橋都市整備下水道課長","answer":"これまでの事業化に当たりましては、地域の方々も交えました住民説明会を行ってきておりまして、今回、この状況報告という形でまた同じような住民説明会、あるいは町会長との会合等で説明していく予定です。","voiceIndex":145,"id":"exchange-047"},{"speaker":"松澤委員","kind":"質問","question":"この件ではないんですけれども、ここに書いていないんですけれども、補助２６号線などはどうなんですか。わかりますか。","respondent":"松代都市計画課長","answer":"そのＪＲ東日本が次の施工段階で業者を近々決めるというように聞いておりまして、その業者が決まり次第、施工方法等を再度詰めて、地元に説明に入りたいと。この時期はまだ示されておりません。こういった状況が今の現状の状況です。","voiceIndex":148,"id":"exchange-048"}]},{"id":"topic-07","title":"国文学研究資料館跡地内建物解体工事","agenda":"国文学研究資料館跡地内建物解体工事","exchanges":[{"speaker":"中塚副委員長","kind":"質問","question":"解体した後はどんな公園になるんですか。既にもう説明があったのかもしれないけれども、ちょっとその辺のところがよくわからないのでご説明いただけますか。","respondent":"藤橋都市整備下水道課長","answer":"公園整備計画につきましては、これまでパブリックコメント、それから地域住民とこの説明会も通じまして平成２２年８月に説明しています。","voiceIndex":155,"id":"exchange-049"}]},{"id":"topic-08","title":"では３の行政視察についてでございますが、本件は関係理事者のみお残りいただく予定でございますので、順番を入れ替えまして、予定表の４、その他を先に行います。 まず","agenda":"では３の行政視察についてでございますが、本件は関係理事者のみお残りいただく予定でございますので、順番を入れ替えまして、予定表の４、その他を先に行います。 まず","exchanges":[{"speaker":"中塚副委員長","kind":"質問・要望","question":"きのうご質問したとおりなんですけれども、本会議での答弁で高層住宅についての答弁が、区は情報収集に努め、対策に必要な検討を行うというご答弁がありました。質問は、現時点で課題や問題意識は何か、どのように考えていらっしゃるのかご説明をいただきたいと思います。","respondent":"中山防災課長、高山防災計画担当課長","answer":"そういった中で最終的には管理組合や自治会が責任を持って自分のマンションは自分が守るという形に考えていくのがこれからの課題だと考えています。区としましては、こうした対策を着実に進めていくとともに、引き続き情報収集に努め、対策について必要な検討を行ってまいります。","voiceIndex":164,"id":"exchange-050"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"手元の資料についてちょっと伺いたいと思うんですけれども、この対策について、このものは現行の計画を説明したものなのか、それとも今回の大震災を経験して、その教訓とすべきもの、学ぶべきものは学んでいきたいという、事務事業概要にもありましたけれども、今回の震災を経験して、今時点で新たに問題意識や解決すべき問題と考えているものが何なのか、そこについても伺いたい。","respondent":"高山防災計画担当課長","answer":"ご質問にお答えします。この対策の柱ですが、基本としましては、現在の現行の計画を説明したものです。本震災の教訓として何か反映しているものはあるのかという点ですが、やはり基本的な取り組みとしましては、こういったものでかなり網羅されているものかと思います。","voiceIndex":168,"id":"exchange-051"},{"speaker":"中塚副委員長","kind":"確認","question":"つまり、電気、ガス、水道がどう復旧するかによるわけですよね。それはどんなふうに考えていらっしゃるのか伺いたいと思います。ここを確認したいと思うんですけれども、ライフライン被害が起きて、建物は残っているけれどもそこで避難生活が維持できるのかというのが私自身の問題意識なんです。そこについて、よく対策を考える必要があるのではないかと思うんですけれども、いかがでしょうか。","respondent":"片田防災まちづくり事業部長","answer":"いろいろほかの区の状況などを聞いたりいたしますと、港区等のある某マンションなどでは、万が一大地震が起こったときに、１階の部分に皆さんが集まって、例えば各フロアごと、５層分ぐらいのフロアごとにコミュニティをつくっていただいて、それぞれの安否確認をして。","voiceIndex":170,"id":"exchange-052"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"今回の機会を受けて一定のマニュアルづくりが必要ではないかというお話がありました。改めてそこの問題意識を伺いたいと思います。やはりそういうところについても、解決すべき問題をしっかり整理して対策に反映していくという方向が必要だと思うんですけれども、今後の方向についてもう一度ご説明をいただきたいと思います。","respondent":"高山防災計画担当課長、片田防災まちづくり事業部長","answer":"ちょっと古いデータではありますが、首都直下型地震による東京の被害想定報告書によりますと、電力については６日で完全復旧、ガスについては５３日、上水道については３０日で復旧といったデータがあります。それとあと、エレベーターについては、確かに地震によってワイヤーの問題とかありますけれども、基本的には特に高層住宅、特に超高層なども含めてですけれども。","voiceIndex":172,"id":"exchange-053"},{"speaker":"中塚副委員長","kind":"確認","question":"しかも、同時多発的に起きるわけですから、会社だってどこまで受けるのか、そういう問題についてもしっかり課題ととらえて対応していく、今後の計画に反映させていくという、そういう視点が必要ではないかと思うんですけれども、いかがでしょうか。","respondent":"片田防災まちづくり事業部長、岩田都市環境事業部長","answer":"ただ、いろいろな制御装置のふぐあいで、過去、シンドラーのエレベーターとかいろいろな事件がありましたけれども、そういう支障があるにしても、停電についても、当然、そういう形での復旧に対してインフラが復旧できるような状況。ご質問は、今、計画論の話ですけれども、東京電力は大体１週間程度で復旧すると、これは仮説の復旧なんですけれども、復旧するという計画に一応なっていますけれども、実際にはそれ以上かかるかもしれませんし。","voiceIndex":175,"id":"exchange-054"},{"speaker":"武内委員","kind":"質問","question":"このエレベーター閉じ込め防止装置というのは、自動着床装置のことですか。","respondent":"中村建築課長","answer":"そのとおりです。一定以上の震動が起きたときに、最寄りの階にとまる着床装置のことです。","voiceIndex":178,"id":"exchange-055"},{"speaker":"井上委員","kind":"確認","question":"働きかけていました、結果やりませんでしたということよりも、ある程度区の避難所の関係もあるので、自己責任としてそういうところに設置を以前にも質問して、義務づけるのはなかなか難しいという区長の答弁もありましたけれども、そうは言っていられないでしょうという実感もあるので、その辺についてどういうふうに強くやって対策をとっていくのかということ、３点お伺いします。","respondent":"中村建築課長、片田防災まちづくり事業部長","answer":"公共施設のエレベーターの状況ですが、こちら、エレベーターという構造のものが、もうできたときから地震に対するそういった想定はされておりますので。それとあと備蓄の働きかけなんですけれども、先ほど申し上げましたように、東京都もたしかそういう備蓄倉庫をこれから設置するような場合には。","voiceIndex":182,"id":"exchange-056"},{"speaker":"井上委員","kind":"意見","question":"「防止装置の設置を努める」という、その表記もおかしいし、「防止装置の設置を促進する」ともう義務づけてあるのであれば、「促進する」以前の問題で、つけていなければ違反になるわけですよね。この辺の表記の仕方が間違えたのか、今、現状、どういうことになるのか、ちょっと整理をしてください。","respondent":"片田防災まちづくり事業部長","answer":"ここの表記については、平成１９年度の地域防災計画の、ページは記載してございませんけれども、それを横引きしてきたところの資料ですので、現時点での品川区としてのエレベーター対策とか、備蓄の考え方とか、安全対策については、これに示すとおりなんですけれども。","voiceIndex":186,"id":"exchange-057"},{"speaker":"井上委員","kind":"確認","question":"防止装置はもう設置が義務づけられている、法が確立している、ということでいいんですねということで確認と、あと、先ほど家具転倒防止が構造的なアドバイスを含めるとか、それはわかりましたということと、住民の方はどういうふうなアプローチでそのアドバイスを受けられるのかということが周知されないと、だれに聞いていいかわからない。","respondent":"中山防災課長","answer":"今回、１５０名ぐらいの参加ですから、もう７００名ぐらいの方が各町会に散らばっているですので、その方の指導を受けるということにしていますし、また、総合防災訓練、秋にやってありますけれども、そこにも家具転倒防止を一式持っていって、啓発に努めているところです。","voiceIndex":188,"id":"exchange-058"},{"speaker":"井上委員","kind":"質問・要望","question":"アドバイザー研修を受けた人が７００人いることはわかりました。では、その人たちはだれですかということが区民の方にわからなければ、本人が知識を持っているというだけではない、そういったときに啓発をしていただきたいという目的があるのなら、そういう方がわからないといけないんですが、そういうことがわかるような仕組みになっているのでしょうか。","respondent":"中山防災課長、片田防災まちづくり事業部長","answer":"地域の防災リーダーとなっていただくよう受講をお願いしているわけです。そのためにスタッフジャンパー等を配ってありますし、それから、町会の推薦で来ておられますので、そこで周知はされていると考えております。八潮などではそういう自治会としてのきちっとした体制をとられていると聞いてありますけれども、やはりそういう方々に対しても、マンション管理の講習・セミナーとか、そういう機会を通して。","voiceIndex":190,"id":"exchange-059"},{"speaker":"井上委員","kind":"意見","question":"リーダーとかアドバイザー研修を受けた人たちがどこでどういうふうに自分たちはその技術とか知識を提供できるんだろうというふうに思っている方たちも多いと思いますので、それを受けたら出すほうをしていかないといけないので、その辺の検討をよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":193,"id":"exchange-060"}]},{"id":"topic-09","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"武内委員","kind":"意見","question":"私は、自転車関係、今回、所管事務調査にもありますけれども、その中で例えば長野県の松本市にある、ほかでもやっていますけれども、全小学校で自転車の免許証、大分前からいろいろな自治体でやっていますけれども、そういったものを取り組み出しているということで、例えばそういった安全対策、そうした観点からどうかなと。幾つかありましたが、一つの意見として。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":204,"id":"exchange-061"},{"speaker":"井上委員","kind":"意見","question":"川の浄化で北海道に行ってもなかなか難しかったし、駅前再開発も全然規模も違うしというところで言えば、自転車の共同システムなどだと、参考になるかもしれないんですが、だったら、２３区で共同システムをしている、そういう状況が同じようなところに、ちょっと導入とか、失敗例とか、そういったところの参考なのかなと思うので、遠出を考えなくても、本当に住環境が同じような。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":206,"id":"exchange-062"},{"speaker":"中塚副委員長","kind":"質問","question":"所管事務調査のところでなかなか少し議論ができなかったんですけれども、建設委員会でそれぞれ問題意識を出し合ってやることが大事だと思うので、ぜひいろいろテーマについて、あと、その取り組むべき、調査すべき角度とか、問題意識とか、それぞれ委員のお考えを出していただけると大変運営しやすいんですけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":208,"id":"exchange-063"},{"speaker":"大沢委員","kind":"質問","question":"正副でまとめていただいたらいいと思いますが、いかがでしょうか。正副でまとめてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":209,"id":"exchange-064"},{"speaker":"武内委員","kind":"質問","question":"調査項目、また場所が決まった段階で、先方のご都合もあるでしょうから、それを考慮していただいて、どちらでも私は可能なほうで結構だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":212,"id":"exchange-065"},{"speaker":"大沢委員","kind":"質問・要望","question":"日程も考慮しながら正副委員長で決めていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":213,"id":"exchange-066"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4010#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":58695,"voices":214}}]);
